comms.text:
@1 וַהֲוָה בְּיוֹמָא תְמִינָאָה קְרָא משֶׁה לְאַהֲרֹן וְלִבְנוֹהִי וּלְסָבֵי יִשְׂרָאֵל:
@2 וַאֲמַר לְאַהֲרֹן סַב לָךְ עֶגַל בַּר תּוֹרֵי לְחַטָּאתָא וּדְכַר לַעֲלָתָא שַׁלְמִין וְקָרֵב קֳדָם יְיָ:
@3 וְעִם בְּנֵי יִשְׂרָאֵל תְּמַלֵּל לְמֵימָר סִיבוּ צְפִיר בַּר עִזִּין לְחַטָּאתָא וְעֵגָל וְאִמָּר בְּנֵי שְׁנָא שַׁלְמִין לַעֲלָתָא:
@4 וְתוֹר וּדְכָר לְנִכְסַת קוּדְשַׁיָּא לְדַבָּחָא קֳדָם יְיָ וּמִנְחָתָא דְּפִילָא בִמְשָׁח אֲרֵי יוֹמָא דֵין יְקָרָא דַיְיָ מִתְגְּלִי לְכוֹן:
@5 וּנְסִיבוּ יָת דִּי פַקִּיד משֶׁה לָקֳדָם מַשְׁכַּן זִמְנָא וּקְרִיבוּ כָּל כְּנִשְׁתָּא וְקָמוּ קֳדָם יְיָ:
@6 וַאֲמַר משֶׁה דֵּין פִּתְגָּמָא דִּי פַקִּיד יְיָ תַּעְבְּדוּן וְיִתְגְּלִי לְכוֹן יְקָרָא דַיְיָ:
@7 וַאֲמַר משֶׁה לְאַהֲרֹן קְרַב לְמַדְבְּחָא וְעִבֵד יָת חַטָּאתָךְ וְיָת עֲלָתָךְ וְכַפַּר עֲלָךְ וְעַל עַמָּא וְעִבֵד יָת קֻרְבַּן עַמָּא וְכַפַּר עֲלֵיהוֹן כְּמָא דִי פַּקִּיד יְיָ:
@8 וּקְרֵב אַהֲרֹן לְמַדְבְּחָא וּנְכֵס יָת עֶגְלָא דְחַטָּאתָא דִּי לֵיהּ:
@9 וְקָרִיבוּ בְּנֵי אַהֲרֹן יָת דְּמָא לֵיהּ וּטְבַל אֶצְבְּעֵיהּ בִּדְמָא וִיהַב עַל קַרְנַת מַדְבְּחָא וְיָת דְּמָא אֲרִיק לִיסוֹדָא דְמַדְבְּחָא:
@10 וְיָת תַּרְבָּא וְיָת כָּלְיְתָא וְיָת חִצְרָא מִן כַּבְדָּא מִן חַטָּאתָא אַסֵּק לְמַדְבְּחָא כְּמָא דִי פַּקִּיד יְיָ יָת משֶׁה:
@11 וְיָת בִּשְׂרָא וְיָת מַשְׁכָּא אוֹקִיד בְּנוּרָא מִבָּרָא לְמַשְׁרִיתָא:
@12 וּנְכֵס יָת עֲלָתָא וְאַמְטִיאוּ בְּנֵי אַהֲרֹן לֵיהּ יָת דְּמָא וּזְרָקֵיהּ עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@13 וְיָת עֲלָתָא אַמְטִיאוּ לֵיהּ לְאֵבָרָהָא וְיָת רֵישָׁא וְאַסֵּק עַל מַדְבְּחָא:
@14 וְחַלִּיל יָת גַּוָּא וְיָת כְּרָעַיָּא וְאַסֵּק עַל עֲלָתָא לְמַדְבְּחָא:
@15 וְקָרֵב יָת קֻרְבַּן עַמָּא וּנְסִיב יָת צְפִירָא דְחַטָּאתָא דִּי לְעַמָּא וְנָכְסֵיהּ וְכַפֵּר בִּדְמֵיהּ כְּקַדְמָאָה:
@16 וְקָרֵב יָת עֲלָתָא וְעָבְדַהּ כִּדְחָזֵי:
@17 וְקָרֵב יָת מִנְחָתָא וּמְלָא יְדֵיהּ מִנַּהּ וְאַסֵּק עַל מַדְבְּחָא בַּר מֵעֲלַת צַפְרָא:
@18 וּנְכֵס יָת תּוֹרָא וְיָת דִּכְרָא נִכְסַת קוּדְשַׁיָּא דִּי לְעַמָּא וְאַמְטִיאוּ בְּנֵי אַהֲרֹן יָת דְּמָא לֵיהּ וּזְרָקֵיהּ עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@19 וְיָת תַּרְבַּיָּא מִן תּוֹרָא וּמִן דִּכְרָא אֲלִיתָא וְחָפֵי גַוָּא וְכָלְיְתָא וַחֲצַר כַּבְדָּא:
@20 וְשַׁוִּיאוּ יָת תַּרְבַּיָּא עַל חֶדְוָתָא וְאַסֵּק תַּרְבַּיָּא לְמַדְבְּחָא:
@21 וְיָת חֶדְוָתָא וְיָת שׁוֹקָא דְיַמִּינָא אֲרֵם אַהֲרֹן אֲרָמָא קֳדָם יְיָ כְּמָא דִי פַּקִּיד משֶׁה:
@22 וַאֲרֵם אַהֲרֹן יָת יְדוֹהִי עַל עַמָּא וּבָרֵכִנּוּן וּנְחַת מִלְּמֶעְבַּד חַטָּאתָא וַעֲלָתָא וְנִכְסַת קוּדְשַׁיָּא:
@23 וְעַל משֶׁה וְאַהֲרֹן לְמַשְׁכַּן זִמְנָא וּנְפָקוּ וּבָרִיכוּ יָת עַמָּא וְאִתְגְּלִי יְקָרָא דַיְיָ לְכָל עַמָּא:
@24 וּנְפָקַת אֶשָּׁתָא מִן קֳדָם יְיָ וַאֲכָלַת עַל מַדְבְּחָא יָת עֲלָתָא וְיָת תַּרְבַּיָּא וַחֲזָא כָּל עַמָּא וְשַׁבָּחוּ וּנְפָלוּ עַל אַפֵּיהוֹן:
@25 וּנְסִיבוּ בְנֵי אַהֲרֹן נָדָב וַאֲבִיהוּא גְּבַר מַחְתִּיתֵיהּ וִיהָבוּ בְהוֹן אֶשָּׁתָא וְשַׁוִּיאוּ עֲלַהּ קְטוֹרֶת וְקָרִיבוּ קֳדָם יְיָ אֶשָּׁתָא נוּכְרֵיתָא דִּי לָא פַּקִּיד יָתְהוֹן:
@26 וּנְפָקַת אֶשָּׁתָא מִן קֳדָם יְיָ וַאֲכָלַת יָתְהוֹן וּמִיתוּ קֳדָם יְיָ:
@27 וַאֲמַר משֶׁה לְאַהֲרֹן הוּא דִי מַלִּיל יְיָ לְמֵימַר בְּקָרִיבַי אִתְקַדַּשׁ וְעַל אַפֵּי כָל עַמָּא אִתְיַקָּר וּשְׁתִיק אַהֲרֹן:
@28 וּקְרָא משֶׁה לְמִישָׁאֵל וּלְאֶלְצָפָן בְּנֵי עֻזִּיאֵל אַח אֲבוּהִי דְאַהֲרֹן וַאֲמַר לְהוֹן קְרִיבוּ טוּלוּ יָת אֲחוּכוֹן מִן קֳדָם אַפֵּי קוּדְשָׁא לְמִבָּרָא לְמַשְׁרִיתָא:
@29 וּקְרִיבוּ וּנְטָלֻנּוּן בְּכִתֻּנֵּיהוֹן לְמִבָּרָא לְמַשְׁרִיתָא כְּמָא דִי מַלִּיל משֶׁה:
@30 וַאֲמַר משֶׁה לְאַהֲרֹן וּלְאֶלְעָזָר וּלְאִיתָמָר בְּנוֹהִי רֵישֵׁיכוֹן לָא תְרַבּוּן פֵּרוּעַ וּלְבוּשֵׁיכוֹן לָא תְבַזְּעוּן וְלָא תְמוּתוּן וְעַל כָּל כְּנִשְׁתָּא יְהֵי רוּגְזָא וַאֲחֵיכוֹן כָּל בֵּית יִשְׂרָאֵל יִבְכּוּן יָת יְקִדְתָּא דִּי אוֹקִיד יְיָ:
@31 וּמִתְּרַע מַשְׁכַּן זִמְנָא לָא תִפְּקוּן דִּילְמָא תְמוּתוּן אֲרֵי מְשַׁח רְבוּתָא דַיְיָ עֲלֵיכוֹן וַעֲבָדוּ כְּפִתְגָּמָא דְמשֶׁה:
@32 וּמַלִּיל יְיָ לְאַהֲרֹן לְמֵימָר:
@33 חֲמַר וּמְרַוֵּי לָא תִשְׁתֵּי אַתְּ וּבְנָיךְ עִמָּךְ בְּמֵעַלְכוֹן לְמַשְׁכַּן זִמְנָא וְלָא תְמוּתוּן קְיַם עָלָם לְדָרֵיכוֹן:
@34 וּלְאַפְרָשָׁא בֵּין קוּדְשָׁא וּבֵין חֻלָּא וּבֵין מְסָאָבָא וּבֵין דַּכְיָא:
@35 וּלְאַלָּפָא יָת בְּנֵי יִשְׂרָאֵל יָת כָּל קְיָמַיָּא דִּי מַלִּיל יְיָ לְהוֹן בִּידָא דְמשֶׁה:
@36 וּמַלִּיל משֶׁה עִם אַהֲרֹן וְעִם אֶלְעָזָר וְעִם אִיתָמָר בְּנוֹהִי דְּאִשְׁתָּאֲרוּ סִיבוּ יָת מִנְחָתָא דְאִשְׁתָּאָרַת מִקֻּרְבָּנַיָּא דַיְיָ וְאִכְלוּהָ פַטִּיר בִּסְטַר מַדְבְּחָא אֲרֵי קֹדֶשׁ קוּדְשִׁין הִיא:
@37 וְתֵיכְלוּן יָתַהּ בַּאֲתַר קַדִּישׁ אֲרֵי חֳלָקָךְ וָחֳלַק בְּנָיךְ הִיא מִקֻּרְבָּנַיָּא דַּיְיָ אֲרֵי כֵן אִתְפַּקָּדִית:
@38 וְיָת חֶדְיָא דַאֲרָמוּתָא וְיָת שׁוֹקָא דְאַפְרָשׁוּתָא תֵּיכְלוּן בַּאֲתַר דְּכֵי אַתְּ וּבְנָיךְ וּבְנָתָיךְ עִמָּךְ אֲרֵי חֳלָקָךְ וָחֳלַק בְּנָיךְ אִתְיְהִבוּ מִנִּכְסַת קוּדְשַׁיָּא דִּבְנֵי יִשְׂרָאֵל:
@39 שׁוֹקָא דְאַפְרָשׁוּתָא וְחֶדְיָא דַאֲרָמוּתָא עַל קֻרְבָּנֵי תַרְבַּיָּא יַיְתוּן לַאֲרָמָא אֲרָמָא קֳדָם יְיָ וִיהֵי לָךְ וְלִבְנָיךְ עִמָּךְ לִקְיַם עָלָם כְּמָא דִי פַּקִּיד יְיָ:
@40 וְיָת צְפִירָא דְחַטָּתָא מִתְבַּע תָּבְעֵי משֶׁה וְהָא אִתּוֹקָד וּרְגֵז עַל אֶלְעָזָר וְעַל אִיתָמָר בְּנֵי אַהֲרֹן דְּאִשְׁתָּאָרוּ לְמֵימָר:
@41 מָדֵין לָא אֲכַלְתּוּן יָת חַטָּאתָא בַּאֲתַר קַדִּישׁ אֲרֵי קֹדֶשׁ קוּדְשִׁין הִיא וְיָתַהּ יָהֵב לְכוֹן לְסַלָּחָא עַל חוֹבֵי כְנִשְׁתָּא לְכַפָּרָא עַלֵיהוֹן קֳדָם יְיָ:
@42 הָא לָא אִתָּעַל יָת דְּמַהּ לְבֵית קֻדְשָׁא גַּוָּאָה מֵיכַל תֵּיכְלוּן יָתַהּ בְּקֻדְשָׁא כְּמָא דִי פַקֵּדִית:
@43 וּמַלִּיל אַהֲרֹן עִם משֶׁה הָא יוֹמָא דֵין קָרִיבוּ יָת חַטָּאתְהוֹן וְיָת עֲלָתְהוֹן קֳדָם יְיָ וַעֲרָעָא יָתִי עָקָן כְּאִלֵּין וְאִלּוּפוֹן אֲכָלִית חַטָּאתָא יוֹמָא דֵין הֲתַקֵּן קֳדָם יְיָ:
@44 וּשְׁמַע משֶׁה וּשְׁפַר בְּעֵינוֹהִי:
@45 וּמַלִּיל יְיָ עִם משֶׁה וּלְאַהֲרֹן לְמֵימַר לְהוֹן:
@46 מַלִּילוּ עִם בְּנֵי יִשְׂרָאֵל לְמֵימָר דָּא חַיְתָא דִּי תֵיכְלוּן מִכָּל בְּעִירָא דִּי עַל אַרְעָא:
@47 כָּל דִּי סְדִיקָן פַּרְסָתָא וּמַטִּלְפָן טִלְפִין פַּרְסָתָא מַסְּקָא פִשְׁרָא בִּבְעִירָא יָתַהּ תֵּיכְלוּן:
@48 בְּרַם יָת דֵּין לָא תֵיכְלוּן מִמַּסְּקֵי פִשְׁרָא וּמִמַּסְדִּיקֵי פַּרְסָתָא יָת גַּמְלָא אֲרֵי מַסִּיק פִּשְׁרָא הוּא וּפַרְסָתָא לָא סְדִיקָא מְסָאָב הוּא לְכוֹן:
@49 וְיָת טַפְזָא אֲרֵי מַסִּיק פִּשְׁרָא הוּא וּפַרְסָתָא לָא סְדִיקָא מְסָאָב הוּא לְכוֹן:
@50 וְיָת אַרְנְבָא אֲרֵי מַסְּקָא פִשְׁרָא הִיא וּפַרְסָתָא לָא סְדִיקָא מְסָאָבָא הִיא לְכוֹן:
@51 וְיָת חֲזִירָא אֲרֵי סְדִיק פַּרְסָתָא הוּא וּמַטִּילְפָן טִלְפִין פַּרְסָתֵיהּ וְהוּא פִּשְׁרָא לָא פָשָׁר מְסָאָב הוּא לְכוֹן:
@52 מִבִּסְרְהוֹן לָא תֵיכְלוּן וּבִנְבִלְתְּהוֹן לָא תִקְרְבוּן מְסַאֲבִין אִנּוּן לְכוֹן:
@53 יָת דֵּין תֵּיכְלוּן מִכָּל דִּי בְמַיָּא כֹּל דִּי לֵיהּ צִיצִין וְקַלְפִין בְּמַיָּא בְּיָמְמַיָּא וּבְנַחֲלַיָּא יָתְהוֹן תֵּיכְלוּן:
@54 וְכֹל דִּי לֵית לֵיהּ צִיצִין וְקַלְפִין בְּיַמְמַיָּא וּבְנַחֲלַיָּא מִכֹּל רִחֲשָׁא דְמַיָּא וּמִכָּל נַפְשָׁא חַיְתָא דִּי בְמַיָּא שִׁקְצָא אִנּוּן לְכוֹן:
@55 וְשִׁקְצָא יְהוֹן לְכוֹן מִבִּסְרְהוֹן לָא תֵיכְלוּן וְיָת נְבִלְתְּהוֹן תְּשַׁקְּצוּן:
@56 כֹּל דִּי לֵית לֵיהּ צִיצִין וְקַלְפִין בְּמַיָּא שִׁקְצָא הוּא לְכוֹן:
@57 וְיָת אִלֵּין תַּשַׁקְּצוּן מִן עוֹפָא לָא יִתְאַכְלוּן שִׁקְצָא אִנּוּן נִשְׁרָא וְעַר וְעַזְיָא:
@58 וְדַיְתָא וְטָרָפִיתָא לִזְנַהּ:
@59 יָת כָּל עוּרְבָא לִזְנֵיהּ:
@60 וְיָת בַּת נַעֲמִיתָא וְצִיצָא וְצִפַּר שַׁחְפָּא וְנָצָא לִזְנוֹהִי:
@61 וְקַרְיָא וְשָׁלֵינוּנָא וְקִפּוֹפָא:
@62 וּבַוְתָא וְקָאתָא וִירַקְרֵקָא:
@63 וְחַוָּרִיתָא וְאִבּוּ לִזְנַהּ וְנַגַּר טוּרָא וַעֲטַלֵּפָא:
@64 כֹּל רִחֲשָׁא דְעוֹפָא דִּמְהַלֵּךְ עַל אַרְבַּע שִׁקְצָא הוּא לְכוֹן:
@65 בְּרַם יָת דֵּין תֵּיכְלוּן מִכֹּל רִחֲשָׁא דְעוֹפָא דִּמְהַלֵּךְ עַל אַרְבַּע דִּי לֵיהּ קַרְצוּלִין מֵעִלָּוֵי רַגְלוֹהִי לְקַפָּצָא בְהוֹן עַל אַרְעָא:
@66 יָת אִלֵּין מִנְּהוֹן תֵּיכְלוּן יָת גּוֹבָא לִזְנַהּ וְיָת רָשׁוּנָא לִזְנוֹהִי וְיָת חַרְגּוֹלָא לִזְנוֹהִי וְיָת חֲגָבָא לִזְנוֹהִי:
@67 וְכֹל רִחֲשָׁא דְעוֹפָא דִּי לֵיהּ אַרְבַּע רַגְלִין שִׁקְצָא הוּא לְכוֹן:
@68 וּלְאִלֵּין תִּסְתָּאָבוּן כָּל דְּיִקְרַב בִּנְבִלְתְּהוֹן יְהֵי מְסָאָב עַד רַמְשָׁא:
@69 וְכָל דְּיִטוֹל מִנְּבִלְתְּהוֹן יְצַבַּע לְבוּשׁוֹהִי וִיהֵי מְסָאָב עַד רַמְשָׁא:
@70 לְכָל בְּעִירָא דִּי הִיא סְדִיקָא פַרְסָתָא וְטִלְפִין לֵיתָהָא מַטִּלְפָא וּפִשְׁרָא לֵיתָהָא מַסְּקָא מְסַאֲבִין אִנּוּן לְכוֹן כָּל דְּיִקְרַב בְּהוֹן יְהֵי מְסָאָב:
@71 וְכֹל דִּמְהַלֵּךְ עַל יְדוֹהִי בְּכָל חַיְתָא דִּמְהַלְכָא עַל אַרְבַּע מְסַאֲבִין אִנּוּן לְכוֹן כָּל דְּיִקְרַב בִּנְבִלְתְּהוֹן יְהֵי מְסָאָב עַד רַמְשָׁא:
@72 וּדְיִטּוֹל יָת נְבִלְתְּהוֹן יְצַבַּע לְבוּשׁוֹהִי וִיהֵי מְסָאָב עַד רַמְשָׁא מְסַאֲבִין אִנּוּן לְכוֹן:
@73 וְדֵין לְכוֹן מְסָאָבָא בְּרִחֲשָׁא דְּרָחֵשׁ עַל אַרְעָא חֻלְדָא וְעַכְבָּרָא וְצָבָא לִזְנוֹהִי:
@74 וְיָלָא וְכֹחָא וְחֻלְטֵיתָא וְחֻמְטָא וְאָשׁוּתָא:
@75 אִלֵּין דִּמְסַאֲבִין לְכוֹן בְּכָל רִחֲשָׁא כָּל דְּיִקְרַב בְּהוֹן בְּמוֹתְהוֹן יְהֵי מְסָאָב עַד רַמְשָׁא:
@76 וְכֹל דִּי יִפֵּל עֲלוֹהִי מִנְּהוֹן בְּמוֹתְהוֹן יְהֵי מְסָאָב מִכָּל מָאן דְּאָעָא אוֹ לְבוּשׁ אוֹ מְשַׁךְ אוֹ שָׂק כָּל מָאן דִּי תִתְעֲבֵד עִבִידָא בְּהוֹן בְּמַיָּא יִתָּעַל וִיהֵי מְסָאָב עַד רַמְשָׁא וְיִדְכֵּי:
@77 וְכָל מָאן דַּחֲסַף דִּי יִפֵּל מִנְּהוֹן לְגַוֵּיהּ כֹּל דִּי בְגַוֵּיהּ יִסְתָּאַב וְיָתֵיהּ תְּתַבְּרוּן:
@78 מִכָּל מֵיכְלָא דְּמִתְאֲכֵל דִּי יַעֲלוּן עֲלוֹהִי מַיָּא יְהֵי מְסָאָב וְכָל מַשְׁקֵה דִי יִשְׁתֵּתֵי בְּכָל מָאן יְהֵי מְסָאָב:
@79 וְכֹל דִּי יִפֵּל מִנְּבִלְתְּהוֹן עֲלוֹהִי יְהֵי מְסָאָב תַּנּוּר וְכִירַיִם יִתָּרְעוּן מְסַאֲבִין אִנּוּן וּמְסַאֲבִין יְהוֹן לְכוֹן:
@80 בְּרַם מַעְיָן וְגוֹב בֵּית כְּנִישׁוּת מַיָּא יְהֵי דְכֵי וּדְיִקְרַב בִּנְבִלְתְּהוֹן יְהֵי מְסָאָב:
@81 וַאֲרֵי יִפֵּל מִנְּבִלְתְּהוֹן עַל כָּל בַּר זְרַע זֵרוּעַ דִּי יִזְדְּרָע דְּכֵי הוּא:
@82 וַאֲרֵי יִתְיַהֲבוּן מַיָּא עַל בַּר זַרְעָא וְיִפֵּל מִנְּבִלְתְּהוֹן עֲלוֹהִי מְסָאָב הוּא לְכוֹן:
@83 וַאֲרֵי יְמוּת מִן בְּעִירָא דִּי הִיא לְכוֹן לְמֵיכָל דְּיִקְרַב בִּנְבִלְתַּהּ יְהֵי מְסָאָב עַד רַמְשָׁא:
@84 וּדְיֵכוּל מִנְּבִלְתַּהּ יְצַבַּע לְבוּשׁוֹהִי וִיהֵי מְסָאָב עַד רַמְשָׁא וּדְיִטּוֹל יָת נְבִלְתַּהּ יְצַבַּע לְבוּשׁוֹהִי וִיהֵי מְסָאָב עַד רַמְשָׁא:
@85 וְכָל רִחֲשָׁא דְּרָחֵשׁ עַל אַרְעָא שִׁקְצָא הוּא לָא יִתְאָכֵל:
@86 כֹּל דִּמְהַלֵּךְ עַל מְעוֹהִי וְכֹל דִּמְהַלֵּךְ עַל אַרְבַּע עַד כָּל סְגִיאוּת רַגְלָאִין לְכָל רִחֲשָׁא דְּרָחֵשׁ עַל אַרְעָא לָא תֵיכְלֻנּוּן אֲרֵי שִׁקְצָא אִנּוּן:
@87 לָא תְשַׁקְּצוּ יָת נַפְשָׁתֵיכוֹן בְּכָל רִחֲשָׁא דְּרָחֵשׁ וְלָא תִסְתַּאֲבוּן בְּהוֹן וְתִסְתַּאֲבוּן פּוֹן בְּהוֹן:
@88 אֲרֵי אֲנָא יְיָ אֱלָהָכוֹן וְתִתְקַדְּשׁוּן וּתְהוֹן קַדִּישִׁין אֲרֵי קַדִּישׁ אֲנָא וְלָא תְסַאֲבוּן יָת נַפְשָׁתֵיכוֹן בְּכָל רִחֲשָׁא דְּרָחֵשׁ עַל אַרְעָא:
@89 אֲרֵי אֲנָא יְיָ דְּאַסֵּק יָתְכוֹן מֵאַרְעָא דְמִצְרַיִם לְמֶהֱוֵי לְכוֹן לֶאֱלָהּ וּתְהוֹן קַדִּישִׁין אֲרֵי קַדִּישׁ אֲנָא:
@90 דָּא אוֹרַיְתָא דִבְעִירָא וּדְעוֹפָא וּדְכֹל נַפְשָׁתָא חַיְתָא דִּרְחֵשָׁא בְּמַיָּא וּלְכָל נַפְשָׁא דִּרְחֵשָׁא עַל אַרְעָא:
@91 לְאַפְרָשָׁא בֵּין מְסָאָבָא וּבֵין דַּכְיָא וּבֵין חַיְתָא דְּמִתְאַכְלָא וּבֵין חַיְתָא דִּי לָא מִתְאַכְלָא:

@1 **ויהי ביום השמיני.** לַמִּלּוּאִים; הוּא רֹאשׁ חֹדֶשׁ נִיסָן שֶׁהוּקַם הַמִּשְׁכָּן בּוֹ בַיּוֹם וְנָטַל עֶשֶׂר עֲטָרוֹת הַשְּׁנוּיוֹת בְּסֵדֶר עוֹלָם:
@1 **ולזקני ישראל.** לְהַשְׁמִיעָם שֶׁעַל פִּי הַדִּבּוּר אַהֲרֹן נִכְנָס וּמְשַׁמֵּשׁ בִּכְהֻנָּה גְדוֹלָה וְלֹא יֹאמְרוּ מֵאֵלָיו נִכְנָס (תנחומא):
@2 **קח לך עגל.** לְהוֹדִיעַ שֶׁכִּפֵּר לוֹ הַקָּבָּ"ה עַל יְדֵי עֵגֶל זֶה עַל מַעֲשֵׂה הָעֵגֶל שֶׁעָשָֹה (שם):
@4 **כי היום ה' נראה אליכם.** לְהַשְׁרוֹת שְׁכִינָתוֹ בְמַעֲשֵׂה יְדֵיכֶם, לְכָךְ קָרְבָּנוֹת הַלָּלוּ בָּאִין חוֹבָה לְיוֹם זֶה:
@7 **קרב אל המזבח.** שֶׁהָיָה אַהֲרֹן בּוֹשׁ וְיָרֵא לָגֶשֶׁת, אָמַר לוֹ מֹשֶׁה, לָמָּה אַתָּה בוֹשׁ? לְכָךְ נִבְחַרְתָּ (ספרא):
@7 **את חטאתך.** עֵגֶל בֶּן בָּקָר:
@7 **ואת עלתך.** הָאָיִל:
@7 **קרבן העם.** שְׂעִיר עִזִּים וְעֵגֶל וְכֶבֶשׂ; כָּל מָקוֹם שֶׁנֶּאֱמַר "עֵגֶל" בֶּן שָׁנָה הוּא וּמִכָּאן אַתָּה לָמֵד (שם):
@11 **ואת הבשר ואת העור וגו'.** לֹא מָצִינוּ חַטָּאת חִיצוֹנָה נִשְֹרֶפֶת אֶלָּא זוֹ וְשֶׁל מִלּוּאִים, וְכֻלָּן עַל פִּי הַדִּבּוּר:
@12 **וימצאו.** לְשׁוֹן הוֹשָׁטָה וְהַזְמָנָה:
@15 **ויחטאהו.** עָשָׂהוּ כְּמִשְׁפַּט חַטָּאת:
@15 **כראשון.** כָּעֵגֶל שֶׁלּוֹ:
@16 **ויעשה כמשפט.** הַמְפֹרָשׁ בְּעוֹלַת נְדָבָה בְּוַיִּקְרָא:
@17 **וימלא כפו.** הִיא קְמִיצָה (שם):
@17 **מלבד עלת הבקר.** כָּל אֵלֶּה עָשָֹה אַחַר עוֹלַת הַתָּמִיד:
@19 **והמכסה.** חֵלֶב הַמְכַסֶּה אֶת הַקֶּרֶב:
@20 **וישימו את החלבים על החזות.** לְאַחַר הַתְּנוּפָה נְתָנָן כֹּהֵן הַמֵּנִיף לְכֹהֵן אַחֵר לְהַקְטִירָם, נִמְצְאוּ הָעֶלְיוֹנִים לְמַטָּה (מנחות ס"ב):
@22 **ויברכם.** בִּרְכַּת כֹּהֲנִים — יְבָרֶכְךָ, יָאֵר, יִשָּׂא (סוטה ל"ח):
@22 **וירד.** מֵעַל הַמִּזְבֵּחַ:
@23 **ויבא משה ואהרן וגו'.** לָמָּה נִכְנְסוּ? מָצָאתִי בְּפָרָשַׁת מִלּוּאִים, בְּבָרַיְתָא הַנּוֹסֶפֶת עַל תּוֹרַת כֹּהֲנִים שֶׁלָּנוּ, לָמָּה נִכְנַס מֹשֶׁה עִם אַהֲרֹן? לְלַמְּדוֹ עַל מַעֲשֵׂה הַקְּטֹרֶת, אוֹ לֹא נִכְנַס אֶלָּא לְדָבָר אַחֵר? הֲרֵינִי דָן, יְרִידָה וּבִיאָה טְעוּנָה בְרָכָה, מַה יְּרִידָה מֵעֵין עֲבוֹדָה אַף בִּיאָה מֵעֵין עֲבוֹדָה, הָא לָמַדְתָּ לָמָּה נִכְנַס מֹשֶׁה עִם אַהֲרֹן לְלַמְּדוֹ עַל מַעֲשֵׂה הַקְּטֹרֶת; דָּ"אַ כֵּיוָן שֶׁרָאָה אַהֲרֹן שֶׁקָּרְבוּ כָּל הַקָּרְבָּנוֹת וְנַעֲשׂוּ כָל הַמַּעֲשִׂים וְלֹא יָרְדָה שְׁכִינָה לְיִשְׂרָאֵל, הָיָה מִצְטַעֵר וְאוֹמֵר, יוֹדֵעַ אֲנִי שֶׁכָּעַס הַקָּבָּ"ה עָלַי וּבִשְׁבִילִי לֹא יָרְדָה שְׁכִינָה לְיִשְׂרָאֵל, אָמַר לוֹ לְמֹשֶׁה, מֹשֶׁה אָחִי, כָּךְ עָשִֹיתָ לִי שֶׁנִּכְנַסְתִּי וְנִתְבַּיַּשְׁתִּי? מִיַּד נִכְנַס מֹשֶׁה עִמּוֹ וּבִקְּשׁוּ רַחֲמִים וְיָרְדָה שְׁכִינָה לְיִשְׂרָאֵל (ספרא):
@23 **ויצאו ויברכו את העם.** אָמְרוּ וִיהִי נֹעַם ה' אֱלֹהֵינוּ עָלֵינוּ, יְהִי רָצוֹן שֶׁתִּשְׁרֶה שְׁכִינָה בְמַעֲשֵׂה יְדֵיכֶם; לְפִי שֶׁכָּל שִׁבְעַת יְמֵי הַמִּלּוּאִים שֶׁהֶעֱמִידוֹ מֹשֶׁה לַמִּשְׁכָּן וְשִׁמֵּשׁ בּוֹ וּפֵרְקוֹ בְכָל יוֹם לֹא שָׁרְתָה בוֹ שְׁכִינָה, וְהָיוּ יִשְׂרָאֵל נִכְלָמִים וְאוֹמְרִים לְמֹשֶׁה, מֹשֶׁה רַבֵּנוּ, כָּל הַטֹּרַח שֶׁטָּרַחְנוּ שֶׁתִּשְׁרֶה שְׁכִינָה בֵינֵינוּ וְנֵדַע שֶׁנִּתְכַּפֵּר לָנוּ עֲוֹן הָעֵגֶל, לְכָךְ אָמַר לָהֶם זֶה הַדָּבָר אֲשֶׁר צִוָּה ה' תַּעֲשׂוּ וְיֵרָא אֲלֵיכֶם כְּבוֹד ה' — אַהֲרֹן אָחִי כְּדַאי וְחָשׁוּב מִמֶּנִּי, שֶׁעַל יְדֵי קָרְבְּנוֹתָיו וַעֲבוֹדָתוֹ תִשְׁרֶה שְׁכִינָה בָכֶם וְתֵדְעוּ שֶׁהַמָּקוֹם בָּחַר בּוֹ:
@24 **וירנו.** כְּתַרְגּוּמוֹ:
@26 **ותצא אש.** רַ' אֱלִיעֶזֶר אוֹמֵר לֹא מֵתוּ בְנֵי אַהֲרֹן אֶלָּא עַל יְדֵי שֶׁהוֹרוּ הֲלָכָה בִּפְנֵי מֹשֶׁה רַבָּן, רַבִּי יִשְׁמָעֵאל אוֹמֵר שְׁתוּיֵי יַיִן נִכְנְסוּ לַמִּקְדָּשׁ, תֵּדַע, שֶׁאַחַר מִיתָתָן הִזְהִיר הַנּוֹתָרִים שֶׁלֹּא יִכָּנְסוּ שְׁתוּיֵי יַיִן לַמִּקְדָּשׁ, מָשָׁל לְמֶלֶךְ שֶׁהָיָה לוֹ בֶן בַּיִת וְכוּ', כִּדְאִיתָא בְּוַיִּקְרָא רַבָּה:
@27 **הוא אשר דבר וגו'.** הֵיכָן דִּבֵּר? וְנֹעַדְתִּי שָׁמָּה לִבְנֵי יִשְֹרָאֵל וְנִקְדַּשׁ בִּכְבֹדִי (שמות כ"ט), אַל תִּקְרֵי בִּכְבֹדִי אֶלָּא בִּמְכֻבָּדַי; אָמַר לוֹ מֹשֶׁה לְאַהֲרֹן, אַהֲרֹן אָחִי, יוֹדֵעַ הָיִיתִי שֶׁיִּתְקַדֵּשׁ הַבַּיִת בִּמְיֻדָּעָיו שֶׁל מָקוֹם, וְהָיִיתִי סָבוּר אוֹ בִי אוֹ בְךָ, עַכְשָׁיו רוֹאֶה אֲנִי שֶׁהֵם גְּדוֹלִים מִמֶּנִּי וּמִמְּךָ (ספרא):
@27 **וידם אהרן.** קִבֵּל שָׂכָר עַל שְׁתִיקָתוֹ, וּמַה שָּׂכָר קִבֵּל? שֶׁנִּתְיַחֵד עִמּוֹ הַדִּבּוּר — שֶׁנֶּאֶמְרָה לוֹ לְבַדּוֹ פָּרָשַׁת שְׁתוּיֵי יַיִן (ויקרא רבה י"ב):
@27 **בקרבי.** בִּבְחִירַי:
@27 **ועל פני כל העם אכבד.** כְּשֶׁהַקָּבָּ"ה עוֹשֶׂה דִין בַּצַּדִּיקִים מִתְיָרֵא וּמִתְעַלֶּה וּמִתְקַלֵּס, אִם כֵּן בְּאֵלּוּ, כָּל שֶׁכֵּן בָּרְשָׁעִים; וְכֵן הוּא אוֹמֵר נוֹרָא אֱלֹהִים מִמִּקְדָּשֶׁיךָ (תהלים ס"ח), אַל תִּקְרֵי מִמִּקְדָּשֶׁיךָ אֶלָּא מִמְּקֻדָּשֶׁיךָ:
@28 **דד אהרן.** עֻזִּיאֵל אֲחִי עַמְרָם הָיָה שֶׁנֶּאֱמַר וּבְנֵי קְהָת וְגוֹ' (שמות ו'):
@28 **שאו את אחיכם וגו'.** כְּאָדָם הָאוֹמֵר לַחֲבֵרוֹ, הַעֲבֵר אֶת הַמֵּת מִלִּפְנֵי הַכַּלָּה שֶׁלֹּא לְעַרְבֵּב אֶת הַשִּׂמְחָה:
@29 **בכתנתם.** שֶׁל מֵתִים; מְלַמֵּד שֶׁלֹּא נִשְׂרְפוּ בִגְדֵיהֶם אֶלָּא נִשְׁמָתָם, כְּמִין שְׁנֵי חוּטִין שֶׁל אֵשׁ נִכְנְסוּ לְתוֹךְ חָטְמֵיהֶם (ספרא):
@30 **אל תפרעו.** אַל תְּגַדְּלוּ שֵׂעָר, מִכָּאן שֶׁאָבֵל אָסוּר בְּתִסְפֹּרֶת, אֲבָל אַתֶּם אַל תְּעַרְבְּבוּ שִׂמְחָתוֹ שֶׁל מָקוֹם (מועד קטן י"ד):
@30 **ולא תמתו.** הָא אִם תַּעֲשׂוּ תָּמוּתוּ (ספרא):
@30 **ואחיכם כל בית ישראל.** מִכָּאן שֶׁצָּרָתָן שֶׁל תַּלְמִידֵי חֲכָמִים מֻטֶּלֶת עַל הַכֹּל לְהִתְאַבֵּל בָּהּ (מועד קטן כ"ח):
@33 **יין ושכר.** יַיִן דֶּרֶךְ שִׁכְרוּתוֹ (ספרא):
@33 **בבאכם אל אהל מועד.** אֵין לִי אֶלָּא בְּבֹאֲכֶם לַהֵיכָל, בְּגִשְׁתָּם לַמִּזְבֵּחַ מִנַּיִן? נֶאֱמַר כָּאן בִּיאַת אֹהֶל מוֹעֵד וְנֶאֱמַר בְּקִדּוּשׁ יָדַיִם וְרַגְלַיִם בִּיאַת אֹהֶל מוֹעֵד, מַה לְּהַלָּן עָשָׂה גִישַׁת מִזְבֵּחַ כְּבִיאַת אֹהֶל מוֹעֵד, אַף כָּאן עָשָׂה גִישַׁת מִזְבֵּחַ כְּבִיאַת אֹהֶל מוֹעֵד (שם):
@34 **ולהבדיל.** כְּדֵי שֶׁתַּבְדִּילוּ בֵּין עֲבוֹדָה קְדוֹשָׁה לִמְחֻלֶּלֶת, הָא לָמַדְתָּ שֶׁאִם עָבַד עֲבוֹדָתוֹ פְסוּלָה (שם):
@35 **ולהורת.** לִמֵּד שֶׁאָסוּר שִׁכּוֹר בְּהוֹרָאָה, יָכוֹל יְהֵא חַיָּב מִיתָה, תַּ"ל אַתָּה וּבָנֶיךָ אִתָּךְ, וְלֹא תָמֻתוּ, כֹּהֲנִים בַּעֲבוֹדָתָם בְּמִיתָה, וְאֵין חֲכָמִים בְּהוֹרָאָתָן בְּמִיתָה (שם):
@36 **הנותרים.** מִן הַמִּיתָה, מְלַמֵּד שֶׁאַף עֲלֵיהֶן נִקְנְסָה מִיתָה עַל עֲוֹן הָעֵגֶל, הוּא שֶׁנֶּאֱמַר (דברים ט'), וּבְאַהֲרֹן הִתְאַנַּף ה' מְאֹד לְהַשְׁמִידוֹ, וְאֵין הַשְׁמָדָה אֶלָּא כִלּוּי בָּנִים, שֶׁנֶּאֱמַר (עמוס ב'), וָאַשְׁמִיד פִּרְיוֹ מִמַּעַל, וּתְפִלָּתוֹ שֶׁל מֹשֶׁה בִּטְּלָה מֶחֱצָה, שֶׁנֶּאֱמַר (דברים ט'), וָאֶתְפַּלֵּל גַּם בְּעַד אַהֲרֹן בָּעֵת הַהִיא:
@36 **קחו את המנחה.** אַף עַל פִּי שֶׁאַתֶּם אוֹנְנִין וְקָדָשִׁים אֲסוּרִים לְאוֹנֵן:
@36 **את המנחה.** זוֹ מִנְחַת שְׁמִינִי וּמִנְחַת נַחְשׁוֹן (ספרא):
@36 **ואכלוה מצות.** מַה תַּ"ל? לְפִי שֶׁהִיא מִנְחַת צִבּוּר וּמִנְחַת שָׁעָה וְאֵין כַּיּוֹצֵא בָהּ לְדּוֹרוֹת, הֻצְרַךְ לְפָרֵשׁ בָּהּ דִּין שְׁאָר מְנָחוֹת (שם):
@37 **וחק בניך.** אֵין לַבָּנוֹת חֹק בַּקֳּדָשִׁים (שם):
@37 **כי כן צויתי.** בַּאֲנִינוּת יֹאכְלוּהָ (שם; זבחים ק"א):
@38 **ואת חזה התנופה.** שֶׁל שַׁלְמֵי צִבּוּר.
@38 **תאכלו במקום טהור.** וְכִי אֶת הָרִאשׁוֹנִים אָכְלוּ בְּמָקוֹם טָמֵא? אֶלָּא הָרִאשׁוֹנִים שֶׁהֵם קָדְשֵׁי קֳדָשִׁים הֻזְקְקָה אֲכִילָתָם בְּמָקוֹם קָדוֹשׁ, אֲבָל אֵלּוּ אֵין צְרִיכִים תּוֹךְ הַקְּלָעִים אֲבָל צְרִיכִים הֵם לֵאָכֵל תּוֹךְ מַחֲנֵה יִשְׂרָאֵל שֶׁהוּא טָהוֹר מִלִּכָּנֵס שָׁם מְצֹרָעִים; מִכָּאן שֶׁקָּדָשִׁים קַלִּים נֶאֱכָלִין בְּכָל הָעִיר (שם נ"ה):
@38 **אתה ובניך ובנתיך.** אַתָּה וּבָנֶיךָ בְּחֵלֶק אֲבָל בְּנוֹתֶיךָ לֹא בְחֵלֶק, אֶלָּא אִם תִּתְּנוּ לָהֶם מַתָּנוֹת רַשָּׁאוֹת הֵן לֶאֱכֹל בְּחָזֶה וְשׁוֹק, אוֹ אֵינוֹ אֶלָּא אַף הַבָּנוֹת בְּחֵלֶק? תַּלְמוּד לוֹמַר כִּי חָקְךָ וְחָק בָּנֶיךָ נִתְּנוּ — חֹק לַבָּנִים וְאֵין חֹק לַבָּנוֹת (ספרא):
@39 **שוק התרומה וחזה התנופה.** לשון אשר הונף ואשר הורם. תנופה מוליך ומביא תרומה מעלה ומוריד. ולמה חלקן הכתוב תרומה בשוק ותנופה בחזה. לא ידענו. ששניהם בהרמה והנפה:
@39 **על אשי החלבים.** מִכָּאן שֶׁהַחֲלָבִים לְמַטָּה בִּשְׁעַת תְּנוּפָה, וְיִשּׁוּב הַמִּקְרָאוֹת שֶׁלֹּא יַכְחִישׁוּ זֶה אֶת זֶה כְּבָר פֵּרַשְׁתִּי אֶת שְׁלָשְׁתָּן בְּצַו אֶת אַהֲרֹן:
@40 **שעיר החטאת.** שְׂעִיר מוּסְפֵי רֹאשׁ חֹדֶשׁ; וּשְׁלֹשָׁה שְׂעִירֵי חַטָּאוֹת קָרְבוּ בוֹ בַיּוֹם, שְׂעִיר עִזִּים וּשְׂעִיר נַחְשׁוֹן וּשְׂעִיר רֹאשׁ חֹדֶשׁ, וּמִכֻּלָּן לֹא נִשְׂרַף אֶלָּא זֶה; וְנֶחְלְקוּ בַדָּבָר חַכְמֵי יִשְֹרָאֵל, יֵשׁ אוֹמְרִים מִפְּנֵי הַטֻּמְאָה שֶׁנָּגְעָה בוֹ נִשְׂרַף, וְיֵשׁ אוֹמְרִים מִפְּנֵי אֲנִינוּת נִשְׂרַף, לְפִי שֶׁהוּא קָדְשֵׁי דוֹרוֹת, אֲבָל בְּקָדְשֵׁי שָׁעָה סָמְכוּ עַל מֹשֶׁה שֶׁאָמַר לָהֶם בַּמִּנְחָה וְאִכְלוּהָ מַצּוֹת (ספרא; זבחים ק"א):
@40 **דרש דרש.** שְׁתֵּי דְרִישׁוֹת: מִפְּנֵי מָה נִשְׂרַף זֶה? וּמִפְּנֵי מָה נֶאֶכְלוּ אֵלּוּ? כָּךְ הִיא בְּתוֹרַת כֹּהֲנִים:
@40 **על אלעזר ועל איתמר.** בִּשְׁבִיל כְּבוֹדוֹ שֶׁל אַהֲרֹן הָפַךְ פָּנָיו כְּנֶגֶד הַבָּנִים וְכָעַס (ספרא):
@40 **לאמר.** אָמַר לָהֶם הֲשִׁיבוּנִי עַל דְּבָרַי (שם):
@41 **מדוע לא אכלתם את החטאת במקום הקדש.** וְכִי חוּץ לַקֹּדֶשׁ אֲכָלוּהָ, וַהֲלֹא שְׂרָפוּהָ, וּמַה הוּא אוֹמֵר בִּמְקוֹם הַקֹּדֶשׁ, אֶלָּא אָמַר לָהֶם שֶׁמָּא חוּץ לַקְּלָעִים יָצְאָה וְנִפְסְלָה:
@41 **כי קדש קדשים הוא.** וְנִפְסֶלֶת בְּיוֹצֵא, וְהֵם אָמְרוּ לוֹ לָאו. אָמַר לָהֶם הוֹאִיל וּבִמְקוֹם הַקֹּדֶשׁ הָיְתָה, מַדּוּעַ לֹא אֲכַלְתֶּם אוֹתָהּ:
@41 **ואתה נתן לכם לשאת וגו'.** שֶׁהַכֹּהֲנִים אוֹכְלִים וּבְעָלִים מִתְכַּפְּרִים:
@41 **לשאת את עון העדה.** מִכָּאן לָמַדְנוּ שֶׁשְּׂעִיר רֹאשׁ חֹדֶשׁ הָיָה, שֶׁהוּא מְכַפֵּר עַל עֲוֹן טֻמְאַת מִקְדָּשׁ וְקָדָשָׁיו, שֶׁחַטַּאת שְׁמִינִי וְחַטַּאת נַחְשׁוֹן לֹא לְכַפָּרָה בָּאוּ:
@42 **הן לא הובא וגו'.** שֶׁאִלּוּ הוּבָא, הָיָה לָכֶם לְשָֹרְפָהּ, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא ו'), וְכָל חַטָּאת אֲשֶׁר יוּבָא מִדָּמָהּ וְגוֹ' (פסחים פ"ב):
@42 **אכל תאכלו אתה.** הָיָה לָכֶם לְאָכְלָהּ אַף עַל פִּי שֶׁאַתֶּם אוֹנְנִים:
@42 **כאשר צויתי.** לָכֶם בַּמִּנְחָה:
@43 **וידבר אהרן.** אֵין לְשׁוֹן דִּבּוּר אֶלָּא לְשׁוֹן עַז, שֶׁנֶּאֱמַר וַיְדַבֵּר הָעָם וְגוֹ' (במדבר כ"א), אֶפְשָׁר מֹשֶׁה קָצַף עַל אֶלְעָזָר וְעַל אִיתָמָר וְאַהֲרֹן מְדַבֵּר? הָא יָדַעְתָּ שֶׁלֹּא הָיְתָה אֶלָּא מִדֶּרֶךְ כָּבוֹד; אָמְרוּ: אֵינוֹ בַדִּין שֶׁיְּהֵא אָבִינוּ יוֹשֵׁב וְאָנוּ מְדַבְּרִים לְפָנָיו, וְאֵינוֹ בַדִּין שֶׁיְּהֵא תַלְמִיד מֵשִׁיב אֶת רַבּוֹ; יָכוֹל מִפְּנֵי שֶׁלֹּא הָיָה בְאֶלְעָזָר לְהָשִׁיב? תַּ"ל וַיֹּאמֶר אֶלְעָזָר הַכֹּהֵן אֶל אַנְשֵׁי הַצָּבָא וְגוֹמֵר (שם ל"א), הֲרֵי כְּשֶׁרָצָה, דִּבֵּר לִפְנֵי מֹשֶׁה וְלִפְנֵי הַנְּשִֹיאִים, זוֹ מָצָאתִי בְּסִפְרֵי שֶׁל פָּנִים שֵׁנִי:
@43 **הן היום הקריבו.** מַהוּ אוֹמֵר? אֶלָּא אָמַר לוֹ מֹשֶׁה: שֶׁמָּא זְרַקְתֶּם דָּמָהּ אוֹנְנִין, שֶׁאוֹנֵן שֶׁעָבַד חִלֵּל? אָמַר לוֹ אַהֲרֹן וְכִי הֵם הִקְרִיבוּ שֶׁהֵם הֶדְיוֹטוֹת? אֲנִי הִקְרַבְתִּי שֶׁאֲנִי כֹהֵן גָּדוֹל וּמַקְרִיב אוֹנֵן (זבחים ק"א):
@43 **ותקראנה אתי כאלה.** אֲפִלוּ לֹא הָיוּ הַמֵּתִים בָּנַי, אֶלָּא שְׁאָר קְרוֹבִים שֶׁאֲנִי חַיָּב לִהְיוֹת אוֹנֵן עֲלֵיהֶם כְּאֵלּוּ, כְּגוֹן כָּל הָאֲמוּרִים בְּפָרָשַׁת כֹּהֲנִים שֶׁהַכֹּהֵן מִטַּמֵּא לָהֶם (ספרא).
@43 **ואכלתי חטאת.** וְאִם אָכַלְתִּי **הייטב וגו'** :
@43 **היום.** אֲבָל אֲנִינוּת לַיְלָה מֻתָּר, שֶׁאֵין אוֹנֵן אֶלָּא יוֹם קְבוּרָה (ספרא; זבחים ק'):
@43 **הייטב בעיני ה'.** אִם שָׁמַעְתָּ בְּקָדְשֵׁי שָׁעָה אֵין לְךָ לְהָקֵל בְּקָדְשֵׁי דוֹרוֹת:
@44 **וייטב בעיניו.** הוֹדָה וְלֹא בוֹשׁ לוֹמַר לֹא שָׁמַעְתִּי (זבחים ק"א):
@45 **אל משה ואל אהרן.** לְמֹשֶׁה אָמַר שֶׁיֹּאמַר לְאַהֲרֹן:
@45 **לאמר אלהם.** אָמַר שֶׁיֹּאמַר לְאֶלְעָזָר וּלְאִיתָמָר; אוֹ אֵינוֹ אֶלָּא לֵאמֹר לְיִשְֹרָאֵל? כְּשֶׁהוּא אוֹמֵר דַּבְּרוּ אֶל בְּנֵי יִשְֹרָאֵל הֲרֵי דִּבּוּר אָמוּר לְיִשְֹרָאֵל, הָא מָה אֲנִי מְקַיֵּם לֵאמֹר אֲלֵהֶם? לַבָּנִים — לְאֶלְעָזָר וּלְאִיתָמָר (ספרא):
@46 **דברו אל בני ישראל.** אֶת כֻּלָּם הִשְׁוָה לִהְיוֹת שְׁלוּחִים בְּדִבּוּר זֶה, לְפִי שֶׁהֻשְׁווּ בַּדְּמִימָה וְקִבְּלוּ עֲלֵיהֶם גְּזֵרַת הַמָּקוֹם מֵאַהֲבָה:
@46 **זאת החיה.** לְשׁוֹן חַיִּים, לְפִי שֶׁיִּשְֹרָאֵל דְּבוּקִים בַּמָּקוֹם וּרְאוּיִין לִהְיוֹת חַיִּים, לְפִיכָךְ הִבְדִּילָם מִן הַטֻּמְאָה וְגָזַר עֲלֵיהֶם מִצְוֹת, וְלָאֻמּוֹת לֹא אָסַר כְּלוּם, מָשָׁל לְרוֹפֵא שֶׁנִּכְנַס לְבַקֵּר אֶת הַחוֹלֶה כּוּ' כִּדְאִיתָא בְּמִדְרַשׁ רַבִּי תַנְחוּמָא:
@46 **זאת החיה.** מְלַמֵּד שֶׁהָיָה מֹשֶׁה אוֹחֵז בַּחַיָּה וּמַרְאֶה אוֹתָהּ לְיִשְֹרָאֵל זֹאת תֹּאכְלוּ וְזֹאת לֹא תֹאכְלוּ (חולין מ"ב), אֶת זֶה תֹּאכְלוּ וְגוֹ' (פסוק ט'), אַף בְּשִׁרְצֵי הַמַּיִם אָחַז מִכָּל מִין וָמִין וְהֶרְאָה לָהֶם, וְכֵן בָּעוֹף וְאֶת אֵלֶּה תְּשַׁקְּצוּ מִן הָעוֹף (פסוק י"ג), וְכֵן בַּשְּׁרָצִים וְזֶה לָכֶם הַטָּמֵא (פסוק כ"ט):
@46 **זאת החיה … מכל הבהמה.** מְלַמֵּד שֶׁהַבְּהֵמָה בִּכְלַל חַיָּה (ספרא; חולין ע'):
@47 **מפרסת.** כְּתַרְגּוּמוֹ סְדִיקָא:
@47 **פרסה.** פלנט"א בְּלַעַז:
@47 **ושסעת שסע.** שֶׁמֻּבְדֶּלֶת מִלְּמַעְלָה וּמִלְּמַטָּה בִּשְׁתֵּי צִפָּרְנִַין, כְּתַרְגּוּמוֹ וּמַטִּלְּפָן טִלְפִין, שֶׁיֵּשׁ שֶׁפַּרְסוֹתָיו סְדוּקוֹת מִלְּמַעְלָה וְאֵין שְׁסוּעוֹת וּמֻבְדָּלוֹת לְגַמְרֵי, שֶׁמִּלְּמַטָּה מְחֻבָּרוֹת:
@47 **מעלת גרה.** מַעֲלָה וּמְקִיאָה הָאֹכֶל מִמֵּעֶיהָ וּמַחֲזֶרֶת אוֹתוֹ לְתוֹךְ פִּיהָ לְכָתְשׁוֹ וּלְטָחֳנוֹ הָדֵק:
@47 **גרה.** כָּךְ שְׁמוֹ; וְיִתָּכֵן לִהְיוֹת מִגִּזְרַת מַיִם הַנִּגָּרִים (שמואל ב י"ד), שֶׁהוּא נִגְרָר אַחַר הַפֶּה; וְתַרְגּוּמוֹ פִשְׁרָא, שֶׁעַל יְדֵי הַגֵּרָה הָאֹכֶל נִפְשָׁר וְנִמּוֹחַ:
@47 **בבהמה.** תֵּיבָה יְתֵרָה הִיא לִדְרָשָׁה — לְהַתִּיר אֶת הַשְּׁלִיל הַנִּמְצָא בִמְעֵי אִמּוֹ (ספרא; חולין ס"ט):
@47 **אתה תאכלו.** וְלֹא בְהֵמָה טְמֵאָה, וַהֲלֹא בְאַזְהָרָה הִיא? אֶלָּא לַעֲבֹר עָלֶיהָ בַּעֲשֵׂה וְלֹא תַעֲשֶׂה (ספרא; זבחים ל"ד):
@52 **מבשרם לא תאכלו.** אֵין לִי אֶלָּא אֵלּוּ, שְׁאָר בְּהֵמָה טְמֵאָה שֶׁאֵין לָהּ שׁוּם סִימָן טָהֳרָה מִנַּיִן? אָמַרְתָּ קַל וָחֹמֶר, וּמָה אֵלּוּ שֶׁיֵּשׁ בָּהֶן קְצָת סִימָנֵי טָהֳרָה אֲסוּרוֹת וְכוּ' (ספרא):
@52 **מבשרם.** עַל בְּשָׂרָם בְּאַזְהָרָה וְלֹא עַל עֲצָמוֹת וְגִידִין וְקַרְנַיִם וּטְלָפַיִם (שם):
@52 **ובנבלתם לא תגעו.** יָכוֹל יְהוּ יִשְׂרָאֵל מֻזְהָרִים עַל מַגַּע נְבֵלָה, תַּ"ל אֱמֹר אֶל הַכֹּהֲנִים וְגוֹ' — כֹּהֲנִים מֻזְהָרִין וְאֵין יִשְׂרָאֵל מֻזְהָרִין — קַל וָחֹמֶר מֵעַתָּה: וּמַה טֻּמְאַת מֵת חֲמוּרָה לֹא הִזְהִיר בָּהּ אֶלָּא כֹּהֲנִים, טֻמְאַת נְבֵלָה קַלָּה לֹא כָל שֶׁכֵּן, וּמַה תַּלְמוּד לוֹמַר לֹא תִגָּעוּ? בָּרֶגֶל (שם; ראש השנה ט"ז):
@53 **סנפיר.** אֵלּוּ שֶׁשָּׁט בָּהֶם (חולין נ"ט):
@53 **קשקשת.** אֵלּוּ קְלִפִּין הַקְּבוּעִים בּוֹ (כְּמוֹ שֶׁנֶּאֱמַר (שמואל א י"ז), וְשִׁרְיוֹן קַשְׂקַשִּׂים הוּא לָבוּשׁ):
@54 **שרץ.** בְּכָל מָקוֹם מַשְׁמָעוֹ דָּבָר נָמוּךְ שֶׁרוֹחֵשׁ וְנָד עַל הָאָרֶץ:
@55 **ושקץ יהיו.** לֶאֱסֹר אֶת עֵרוּבֵיהֶן אִם יֵשׁ בָּהֶם בְּנוֹתֵן טַעַם (ספרא):
@55 **מבשרם.** אֵינוֹ מוּזְהָר עַל הַסְּנַפִּירִים וְעַל הָעֲצָמוֹת (שם):
@55 **ואת נבלתם תשקצו.** לְרַבּוֹת יַבְחוּשִׁין שֶׁסִּנְּנָן; יַבְחוּשִׁין מושיירונ"ש בלע"ז (חולין ס"ז):
@56 **כל אשר אין לו וגו'.** מַה תַּ"ל? שֶׁיָּכוֹל אֵין לִי שֶׁיְּהֵא מֻתָּר אֶלָּא הַמַּעֲלֶה סִימָנִין שֶׁלּוֹ לַיַּבָּשָׁה, הִשִּׁירָן בַּמַּיִם מִנַּיִן? תַּ"ל כֹּל אֲשֶׁר אֵין לוֹ סְנַפִּיר וְקַשְׂקֶשֶׂת בַּמַּיִם, הָא אִם הָיוּ לוֹ בַּמַּיִם אַף עַל פִּי שֶׁהִשִּׁירָן בַּעֲלִיָּתוֹ מֻתָּר (ספרא):
@57 **לא יאכלו.** לְחַיֵּב אֶת הַמַּאֲכִילָן לִקְטַנִּים, שֶׁכָּךְ מַשְׁמָעוֹ לֹא יְהוּ נֶאֱכָלִין עַל יָדְךָ, אוֹ אֵינוֹ אֶלָּא לְאָסְרָן בַּהֲנָאָה? תַּ"ל לֹא תֹאכְלוּם — בַּאֲכִילָה אֲסוּרִין בַּהֲנָאָה מֻתָּרִין; כָּל עוֹף שֶׁנֶּאֱמַר בּוֹ לְמִינָהּ, לְמִינוֹ, לְמִינֵהוּ, יֵשׁ בְּאוֹתוֹ הַמִּין שֶאֵין דּוֹמִין זֶה לָזֶה לֹא בְמַרְאֵיהֶם וְלֹא בִשְׁמוֹתָם וְכֻלָּן מִין אֶחָד:
@60 **הנץ.** אשפר"ויר:
@61 **שלך.** פֵּרְשׁוּ רַבּוֹתֵינוּ זֶה הַשּׁוֹלֶה דָגִים מִן הַיָּם, וְזֶה שֶׁתִּרְגֵּם אֻנְקְלוֹס וְשָׁלֵי נוּנָא (חולין ס"ג):
@61 **כוס וינשוף.** הֵם צואי"טש הַצּוֹעֲקִים בַּלַּיְלָה, וְיֵשׁ לָהֶם לְסָתוֹת כְּאָדָם, וְעוֹד אַחֵר דּוֹמֶה לוֹ שֶׁקּוֹרִין יי"בו:
@62 **תנשמת.** הִיא קלב"א ש"וריץ, וְדוֹמָה לְעַכְבָּר הַפּוֹרַחַת בַּלַּיְלָה, וְתִנְשֶׁמֶת הָאֲמוּרָה בַּשְּׁרָצִים הִיא דוֹמָה לָהּ וְאֵין לָהּ עֵינַיִם, וְקוֹרִין לָהּ טלפ"א:
@63 **החסידה.** זוֹ דַיָּה לְבָנָה, ציגוני"א, וְלָמָּה נִקְרָא שְׁמָהּ חֲסִידָה? שֶׁעוֹשָֹׁה חֲסִידוּת עִם חַבְרוֹתֶיהָ בִּמְזוֹנוֹת (שם):
@63 **האנפה.** הִיא דַיָּה רַגְזָנִית, וְנִרְאֶה לִי שֶׁקּוֹרִין אוֹתוֹ הי"רון:
@63 **הדוכיפת.** תַּרְנְגוֹל הַבָּר, וְכַרְבָּלְתּוֹ כְפוּלָה, וּבְלַעַז הרופ"א, וְלָמָּה נִקְרָא שְׁמוֹ דּוּכִיפַת? שֶׁ"הוֹדוֹ כָפוּת" וְזוֹ הִיא כַּרְבָּלְתוֹ, וְנַגַּר טוּרָא נִקְרָא עַל שֵׁם מַעֲשָׂיו, כְּמוֹ שֶׁפֵּרְשׁוּ רַבּוֹתֵינוּ בְּמַסֶּכֶת גִּטִּין בְּפֶרֶק מִי שֶׁאֲחָזוֹ (גיטין דף ס"ח):
@64 **שרץ העוף.** הֵם הַדַּקִּים הַנְּמוּכִים הָרוֹחֲשִׁין עַל הָאָרֶץ, כְּגוֹן זְבוּבִים וּצְרָעִין וְיַתּוּשִׁין וַחֲגָבִים:
@65 **על ארבע.** עַל אַרְבַּע רַגְלָיִם:
@65 **ממעל לרגליו.** סָמוּךְ לְצַוָּארוֹ יֵשׁ לוֹ כְּמִין שְׁתֵּי רַגְלַיִם לְבַד אַרְבַּע רַגְלָיו, וּכְשֶׁרוֹצֶה לָעוּף וְלִקְפֹּץ מִן הָאָרֶץ מִתְחַזֵּק בְּאוֹתָן שְׁנֵי כְרָעַיִם וּפוֹרֵחַ, וְיֵשׁ הַרְבֵּה — כְּאוֹתָן שֶׁקּוֹרִין לנגו"שטא — אֲבָל אֵין אָנוּ בְקִיאִין בָּהֶן, שֶׁאַרְבָּעָה סִימָנֵי טָהֳרָה נֶאֶמְרוּ בָהֶם אַרְבַּע רַגְלַיִם וְאַרְבַּע כְּנָפַיִם וְקַרְסוּלִין — אֵלּוּ כְרָעַיִם הַכְּתוּבִים כָּאן — וּכְנָפָיו חוֹפִין אֶת רֻבּוֹ, וְכָל סִימָנִין הַלָּלוּ מְצוּיִים בְּאוֹתָן שֶׁבֵּינוֹתֵינוּ, אֲבָל יֵשׁ שֶׁרֹאשָׁן אָרֹךְ וְיֵשׁ שֶׁאֵין לָהֶם זָנָב, וְצָרִיךְ שֶׁיְּהֵא שְׁמוֹ חָגָב, וּבָזֶה אֵין אָנוּ יוֹדְעִים לְהַבְדִּיל בֵּינֵיהֶן:
@67 **וכל שרץ העוף וגו'.** בָּא וְלִמֵּד שֶׁאִם יֵשׁ לוֹ חָמֵשׁ טָהוֹר (ספרא):
@68 **ולאלה.** הָעֲתִידִין לֵאָמֵר בָּעִנְיָן לְמַטָּה.
@68 **תטמאו.** כְּלוֹמַר בִּנְגִיעָתָם יֵשׁ טֻמְאָה:
@69 **וכל הנשא מנבלתם.** כָּל מָקוֹם שֶׁנֶּאֶמְרָה טֻמְאַת מַשָּׂא, חֲמוּרָה מִטֻּמְאַת מַגָּע, שֶׁהִיא טְעוּנָה כִבּוּס בְּגָדִים (ספרא):
@70 **מפרסת פרסה ושסע איננה שסעת.** כְּגוֹן גָּמָל, שֶׁפַּרְסָתוֹ סְדוּקָה לְמַעְלָה אֲבָל לְמַטָּה הִיא מְחֻבֶּרֶת, כָּאן לִמֶּדְךָ שֶׁנִּבְלַת בְּהֵמָה טְמֵאָה מְטַמְּאָה, וּבָעִנְיָן שֶׁבְּסוֹף הַפָּרָשָׁה פֵּרֵשׁ עַל בְּהֵמָה טְהוֹרָה:
@71 **על כפיו.** כְּגוֹן כֶּלֶב וְדֹב וְחָתוּל:
@71 **טמאים הם לכם.** לְמַגָּע:
@73 **וזה לכם הטמא.** כָּל טֻמְאוֹת הַלָּלוּ אֵינָן לְאִסּוּר אֲכִילָה אֶלָּא לְטֻמְאָה מַמָּשׁ — לִהְיוֹת טָמֵא בְּמַגָּעָן, וְנֶאֱסַר לֶאֱכֹל תְּרוּמָה וְקָדָשִׁים וְלִכָּנֵס בַּמִּקְדָּשׁ:
@73 **החלד.** מוש"טילא:
@73 **והצב.** פויי"ט שֶׁדּוֹמֶה לִצְפַרְדֵּעַ:
@74 **אנקה.** הרי"ון:
@74 **הלטאה.** לישרד"ה:
@74 **חמט.** לימצ"א:
@74 **תנשמת.** טל"פא:
@76 **במים יובא.** וְאַף לְאַחַר טְבִילָתוֹ טָמֵא הוּא לִתְרוּמָה:
@76 **עד הערב.** וְאַחַ"כַּ **וטהר** בְּהַעֲרֵב הַשֶּׁמֶשׁ:
@77 **אל תוכו.** אֵין כְּלִי חֶרֶס מִטַּמֵּא אֶלָּא מֵאֲוִירוֹ (חולין כ"ד):
@77 **כל אשר בתוכו יטמא.** הַכְּלִי חוֹזֵר וּמְטַמֵּא מַה שֶּׁבַּאֲוִירוֹ:
@77 **ואתו תשברו.** לִמֵּד שֶׁאֵין לוֹ טָהֳרָה בַּמִּקְוֶה:
@78 **מכל האכל אשר יאכל.** מוּסָב עַל מִקְרָא הָעֶלְיוֹן: "כל אשר בתוכו יטמא מִכָּל הָאֹכֶל אֲשֶׁר יֵאָכֵל" אֲשֶׁר בָּאוּ עָלָיו מַיִם וְהוּא בְּתוֹךְ כְּלִי חֶרֶס הַטָּמֵא יִטְמָא (וְכֵן כָּל מַשְׁקֶה אֲשֶׁר יִשָּׁתֶה בְּכָל כְּלִי וְהוּא בְּתוֹךְ כְּלִי חֶרֶס הַטָּמֵא יִטְמָא). לָמַדְנוּ מִכָּאן דְּבָרִים הַרְבֵּה, לָמַדְנוּ שֶׁאֵין אֹכֶל מֻכְשָׁר וּמְתֻקָּן לְקַבֵּל טֻמְאָה עַד שֶׁיָּבֹאוּ עָלָיו מַיִם פַּעַם אַחַת, וּמִשֶּׁבָּאוּ עָלָיו מַיִם פַּעַם אַחַת מְקַבֵּל טֻמְאָה לְעוֹלָם וַאֲפִלוּ נָגוּב, וְהַיַּיִן וְהַשֶּׁמֶן וְכָל הַנִּקְרָא מַשְׁקֶה מַכְשִׁיר זְרָעִים לְטֻמְאָה כַּמַּיִם, שֶׁכָּךְ יֵשׁ לִדְרֹשׁ הַמִּקְרָא: אֲשֶׁר יָבֹא עָלָיו מַיִם אוֹ כָל מַשְׁקֶה אֲשֶׁר יִשָּׁתֶה בְּכָל כְּלִי, יִטְמָא הָאֹכֶל, וְעוֹד לָמְדוּ רַבּוֹתֵינוּ מִכָּאן שֶׁאֵין וְלַד הַטֻּמְאָה מְטַמֵּא כֵלִים שֶׁכָּךְ שָׁנִינוּ (פסחים פ'), יָכוֹל יְהוּ כָל הַכֵּלִים מִטַּמְּאִין מֵאֲוִיר כְּלִי חֶרֶס תַּ"ל כֹּל אֲשֶׁר בְּתוֹכוֹ יִטְמָא מִכָּל הָאֹכֶל — אֹכֶל (וּמַשְׁקֶה) מִטַּמֵּא מֵאֲוִיר כְּלִי חֶרֶס וְאֵין כָּל הַכֵּלִים מִטַּמְּאִין מֵאֲוִיר כְּלִי חֶרֶס — לְפִי שֶׁהַשֶּׁרֶץ אַב הַטֻּמְאָה וְהַכְּלִי שֶׁנִּטְמָא מִמֶּנּוּ וְלַד הַטֻּמְאָה, לְפִיכָךְ אֵינוֹ חוֹזֵר וּמְטַמֵּא כֵלִים שֶׁבְּתוֹכוֹ, וְלָמַדְנוּ עוֹד שֶׁהַשֶּׁרֶץ שֶׁנָּפַל לַאֲוִיר הַתַּנּוּר וְהַפַּת בְּתוֹכוֹ וְלֹא נָגַע הַשֶּׁרֶץ בַּפַּת, הַתַּנּוּר רִאשׁוֹן וְהַפַּת שְׁנִיָּה, וְלֹא נֹאמַר רוֹאִין אֶת הַתַּנּוּר כְּאִלּוּ מָלֵא טֻמְאָה וּתְהֵא הַפַּת תְּחִלָּה, שֶׁאִם אַתָּה אוֹמֵר כֵּן, לֹא נִתְמַעֲטוּ כָל הַכֵּלִים מִלִּטַּמֵּא מֵאֲוִיר כְּלִי חֶרֶס, שֶׁהֲרֵי טֻמְאָה עַצְמָהּ נָגְעָה בָּהֶן מִגַּבָּן, וְלָמַדְנוּ עוֹד עַל בִּיאַת מַיִם שֶׁאֵינָהּ מַכְשֶׁרֶת זְרָעִים אֶלָּא אִם כֵּן נָפְלוּ עֲלֵיהֶן מִשֶּׁנִּתְלְשׁוּ, שֶׁאִם אַתָּה אוֹמֵר מְקַבְּלִין הֶכְשֵׁר בִּמְחֻבָּר, אֵין לְךָ שֶׁלֹּא בָאוּ עָלָיו מַיִם, וּמַהוּ אוֹמֵר אֲשֶׁר יָבֹא עָלָיו מַיִם? וְלָמַדְנוּ עוֹד שֶׁאֵין אֹכֶל מְטַמֵּא אֲחֵרִים אֶלָּא אִם כֵּן יֵשׁ בּוֹ כַּבֵּיצָה, שֶׁנֶּאֱמַר אֲשֶׁר "יֵאָכֵל" — אֹכֶל הַנֶּאֱכָל בְּבַת אֶחָת, וְשִׁעֲרוּ חֲכָמִים אֵין בֵּית הַבְּלִיעָה מַחֲזִיק יוֹתֵר מִבֵּיצַת תַּרְנְגֹלֶת (ספרא; יומא פ'):
@79 **תנור וכירים.** כֵּלִים הַמִּטַּלְטְלִין הֵם, וְהֵן שֶׁל חֶרֶס וְיֵשׁ לָהֶן תָּוֶךְ, וְשׁוֹפֵת עַל נֶקֶב הֶחָלָל אֶת הַקְּדֵרָה, וּשְׁנֵיהֶם פִּיהֶם לְמַעְלָה:
@79 **יתץ.** שֶׁאֵין לִכְלֵי חֶרֶס טָהֳרָה בִּטְבִילָה:
@79 **וטמאים יהיו לכם.** שֶׁלֹּא תֹאמַר מְצֻוֶּה אֲנִי לְנָתְצָם, תַּלְמוּד לוֹמַר וּטְמֵאִים יִהְיוּ לָכֶם — אִם רָצָה לְקַיְּמָן בְּטֻמְאָתָן רַשַּׁאי:
@80 **אך מעין ובור מקוה מים.** הַמְחֻבָּרִים לַקַּרְקַע אֵין מְקַבְּלִין טֻמְאָה, וְעוֹד יֵשׁ לְךָ לִלְמֹד, **יהיה טהור** — הַטּוֹבֵל בָּהֶם מִטֻּמְאָתוֹ:
@80 **ונגע בנבלתם יטמא.** אֲפִלּוּ הוּא בְּתוֹךְ מַעְיָן וּבוֹר וְנוֹגֵעַ בְּטֻמְאָתָם יִטְמָא; שֶׁלֹּא תֹאמַר קַל וָחֹמֶר: אִם מְטַהֵר אֶת הַטְּמֵאִים מִטֻּמְאָתָם קַל וָחֹמֶר שֶׁיַּצִּיל אֶת הַטָּהוֹר מִלִּטַּמֵּא לְכָךְ נֶאֱמַר וְנֹגֵעַ בְּנִבְלָתָם יִטְמָא (נדרים ע"ה):
@81 **זרע זרוע.** זְרִיעָה שֶׁל מִינֵי זֵרְעוֹנִין; זֵרוּעַ שֵׁם דָּבָר הוּא, כְּמוֹ וְיִתְּנוּ לָנוּ מִן הַזֵּרֹעִים (דניאל א'):
@81 **טהור הוא.** לִמֶּדְךָ הַכָּתוּב שֶׁלֹּא הֻכְשַׁר וְנִתְקַן לִקָּרוֹת אֹכֶל לְקַבֵּל טֻמְאָה עַד שֶׁיָּבֹאוּ עָלָיו מָיִם:
@82 **וכי יתן מים על זרע.** לְאַחַר שֶׁנִּתְלַשׁ, שֶׁאִם תֹּאמַר יֵשׁ הֶכְשֵׁר בִּמְחֻבָּר, אֵין לְךָ זֶרַע שֶׁלֹּא הֻכְשָׁר (חולין קי"ח):
@82 **מים על זרע.** בֵּין מַיִם בֵּין שְׁאָר מַשְׁקִין, בֵּין הֵם עַל הַזֶּרַע בֵּין זֶרַע נוֹפֵל לְתוֹכָן, הַכֹּל נִדְרָשׁ בְּתוֹרַת כֹּהֲנִים:
@82 **ונפל מנבלתם עליו.** אַף מִשֶּׁנֻּגַּב מִן הַמַּיִם, שֶׁלֹּא הִקְפִּידָה תוֹרָה אֶלָּא לִהְיוֹת עָלָיו שֵׁם אֹכֶל, וּמִשֶּׁיָּרַד לוֹ הֶכְשֵׁר קַבָּלַת טֻמְאָה פַּעַם אַחַת, שׁוּב אֵינוֹ נֶעֱקָר הֵימֶנּוּ:
@83 **בנבלתה.** וְלֹא בָעֲצָמוֹת וְגִידִין וְלֹא בַקַּרְנַיִם וּטְלָפַיִם וְלֹא בָעוֹר (ספרא):
@84 **והנשא את נבלתה.** חֲמוּרָה טֻמְאַת מַשָּׂא מִטֻּמְאַת מַגָּע, שֶׁהַנּוֹשֵׂא מְטַמֵּא בְגָדִים, וְהַנּוֹגֵעַ אֵין בְּגָדָיו טְמֵאִין, שֶׁלֹּא נֶאֱמַר בּוֹ יְכַבֵּס בְּגָדָיו:
@84 **והאכל מנבלתה.** יָכוֹל תְּטַמְּאֶנּוּ אֲכִילָתוֹ? כְּשֶׁהוּא אוֹמֵר בְּנִבְלַת עוֹף טָהוֹר (ויקרא כ"ב) "נְבֵלָה וּטְרֵפָה לֹא יֹאכַל לְטָמְאָה בָהּ", בָהּ — אוֹתָהּ מְטַמָּא בְגָדִים בַּאֲכִילָתָהּ וְאֵין נִבְלַת בְּהֵמָה מְטַמָּא בְגָדִים בַּאֲכִילָתָהּ בְּלֹא מַשָּׂא, כְּגוֹן אִם תְּחָבָהּ לוֹ חֲבֵרוֹ בְּבֵית הַבְּלִיעָה, אִם כֵּן מַה תַּ"ל הָאֹכֵל? לִתֵּן שִׁעוּר לַנּוֹשֵׂא וְלַנּוֹגֵעַ כְּדֵי אֲכִילָה, וְהוּא כַּזַּיִת (ספרא; נדה מ"ב):
@84 **וטמא עד הערב.** אַף עַל פִּי שֶׁטָּבַל צָרִיךְ הַעֲרֵב שֶׁמֶשׁ:
@85 **השרץ על הארץ.** לְהוֹצִיא אֶת הַיַּתּוּשִׁין שֶׁבַּכְּלִיסִין וְשֶׁבַּפּוֹלִין, וְאֶת הַזִּיזִין שֶׁבָּעֲדָשִׁים, שֶׁהֲרֵי לֹא שָׁרְצוּ עַל הָאָרֶץ אֶלָּא בְּתוֹךְ הָאֹכֶל, אֲבָל מִשֶּׁיָּצְאוּ לָאֲוִיר וְשָׁרְצוּ הֲרֵי נֶאֱסְרוּ (ספרא; חולין ס"ז):
@85 **לא יאכל.** לְחַיֵּב עַל הַמַּאֲכִיל כָּאוֹכֵל; וְאֵין קָרוּי שֶׁרֶץ אֶלָּא דָּבָר נָמוּךְ, קְצַר רַגְלַיִם, שֶׁאֵינוֹ נִרְאֶה אֶלָּא כְּרוֹחֵשׁ וְנָד:
@86 **הולך על גחון.** זֶה נָחָשׁ, וּלְשׁוֹן גָּחוֹן שְׁחִיָּה, שֶׁהוֹלֵךְ שָׁח וְנוֹפֵל עַל מֵעָיו:
@86 **כל הולך.** לְהָבִיא הַשִּׁלְשׁוּלִין וְאֶת הַדּוֹמֶה לַדּוֹמֶה:
@86 **הולך על ארבע.** זֶה עַקְרָב:
@86 **כל.** לְהָבִיא אֶת הַחִפּוּשִׁית, אשקר"בוט בְּלַעַז, וְאֶת הַדּוֹמֶה לַדּוֹמֶה:
@86 **מרבה רגלים.** זֶה נַדָּל, שֶׁרֶץ שֶׁיֵּשׁ לוֹ רַגְלַיִם מֵרֹאשׁוֹ וְעַד זְנָבוֹ לְכָאן וּלְכָאן, וְקוֹרִין צינטפי"דש (ספרא):
@87 **אל תשקצו.** בַּאֲכִילָתָן, שֶׁהֲרֵי כְּתִיב נַפְשֹׁתֵיכֶם וְאֵין שִׁקּוּץ נֶפֶשׁ בְּמַגָּע, וְכֵן וְלֹא תְטַמְּאוּ בַּאֲכִילָתָם:
@87 **ונטמתם בם.** אִם אַתֶּם מִטַּמְּאִין בָּהֶם בָּאָרֶץ, אַף אֲנִי מְטַמֵּא אֶתְכֶם בָּעוֹלָם הַבָּא וּבִישִׁיבַת מַעְלָה (יומא ל"ט):
@88 **כי אני ה' אלהיכם.** כְּשֵׁם שֶׁאֲנִי קָדוֹשׁ שֶׁאֲנִי ה' אֱלֹהֵיכֶם, כָּךְ וְהִתְקַדִּשְׁתֶּם — קַדְּשׁוּ עַצְמְכֶם לְמַטָּה:
@88 **והייתם קדשים.** לְפִי שֶׁאֲנִי אֲקַדֵּשׁ אֶתְכֶם לְמַעְלָה וּבָעוֹלָם הַבָּא:
@88 **ולא תטמאו וגו'.** לַעֲבֹר עֲלֵיהֶם בְּלָאוִין הַרְבֵּה, וְכָל לָאו מַלְקוּת, וְזֶהוּ שֶׁאָמְרוּ בַּתַּלְמוּד (מכות ט"ז:), אָכַל פּוּטִיתָא לוֹקֶה אַרְבַּע, נְמָלָה לוֹקֶה חָמֵשׁ, צִרְעָה לוֹקֶה שֵׁשׁ:
@89 **כי אני ה' המעלה אתכם.** עַל מְנָת שֶׁתְּקַבְּלוּ מִצְוֹתַי הֶעֱלֵיתִי אֶתְכֶם; דָּבָר אַחֵר, כִּי אֲנִי ה' הַמַּעֲלֶה אֶתְכֶם: בְּכֻלָּן כְּתִיב "הוֹצֵאתִי" וְכָאן כְּתִיב "הַמַּעֲלֶה", תָּנָא דְבֵי רַ' יִשְׁמָעֵאל אִלְּמָלֵי לֹא הֶעֱלֵיתִי אֶת יִשְֹרָאֵל מִמִּצְרַיִם אֶלָּא בִּשְׁבִיל שֶׁאֵין מִטַּמְּאִין בִּשְׁרָצִים כִּשְׁאָר אֻמּוֹת דַּיָּם, וּמַעַלְיוּתָא הִיא גַּבַּיְהוּ, זֶהוּ לְשׁוֹן מַעֲלָה:
@91 **להבדיל.** לֹא בִּלְבַד הַשּׁוֹנֶה, אֶלָּא שֶׁתְּהֵא יוֹדֵעַ וּמַכִּיר וּבָקִי בָּהֶן (ספרא):
@91 **בין הטמא ובין הטהר.** צָרִיךְ לוֹמַר בֵּין חֲמוֹר לְפָרָה, וַהֲלֹא כְבָר מְפֹרָשִׁים הֵם? אֶלָּא בֵּין טְמֵאָה לְךָ לִטְהוֹרָה לְךָ — בֵּין נִשְׁחַט חֶצְיוֹ שֶׁל קָנֶה לְנִשְׁחַט רֻבּוֹ:
@91 **ובין החיה הנאכלת.** צָרִיךְ לוֹמַר בֵּין צְבִי לְעָרוֹד וַהֲלֹא כְבָר מְפֹרָשִׁים הֵם? אֶלָּא בֵּין שֶׁנּוֹלְדוּ בָהּ סִימָנֵי טְרֵפָה כְּשֵׁרָה לְנוֹלְדוּ בָהּ סִימָנֵי טְרֵפָה פְּסוּלָה (ספרא):

@2 **וַיֹּאמֶר אֶל אַהֲרֹן קַח לְךָ עֵגֶל בֶּן בָּקָר** נִצְטַוָּה מֹשֶׁה רַבֵּינוּ בַּקָּרְבָּנוֹת הַלָּלוּ כְּמוֹ שֶׁאָמַר בַּסּוֹף "זֶה הַדָּבָר אֲשֶׁר צִוָּה ה' תַּעֲשׂוּ" וְאִם לֹא נִזְכַּר זֶה, וְכֵן "וַיֹּאמֶר מֹשֶׁה זֶה הַדָּבָר אֲשֶׁר צִוָּה ה' מְלֹא הָעֹמֶר מִמֶּנּוּ לְמִשְׁמֶרֶת" (שמות טז לב), וְכֵן "אָנֹכִי הָאֵל בֵּית אֵל" (בראשית לא יג), סִפֵּר יַעֲקֹב זֶה וְאִם לֹא נִזְכְּרָה הָאֲמִירָה לוֹ. וּכְבָר הֶרְאִיתִיךָ בַּפָּרָשִׁיּוֹת שֶׁל מִצְוַת הַפֶּסַח (שמות יא א) כָּאֵלֶּה רַבּוֹת:
@3 וְטַעַם **וְאֶל בְּנֵי יִשְׂרָאֵל תְּדַבֵּר לֵאמֹר** שֶׁיֹּאמַר לָהֶם אַהֲרֹן כֵּן, כִּי רָצָה שֶׁיִּהְיֶה אַהֲרֹן הַמְּצַוֶּה בְּשֵׁם ה' וְהוּא הַמַּקְרִיב הַקָּרְבָּנוֹת, לְגַדְּלוֹ בְּעֵינֵי הָעָם. וְהַנָּכוֹן שֶׁטַּעְמוֹ וְאֶל בְּנֵי יִשְׂרָאֵל תְּדַבֵּר אַתָּה וְהַזְּקֵנִים הַנִּזְכָּרִים, כִּי לְכָךְ קְרָאָם שֶׁיְּדַבְּרוּ לְיִשְׂרָאֵל, כְּדֶרֶךְ "וַיִּקְרָא מֹשֶׁה לְכָל זִקְנֵי יִשְׂרָאֵל וַיֹּאמֶר אֲלֵיהֶם מִשְׁכוּ" (שמות יב כא), אוֹ אָמַר לְכָל אֶחָד מִן הַזְּקֵנִים "וְאֶל בְּנֵי יִשְׂרָאֵל תְּדַבֵּר", וְשִׁעוּר הַפָּרָשָׁה וַיֹּאמֶר אֶל אַהֲרֹן קַח לְךָ, וְאֶל הַזְּקֵנִים אָמַר וְאֶל בְּנֵי יִשְׂרָאֵל תְּדַבֵּר לֵאמֹר, כִּי הַמְדַבֵּר לָרַבִּים יֹאמַר סְתָם לְכָל אֶחָד מִצְוָתוֹ, כְּדֶרֶךְ "וָאֲצַו אֶתְכֶם בָּעֵת הַהִיא לֵאמֹר וְגוֹ' חֲלוּצִים תַּעַבְרוּ" (דברים ג יח), וְכֵן רַבִּים בְּמִשְׁנֵה תּוֹרָה. וְר"א אָמַר (אבן עזרא על ויקרא ט':ו') כִּי טַעַם "וַיֹּאמֶר מֹשֶׁה זֶה הַדָּבָר אֲשֶׁר צִוָּה ה' תַּעֲשׂוּ" (שם) שֶׁכְּבָר אָמַר לָהֶם מֹשֶׁה זֶה הַדָּבָר, וְאִם כֵּן יִתָּכֵן שֶׁיִּהְיֶה שִׁעוּר הַפְּסוּקִים הָאֵלֶּה כָּךְ, קָרָא מֹשֶׁה לְאַהֲרֹן וּלְבָנָיו וּלְזִקְנֵי יִשְׂרָאֵל, וַיֹּאמֶר מֹשֶׁה זֶה הַדָּבָר אֲשֶׁר צִוָּה ה' אוֹתִי תַּעֲשׂוּ וְיֵרָא אֲלֵיכֶם כְּבוֹד ה', וַיֹּאמֶר אֶל אַהֲרֹן קַח לְךָ עֵגֶל וְגוֹ', וְאֶל בְּנֵי יִשְׂרָאֵל תְּדַבֵּר לֵאמֹר קְחוּ לָכֶם שְׂעִיר עִזִּים. וְהִנֵּה קִצֵּר בַּתְּחִלָּה וּפֵרֵשׁ בַּסּוֹף. וְאֵינֶנּוּ נָכוֹן, אֲבָל אַחַר שֶׁהִזְכִּיר לָהֶם הַקָּרְבָּנוֹת "וַיִּקְחוּ אֵת אֲשֶׁר צִוָּה מֹשֶׁה", חָזַר וְאָמַר לָהֶם "זֶה הַדָּבָר אֲשֶׁר צִוָּה ה' תַּעֲשׂוּ", שֶׁיַּקְרִיבוּ הַקָּרְבָּנוֹת עַל הַסֵּדֶר שֶׁיְּצַוֵּם וְאַחַר כָּךְ יֵרָאֶה לָהֶם הַכָּבוֹד, וּבַעֲבוּר שֶׁאָמַר "כִּי הַיּוֹם ה' נִרְאָה אֲלֵיכֶם" חָזַר וְאָמַר שֶׁיֵּרָאֶה לָהֶם בִּכְבוֹדוֹ. וְהִנֵּה הַקָּרְבָּנוֹת הָאֵלּוּ לֹא הֻזְכְּרוּ בְּפָרָשַׁת "וְזֶה הַדָּבָר אֲשֶׁר תַּעֲשֶׂה לָהֶם לְקַדֵּשׁ אֹתָם לְכַהֵן לִי" (שמות כט א), כִּי שָׁם לֹא צִוָּה רַק עַל הַמִּלּוּאִים, וּבְשִׁבְעַת הַיָּמִים וְקָרְבְּנוֹתֵיהֶם מָלְאוּ יְמֵי מִלּוּאֵיהֶם, כִּי עַתָּה בַּיּוֹם הַשְּׁמִינִי הֵם עַצְמָם יַקְרִיבוּ הַקָּרְבָּנוֹת, וְהִנֵּה הַקָּרְבָּנוֹת הַלָּלוּ כַּחֲנֻכָּה לָהֶם, כְּעִנְיַן מִנְחַת חֲבִתִּים לְדוֹרוֹת בְּיוֹם הִמָּשַׁח אוֹתוֹ (לעיל ו יג יד). וְיִתָּכֵן כִּי לְכַפֵּר עַל מַעֲשֵׂה הָעֵגֶל הוֹסִיף לָהֶם עַתָּה הַקָּרְבָּנוֹת הַלָּלוּ, כִּי כַּאֲשֶׁר צִוָּה "וְזֶה הַדָּבָר אֲשֶׁר תַּעֲשֶׂה לָהֶם לְקַדֵּשׁ אֹתָם" עֲדַיִן לֹא נַעֲשָׂה הָעֵגֶל כַּאֲשֶׁר פֵּרַשְׁתִּי (שם ח ב), לְכָךְ לֹא הִזְכִּירָם שָׁם. וְלֹא כְּדִבְרֵי רַשִׁ"י שֶׁאָמַר שָׁם (שמות כט א) כִּי הַפָּר לְכַפֵּר עַל מַעֲשֵׂה הָעֵגֶל, אֲבָל הָיוּ הַפָּרִים הָהֵם לְחַטֵּא עַל הַמִּזְבֵּחַ וְעַל אַהֲרֹן וְעַל בָּנָיו וּלְקַדֵּשׁ אוֹתָם, וְהָעֵגֶל הַזֶּה בַּיּוֹם הַשְּׁמִינִי לְכַפֵּר עַל מַעֲשֵׂה הָעֵגֶל. וְהִנֵּה קָרְבַּן אַהֲרֹן כְּקָרְבָּנוֹ בְּיוֹם הַכִּפּוּרִים בְּשָׁוֶה, וְחַטַּאת הָעָם כְּחַטָּאתָם בְּיוֹם הַכִּפּוּרִים, שְׂעִיר עִזִּים אֶחָד לְחַטָּאת. וְכָךְ אָמַר בַּתּוֹסֶפְתָּא שֶׁל פָּרָשַׁת מִלּוּאִים בְּת"כ (שמיני מלואים ד), שֶׁהָעֵגֶל הַזֶּה לְכַפֵּר עַל מַעֲשֵׂה הָעֵגֶל. וְדָרְשׁוּ, וְכִי מָה רָאוּ יִשְׂרָאֵל לְהָבִיא יוֹתֵר מֵאַהֲרֹן, אֶלָּא אָמַר לָהֶם יֵשׁ בְּיֶדְכֶם בַּתְּחִלָּה וְיֵשׁ בְּיֶדְכֶם בַּסּוֹף, יֵשׁ בְּיֶדְכֶם בַּתְּחִלָּה שֶׁנֶּאֱמַר (בראשית לז לא) "וַיִּשְׁחֲטוּ שְׂעִיר עִזִּים", וְיֵשׁ בְּיֶדְכֶם בַּסּוֹף שֶׁנֶּאֱמַר (שמות לב ח) "עָשׂוּ לָהֶם עֵגֶל מַסֵּכָה", יָבֹא שָׂעִיר וִיכַפֵּר עַל מַעֲשֵׂה שָׂעִיר, יָבֹא עֵגֶל וִיכַפֵּר עַל מַעֲשֵׂה עֵגֶל. וְנִרְאֶה כִּי בַּעֲבוּר הֱיוֹת טַעַם הַחַטָּאת שֶׁל אַהֲרֹן כְּטַעְמוֹ בְּיוֹם הַכִּפּוּרִים, שָׂרַף אוֹתוֹ כַּאֲשֶׁר יִשָּׂרֵף שֶׁל יוֹם הַכִּפּוּרִים אַף עַל פִּי שֶׁהָיָה זֶה חַטָּאת חִיצוֹנָה, כִּי לֹא פֵּרֵשׁ מֹשֶׁה שֶׁיַּעֲשֶׂה כֵן. וְאוּלַי נִצְטַוָּה בְּכָךְ וְהַכָּתוּב לֹא חָשַׁשׁ לְהַאֲרִיךְ, כִּי לֹא יַעֲשֶׂה רַק מָה שֶׁיֹּאמַר מֹשֶׁה וְלֹא יֹאמַר מֹשֶׁה רַק מָה שֶׁצִּוָּה ה':
@7 וְטַעַם **קְרַב אֶל הַמִּזְבֵּחַ וַיִּקְרַב אַהֲרֹן אֶל הַמִּזְבֵּחַ וַיִּשְׁחַט** עַל דַּעְתִּי בְּדֶרֶךְ הַפְּשָׁט יֹאמַר קְרַב אֶל צְפוֹן הַמִּזְבֵּחַ וַעֲשֵׂה שָׁם הַחַטָּאת וְהָעוֹלָה, כִּי הֵם שְׁחִיטָתָן בַּצָּפוֹן. וְאָמַר מֹשֶׁה כֵּן בְּדֶרֶךְ קְצָרָה, שֶׁכְּבָר יָדַע אַהֲרֹן זֶה. אֲבָל בְּת"כ (שמיני מלואים ח) נִתְעוֹרְרוּ רַבּוֹתֵינוּ בָּזֶה וּמָשְׁלוּ מָשָׁל לְמָה הַדָּבָר דּוֹמֶה, לְמֶלֶךְ בָּשָׂר וָדָם שֶׁנָּשָׂא אִשָּׁה וְהָיְתָה מִתְבַּיֶּשֶׁת מִלְּפָנָיו, נִכְנְסָה אֶצְלָהּ אֲחוֹתָהּ, אָמְרָה לָהּ, אֲחוֹתִי לָמָּה נִכְנַסְתְּ לְדָבָר זֶה, לֹא שֶׁתְּשַׁמְּשִׁי אֶת הַמֶּלֶךְ, הָגִיסִי דַּעְתֵּךְ וּבוֹאִי שַׁמְּשִׁי אֶת הַמֶּלֶךְ. כָּךְ אָמַר לוֹ מֹשֶׁה לְאַהֲרֹן, אַהֲרֹן אָחִי, לָמָּה נִבְחַרְתָּ לִהְיוֹת כֹּהֵן גָּדוֹל, לֹא שֶׁתְּשָׁרֵת לִפְנֵי הַמָּקוֹם, הָגֵס דַּעְתְּךָ וּבוֹא וַעֲבֹד עֲבוֹדָתְךָ. וְיֵשׁ אוֹמְרִים הָיָה אַהֲרֹן רוֹאֶה אֶת הַמִּזְבֵּחַ כְּתַבְנִית שׁוֹר, וְהָיָה מִתְיָרֵא מִמֶּנּוּ. נִכְנַס מֹשֶׁה אֶצְלוֹ, אָמַר לוֹ, אַהֲרֹן אָחִי, לֹא תִּירָא מִמַּה שֶׁאַתָּה מִתְיָרֵא, הָגֵס דַּעְתְּךָ וּבֹא קְרַב אֵלָיו. לְכָךְ אָמַר "קְרַב אֶל הַמִּזְבֵּחַ וַיִּקְרַב אֶל הַמִּזְבֵּחַ", בִּזְרִיזוּת. וְטַעַם דָּבָר זֶה כִּי בַּעֲבוּר שֶׁהָיָה אַהֲרֹן קְדוֹשׁ ה' וְאֵין בְּנַפְשׁוֹ חֵטְא זוּלָתִי מַעֲשֵׂה הָעֵגֶל, הָיָה הַחֵטְא הַהוּא קָבוּעַ לוֹ בְּמַחְשַׁבְתּוֹ, כְּעִנְיָן שֶׁנֶּאֱמַר (תהלים נא ה) "וְחַטָּאתִי נֶגְדִּי תָמִיד", וְהָיָה נִדְמֶה לוֹ כְּאִלּוּ צוּרַת הָעֵגֶל שָׁם מְעַכֵּב בְּכַפָּרוֹתָיו, וּלְכָךְ אָמַר לוֹ הָגֵס דַּעְתְּךָ, שֶׁלֹּא יִהְיֶה שְׁפַל רוּחַ כָּל כָּךְ, שֶׁכְּבָר רָצָה אֱלֹהִים אֶת מַעֲשָׂיו. וַאֲחֵרִים מְפָרְשִׁים שֶׁהָיָה הַשָּׂטָן מַרְאֶה לוֹ כֵן, כְּמוֹ שֶׁאָמְרוּ שָׁם, אַהֲרֹן אָחִי אַף עַל פִּי שֶׁנִּתְרַצָּה הַמָּקוֹם לְכַפֵּר עֲוֹנֹתֶיךָ צָרִיךְ אַתָּה לִתֵּן לְתוֹךְ פִּיו שֶׁל שָׂטָן, שֶׁמָּא יַשְׂטִינְךָ בְּבִיאָתְךָ לַמִּקְדָּשׁ וכו', בְּתוֹרַת כֹּהֲנִים (שמיני מלואים ג). וְטַעַם "וְכַפֵּר בַּעַדְךָ וּבְעַד הָעָם", יֹאמַר קְרַב אֶל הַמִּזְבֵּחַ לַעֲשׂוֹת כָּל הַקָּרְבָּנוֹת, וַעֲשֵׂה תְּחִלָּה אֶת חַטָּאתְךָ וְאֶת עֹלָתֶךָ, וְכַפֵּר בַּעַדְךָ תְּחִלָּה בְּקָרְבְּנוֹתֶיךָ וּבְעַד הָעָם אַחֲרֵי כֵן, שֶׁתַּעֲשֶׂה קָרְבַּן הָעָם וְכַפֵּר בַּעֲדָם בְּקָרְבָּנָם. לִמֵּד אוֹתוֹ שֶׁיָּבֹא זַכַּאי וִיכַפֵּר עַל הַחַיָּב (יומא מג):
@17 **מִלְּבַד עֹלַת הַבָּקָר** הֻצְרַךְ הַכָּתוּב לְהַזְכִּיר זֶה בְּכָאן לְלַמֵּד שֶׁאֵין עוֹלַת הָעָם פּוֹטֶרֶת עוֹלַת הַתָּמִיד וְלֹא קוֹדֶמֶת לָהּ. וְלֹא הֻצְרַךְ לְהַזְכִּיר כֵּן בִּימֵי הַמִּלּוּאִים, לְפִי שֶׁהֵם קָרְבְּנוֹת יָחִיד לְמַלֵּא יַד הַכֹּהֲנִים, וּבְיָדוּעַ שֶׁלֹּא פָּטְרוּ אֶת הַתָּמִיד וְלֹא קָדְמוּ אֵלָיו. וּבְתוֹרַת כֹּהֲנִים (שמיני מלואים יב) שָׁנוּ, "וַיַּקְטֵר עַל הַמִּזְבֵּחַ מִלְּבַד עֹלַת הַבֹּקֶר", מָה בָּא זֶה לְלַמְּדֵנוּ, אִם לְלַמֵּד שֶׁאִם לֹא מָצָא מִנְחָה יָבִיא בְּהֵמָה, וַהֲלֹא כְּבָר נֶאֱמַר (ויקרא ט':ט"ז) "וַיַּקְרֵב אֶת הָעֹלָה וַיַּעֲשֶׂהָ כַּמִּשְׁפָּט", אִם כֵּן לָמָּה נֶאֱמַר "וַיַּקְטֵר עַל הַמִּזְבֵּחַ מִלְּבַד עֹלַת הַבֹּקֶר", מְלַמֵּד שֶׁשְּׁתֵּי מְנָחוֹת הָיוּ שָׁם, אַחַת עַל הָעוֹלָה וְאַחַת בִּפְנֵי עַצְמָהּ. וּפֵרוּשׁוֹ שֶׁאִלּוּ אָמַר "וַיַּקְרֵב אֶת הָעֹלָה וַיַּעֲשֶׂהָ כַּמִּשְׁפָּט מִלְּבַד עֹלַת הַבֹּקֶר" הָיָה לְלַמֵּד שֶׁהַתָּמִיד קוֹדֵם, כְּמוֹ שֶׁאוֹמֵר בְּפָרָשַׁת הַמּוּסָפִין "עַל עֹלַת הַתָּמִיד יֵעָשֶׂה וְנִסְכּוֹ" (במדבר כח טו), "מִלְּבַד עֹלַת הַתָּמִיד" (שם פסוק לא), אֲבָל כְּשֶׁהִזְכִּיר הַמִּנְחָה "וַיַּקְרֵב אֶת הַמִּנְחָה וַיְמַלֵּא כַפּוֹ מִמֶּנָּה וַיַּקְטֵר עַל הַמִּזְבֵּחַ מִלְּבַד עֹלַת הַבֹּקֶר" נִרְאֶה שֶׁעַל הַמִּנְחָה הוּא אוֹמֵר, וּלְפִיכָךְ דִּקְדְּקוּ שֶׁאִם בָּא לוֹמַר שֶׁהִקְרִיב זוֹ הַמִּנְחָה לְבַדָּהּ וְלֹא הִקְרִיב מִנְחַת נְסָכִים לְתָמִיד וְלֹא לְעוֹלַת הָעָם, שֶׁלֹּא מָצָא אֶלָּא לִנְדָבָה זוֹ, וַהֲלֹא כְּבָר נֶאֱמַר "וַיַּקְרֵב אֶת הָעֹלָה וַיַּעֲשֶׂהָ כַּמִּשְׁפָּט", שֶׁקָּרְבָה כְּמִשְׁפָּטָהּ בְּמִנְחַת נְסָכִים, אִם כֵּן לָמָּה נֶאֱמַר "וַיַּקְרֵב וַיַּקְטֵר עַל הַמִּזְבֵּחַ מִלְּבַד עֹלַת הַבֹּקֶר", לוֹמַר שֶׁהִקְרִיב הַמִּנְחָה הַזּוֹ מִלְּבַד עוֹלַת הַבֹּקֶר וּמִנְחָתָהּ, שֶׁאֵין הַמִּנְחָה הַזּוֹ מִנְחַת נְסָכִים אֶלָּא מִנְחַת נְדָבָה שֶׁל יִשְׂרָאֵל:
@19 **וְהַמְּכַסֶּה** חֵלֶב הַמְכַסֶּה אֶת הַקֶּרֶב, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא ט':י"ט). וְאֵינֶנּוּ נָכוֹן בְּעֵינַי, כִּי לָמָּה יַזְכִּיר הַחֵלֶב הַזֶּה וְלֹא יַזְכִּיר הַחֲלָבִים הָאֲחֵרִים. אֲבָל עַל דַּעְתִּי "הַמְכַסֶּה" שֵׁם לְכֻלָּם, כִּי כָּל חֵלֶב שֶׁיִּקְרַב לְגַבֵּי הַמִּזְבֵּחַ הוּא מְכַסֶּה, כִּי הָאֶחָד חֵלֶב הַמְכַסֶּה אֶת הַקֶּרֶב וְהַשֵּׁנִי כָּל הַחֵלֶב אֲשֶׁר עַל הַקֶּרֶב וְגַם הוּא מְכַסֶּה, וְהַחֵלֶב אֲשֶׁר עַל הַכְּלָיוֹת יְכַסֶּה עֲלֵיהֶן, וְכֵן אֲשֶׁר עַל הַכְּסָלִים, וּכְמוֹ שֶׁאָמְרוּ (חולין צג) חֵלֶב שֶׁהַבָּשָׂר חוֹפֶה אוֹתוֹ מֻתָּר, שֶׁעַל הַכְּסָלִים אָמַר רַחֲמָנָא וְלֹא שֶׁבְּתוֹךְ הַכְּסָלִים. וְהִנֵּה הַכָּתוּב הַזֶּה נִמְשָׁךְ לְמַעְלָה, "וַיַּמְצִאוּ בְּנֵי אַהֲרֹן אֵלָיו אֶת הַדָּם" שֶׁל שׁוֹר וְאַיִל הַנִּזְכָּרִים, "וְאֶת הַחֲלָבִים מִן הַשּׁוֹר", אֲבָל מִן הָאַיִל הִמְצִיאוּ אֵלָיו הָאַלְיָה וְהַחֵלֶב, וּמִשְּׁנֵיהֶם הַכְּלָיוֹת וְיוֹתֶרֶת הַכָּבֵד. וְאָמַר **וַיָּשִׂימוּ אֶת הַחֲלָבִים עַל הֶחָזוֹת** כִּי הָאַלְיָה וְהַכְּלָיוֹת וְיוֹתֶרֶת הַכָּבֵד יִתְּנוּ לְמַטָּה וְהַחֲלָבִים עֲלֵיהֶן, וְהַכֹּל עַל הֶחָזוֹת. וְהִנֵּה הַחֲלָבִים לְבַדָּם יֵרָאוּ לְמַעְלָה, וְהוּא דֶּרֶךְ כָּבוֹד בַּהַקְטָרָה:
@20 **וַיַּקְטֵר הַחֲלָבִים הַמִּזְבֵּחָה** עִם שְׁאָר הַנִּזְכָּרִים, אֲבָל בַּעֲבוּר הֱיוֹת הַהַקְטָרָה גְּדוֹלָה בַּחֲלָבִים יַזְכִּירֵם. וְכֵן "וַתֹּאכַל עַל הַמִּזְבֵּחַ אֶת הָעֹלָה וְאֶת הַחֲלָבִים" (ויקרא ט':כ"ד):
@22 **וַיִּשָּׂא אַהֲרֹן אֶת יָדָיו אֶל הָעָם וַיְבָרְכֵם** בִּרְכַּת כֹּהֲנִים, יְבָרֶכְךָ יָאֵר יִשָּׂא, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא ט':כ"ב). וְאִם כֵּן תִּהְיֶה פָּרָשַׁת "דַּבֵּר אֶל אַהֲרֹן וְאֶל בָּנָיו לֵאמֹר כֹּה תְבָרֲכוּ אֶת בְּנֵי יִשְׂרָאֵל" שֶׁבְּחֻמַּשׁ הַפְּקוּדִים (במדבר ו כג) מֻקְדֶּמֶת לָזֶה. וְאוּלַי כֵּן הוּא, כִּי סְמוּכָה לְמָה שֶׁנֶּאֱמַר שָׁם (ז א) "וַיְהִי בְּיוֹם כַּלּוֹת מֹשֶׁה לְהָקִים אֶת הַמִּשְׁכָּן". וְיִתָּכֵן לוֹמַר כִּי אַהֲרֹן פֵּרֵשׂ כַּפָּיו הַשָּׁמַיִם וּבֵרַךְ אֶת הָעָם כַּאֲשֶׁר עָשָׂה שְׁלֹמֹה, שֶׁנֶּאֱמַר (מלכים א ח כב) "וַיַּעֲמֹד שְׁלֹמֹה לִפְנֵי מִזְבַּח ה' וַיִּפְרֹשׂ כַּפָּיו הַשָּׁמָיִם", וְשָׁם (ויקרא ט':נ"ה) נֶאֱמַר "וַיַּעְמֹד וַיְבָרֶךְ אֵת כָּל קְהַל יִשְׂרָאֵל קוֹל גָּדוֹל לֵאמֹר", וּלְפִיכָךְ לֹא הִזְכִּיר הַכָּתוּב שֶׁצִּוָּה אוֹתוֹ מֹשֶׁה לַעֲשׂוֹת כֵּן. וּבַבָּרַיְתָא שֶׁל פָּרָשַׁת מִלּוּאִים בְּת"כ (ריש פרשת שמיני ל) רָאִיתִי "וַיְבָרְכֵם" זוֹ בְּרָכָה סְתוּמָה שֶׁאִי אַתָּה יוֹדְעָהּ, חָזַר הַכָּתוּב וּפֵרֵשׁ לְהַלָּן "יְבָרֶכְךָ ה' וְיִשְׁמְרֶךָ יָאֵר ה' פָּנָיו אֵלֶיךָ וִיחֻנֶּךָּ יִשָּׂא ה' פָּנָיו אֵלֶיךָ" וְגוֹ', וַעֲדַיִן יֵשׁ לִי לוֹמַר שֶׁכָּךְ אָמְרוּ בְּרָכָה זוֹ שֶׁבֵּרַךְ אַהֲרֹן אֶת הָעָם מֵעַצְמוֹ סְתוּמָה הִיא וְלֹא פֵּרֵשׁ לָנוּ הַכָּתוּב מַה הִיא, אֲבָל בְּרָכָה שֶׁנִּצְטַוּוּ הַכֹּהֲנִים לְדוֹרוֹת נִתְפָּרְשָׁה וְהִיא שָׁוָה בְּכָל הַכֹּהֲנִים לְעוֹלָם, אוֹ שֶׁהֵם סְבוּרִים שֶׁכָּאן צִוָּה אוֹתוֹ בִּנְשִׂיאוּת כַּפַּיִם לְיוֹם זֶה וּלְהַלָּן נִתְּנָה בְּרָכָה זוֹ לוֹ וּלְבָנָיו לְדוֹרוֹת:
@26 **וַתֵּצֵא אֵשׁ מִלִּפְנֵי ה'** - טַעַם "מִלִּפְנֵי ה'" כְּמוֹ "מֵאֵת פְּנֵי ה'". וְהַמַּשְׂכִּיל יִתְבּוֹנֵן, שֶׁכְּבָר פֵּרַשְׁתִּי זֶה (שמות ל א). זֶה הַחֵטְא בְּנָדָב וַאֲבִיהוּא תֵּדָעֶנּוּ מִמַּה שֶׁאָמַר: "וַיַּקְרִבוּ לִפְנֵי ה' אֵשׁ זָרָה", וְלֹא אָמַר "וַיַּקְרִיבוּ לִפְנֵי ה' קְטֹרֶת אֲשֶׁר לֹא צִוָּה אֹתָם". וְהִנֵּה הֵם שָׂמוּ קְטֹרֶת עַל הָאֵשׁ, כְּעִנְיָן שֶׁאָמַר הַכָּתוּב (דברים לג י): "יָשִׂימוּ קְטוֹרָה בְּאַפֶּךָ", וְלֹא שָׂמוּ לִבָּם רַק לָזֹאת. וְהִנֵּה לֹא הָיָה אִשֶּׁה רֵיחַ נִיחוֹחַ. וְזֶה טַעַם "וַיָּשִׂימוּ עָלֶיהָ קְטֹרֶת", שֶׁלֹּא אָמַר "וַיָּשִׂימוּ עֲלֵיהֶן", כַּאֲשֶׁר נֶאֱמַר בַּעֲדַת קֹרַח (במדבר טז ז): "וּתְנוּ בָהֵן אֵשׁ וְשִׂימוּ עֲלֵיהֶן קְטֹרֶת", וְשָׁם עוֹד: "וּנְתַתֶּם עֲלֵיהֶם קְטֹרֶת" (שם פסוק יז). אֲבָל אָמַר בְּכָאן "עָלֶיהָ", לִרְמֹז כִּי עַל הָאֵשׁ בִּלְבַד שָׂמוּ קְטֹרֶת. "וַתֵּצֵא אֵשׁ מִלִּפְנֵי ה' וַתֹּאכַל אוֹתָם". וְיִתָּכֵן שֶׁיִּרְמֹז לָזֶה מַה שֶׁאָמַר (שמות ל ט): "לֹא תַעֲלוּ עָלָיו קְטֹרֶת זָרָה", שֶׁלֹּא יַעֲשׂוּהָ זָרָה. וְהוּא מַה שֶׁנֶּאֱמַר (ויקרא ט"ז:א'): "בְּקָרְבָתָם לִפְנֵי ה' וַיָּמֻתוּ", כִּי בְּהַקְרִיבָם לְפָנָיו מֵתוּ.
@27 **הוּא אֲשֶׁר דִּבֶּר ה' לֵאמֹר** - הֵיכָן דִּבֵּר? "וְנִקְדַּשׁ בִּכְבוֹדִי" (שמות כט, מג). אַל תִּקְרֵי "בִּכְבוֹדִי" אֶלָּא "בִּמְכֻבָּדַי". אָמַר לוֹ מֹשֶׁה לְאַהֲרֹן: "אַהֲרֹן אָחִי, יוֹדֵעַ הָיִיתִי שֶׁיִּתְקַדֵּשׁ הַבַּיִת בִּמְיֻדָּעָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהָיִיתִי סָבוּר אוֹ בִּי אוֹ בְךָ. עַכְשָׁו אֲנִי רוֹאֶה שֶׁהֵם גְּדוֹלִים מִמֶּנִּי וּמִמְּךָ". לְשׁוֹן רַשִׁ"י (רש"י על ויקרא י':ג') מִמִּדְרַשׁ רַבּוֹתֵינוּ (ויק"ר יב, ב). וְאִם כֵּן יִהְיֶה טַעַם "וְנִקְדַּשׁ בִּכְבוֹדִי" - שֶׁיִּהְיֶה קָדוֹשׁ בְּעֵינֵי כָּל הָעָם וּבִמְכֻבָּדַי, וְיֵדְעוּ כִּי אֲנִי שׁוֹכֵן בּוֹ. וְרַבִּי אַבְרָהָם גַּם כֵּן אָמַר: "הוּא אֲשֶׁר דִּבֶּר ה' לֵאמֹר" - כְּבָר אָמַר לִי הַשֵּׁם שֶׁיַּרְאֶה קְדֻשָּׁתוֹ בַּקְּרוֹבִים אֵלָיו, כְּטַעַם "רַק אֶתְכֶם יָדַעְתִּי מִכֹּל מִשְׁפְּחוֹת הָאֲדָמָה" (עמוס ג, ב). וְכַאֲשֶׁר אַרְאֶה בָּם קְדֻשָּׁתִי זוֹ, אָז אֶהְיֶה נִכְבָּד עַל פְּנֵי כָּל הָעָם וְיִירְאוּ מִמֶּנִּי. וְאִם כֵּן הוּא דִּבּוּר לֹא נִכְתַּב, כִּי הַשֵּׁם הוֹדִיעוֹ דְּרָכָיו שֶׁכָּךְ הַמִּדָּה הַזֹּאת לְפָנָיו. וּלְדַעְתִּי בְּדֶרֶךְ הַפְּשָׁט אֵין צֹרֶךְ לְכָל זֶה, כִּי דְּבַר הַשֵּׁם - גְּזֵרוֹתָיו וּמַחְשְׁבוֹתָיו וְעִנְיַן דְּרָכָיו. וְהַדִּבּוּר יֵאָמֵר בְּכָל אֵלֶּה: "דִּבַּרְתִּי אֲנִי עִם לִבִּי" (קהלת א, טז) - חָשַׁבְתִּי מַחְשָׁבָה זוֹ. "וְזֶה הַדָּבָר אֲשֶׁר מָל יְהוֹשֻׁעַ" (יהושע ה, ד) - זֶה הָעִנְיָן. "עַל דְּבַר הַכֶּסֶף" (בראשית מג, יח). וְכֵן "וּתְהִי אִשָּׁה לְבֶן אֲדֹנֶיךָ כַּאֲשֶׁר דִּבֶּר ה'" (שם כד, נא) - גָּזַר. וְכָמוֹהוּ "בַּאֲבִירָם בְּכֹרוֹ יִסְּדָהּ וּבִשְׂגוּב צְעִירוֹ הִצִּיב דְּלָתֶיהָ כִּדְבַר ה' אֲשֶׁר דִּבֶּר בְּיַד יְהוֹשֻׁעַ בִּן נוּן" (מלכים א טז, לד). וְהִנֵּה אָמַר מֹשֶׁה: הַמִּקְרֶה הַזֶּה הוּא אֲשֶׁר גָּזַר הַשֵּׁם לֵאמֹר אֶל לִבּוֹ "בִּקְרֹבַי אֶקָּדֵשׁ", שֶׁלֹּא יֶהֶרְסוּ אֶל קְדֻשָּׁתִי, "וְעַל פְּנֵי כָל הָעָם אֶכָּבֵד", שֶׁיִּהְיוּ נוֹהֲגִים כָּבוֹד בְּמִשְׁכָּנִי.
@27 וְטַעַם **וַיִּדֹּם אַהֲרֹן** - שֶׁהָיָה בּוֹכֶה בְּקוֹל, וְאָז שָׁתַק. אוֹ כְּטַעַם "וְאַל תִּדֹּם בַּת עֵינֵךְ" (איכה ב, יח):
@28 " **קִרְבוּ שְׂאוּ אֶת אֲחֵיכֶם** " - מָצָאתִי בְּתוֹרַת כֹּהֲנִים בְּפָרָשַׁת מִלּוּאִים (ריש שמיני לה): רַבִּי אֱלִיעֶזֶר אוֹמֵר, לֹא מֵתוּ בְּנֵי אַהֲרֹן אֶלָּא בַּחוּץ, מָקוֹם שֶׁהַלְוִיִּם מֻתָּרִין שָׁם לִכָּנֵס, שֶׁנֶּאֱמַר: "וַיִּקְרְבוּ וַיִּשָּׂאֻם בְּכֻתֳּנֹתָם". אִם כֵּן, לָמָּה נֶאֱמַר "וַיָּמֻתוּ לִפְנֵי ה'"? נְגָפָם הַמַּלְאָךְ וְהוֹצִיאָם לַחוּץ. רַבִּי עֲקִיבָא אוֹמֵר: לֹא מֵתוּ אֶלָּא בִּפְנִים, שֶׁנֶּאֱמַר "וַיָּמֻתוּ לִפְנֵי ה'". אִם כֵּן, לָמָּה נֶאֱמַר "וַיִּקְרְבוּ וַיִּשָּׂאֻם בְּכֻתֳּנֹתָם"? שֶׁהֵטִילוּ בָּהֶם חַכּוֹת שֶׁל בַּרְזֶל וּגְרָרוּם וְהוֹצִיאוּם לַחוּץ. עַד כָּאן בַּבָּרַיְתָא. וְהַטַּעַם, שֶׁאַף עַל פִּי שֶׁגַּם הַכֹּהֲנִים אֲסוּרִין לָבֹא בַּהֵיכָל אֶלָּא בִּשְׁעַת עֲבוֹדָה, אֵינוֹ אֶלָּא בְּבִיאָה רֵיקָנִית, אֲבָל לְהוֹצִיא מִשָּׁם טֻמְאָה אוֹ לְבֶדֶק הַבַּיִת יִכָּנֵס. שֶׁכָּךְ שָׁנִינוּ בְּתוֹרַת כֹּהֲנִים (אמור פרק ג יא): יָכוֹל לֹא יִכָּנֵס לַעֲשׂוֹת רִקּוּעוֹת? תַּלְמוּד לוֹמַר "אַךְ" (ויקרא כ"א:כ"ג). כָּךְ הִיא מִצְוָתָן: הַכֹּהֲנִים נִכְנָסִין שָׁם, אִם אֵין שָׁם כֹּהֲנִים - נִכְנָסִין שָׁם לְוִיִּם, אִם אֵין טְהוֹרִים - נִכְנָסִים שָׁם טְמֵאִים, אִם אֵין תְּמִימִים - נִכְנָסִין שָׁם בַּעֲלֵי מוּמִין. וְעַכְשָׁו, הַיּוֹם הַזֶּה אֵין שָׁם כֹּהֲנִים, שֶׁהֲרֵי נִצְטַוּוּ שֶׁלֹּא יִטַּמְּאוּ לָהֶם. אֲבָל כֵּיוָן שֶׁהָיָה אֶפְשָׁר בְּחַכּוֹת וּבִגְרִירָה, לֹא הָיוּ רַשָּׁאִין לִכָּנֵס שָׁם. וְעַל דַּעַת רַבִּי אֱלִיעֶזֶר, מִפְּנֵי שֶׁאָמַר הַכָּתוּב "וַיִּקְרְבוּ", סָבַר שֶׁהָיוּ בַּחוּץ, וְלָכֵן לֹא אָמַר "וַיִּגְרְרוּם בְּכֻתֳּנֹתָם". וְטַעַם "בְּכֻתֳּנֹתָם", כִּי הָיוּ לוֹבְשִׁים בִּגְדֵי כְּהֻנָּה. וְהִנֵּה צִוָּה מֹשֶׁה לְהוֹצִיא אוֹתָם אֶל מִחוּץ לַמַּחֲנֶה, וְשָׁם יַפְשִׁיטוּם בִּגְדֵי הַכְּהֻנָּה וְיַלְבִּישׁוּם תַּכְרִיכֵי הַמֵּתִים וְיִקְבְּרוּ אוֹתָם כְּמִנְהָגָם כִּשְׁאָר הַמֵּתִים בַּמִּדְבָּר. וְהִנֵּה אַחַר כֵּן טִהֲרוּ הַבְּגָדִים הַקְּדוֹשִׁים וְהָיוּ לִשְׁאָר הַכֹּהֲנִים.
@30 **אַל תִּפְרָעוּ** - אַל תְּגַדְּלוּ שֵׂעָר. מִכָּאן שֶׁאָבֵל אָסוּר בְּתִסְפֹּרֶת. אֲבָל אַתֶּם אַל תְּעַרְבְּבוּ שִׂמְחָתוֹ שֶׁל מָקוֹם. "וְלֹא תָמֻתוּ" - הָא אִם תַּעֲשׂוּ תָּמוּתוּ. לְשׁוֹן רַשִׁ"י (רש"י על ויקרא י':ו'). וְזֶה שֶׁאָמַר מִכָּאן שֶׁאָבֵל אָסוּר בְּתִסְפֹּרֶת אַסְמַכְתָּא בְּעָלְמָא הִיא. וְעוֹד כִּי לְפִי זֶה לֹא יִדָּרֵשׁ הָא אִם תַּעֲשׂוּ תָּמוּתוּ, אֲבָל יִהְיֶה רְשׁוּת בִּבְנֵי אַהֲרֹן שֶׁיֹּאמַר: אֵינְכֶם חַיָּבִין לִפְרֹעַ רָאשֵׁיכֶם וְלִקְרֹעַ בִּגְדֵיכֶם כִּשְׁאָר הָאֲבֵלִים, "וְלֹא תָּמֻתוּ" - שֶׁלֹּא תִּהְיוּ חַיָּבִין מִיתָה בְּכָךְ, כִּי שְׁאָר הָאֲבֵלִים חַיָּבִים אִם לֹא עָשׂוּ כֵן. וְכָךְ אָמְרוּ בַּגְּמָרָא בְּמַשְׁקִין (מו"ק כד): אָבֵל שֶׁלֹּא פָּרַע וְשֶׁלֹּא פָּרַם חַיָּב מִיתָה, שֶׁנֶּאֱמַר "רָאשֵׁיכֶם אַל תִּפְרָעוּ וּבִגְדֵיכֶם לֹא תִפְרֹמוּ וְלֹא תָמֻתוּ" - הָא אַחֵר שֶׁלֹּא פָּרַע וְשֶׁלֹּא פָּרַם חַיָּב מִיתָה. וְכָל זֶה כְּדֶרֶךְ הָאַסְמַכְתּוֹת בַּתַּלְמוּד. וְאֵין פְּרִיעָה וּפְרִימָה בָּאֲבֵלוּת אֶלָּא מִדִּבְרֵי סוֹפְרִים, אוֹ שֶׁיִּהְיֶה יוֹם רִאשׁוֹן הֲלָכָה לְמֹשֶׁה מִסִּינַי, נִלְמַד מִן הָאֲנִינוּת כְּפִי דַּעַת הַגְּאוֹנִים. אֲבָל עִקַּר הַכָּתוּב הַזֶּה אַזְהָרָה בִּבְנֵי אַהֲרֹן. וּשְׁמַע פֵּרוּשׁוֹ: כְּבָר אָמְרוּ רַבּוֹתֵינוּ (הוריות יב) שֶׁכֹּהֵן גָּדוֹל מַקְרִיב אוֹנֵן וְאֵינוֹ אוֹכֵל, וְאִם מֵת לוֹ מֵת אָסוּר לִפְרֹעַ וְלִפְרֹם עָלָיו וּלְהִטַּמֵּא לוֹ, שֶׁנֶּאֱמַר (להלן כא י-יא) "אֶת רֹאשׁוֹ לֹא יִפְרָע וּבְגָדָיו לֹא יִפְרֹם וְעַל כָּל נַפְשֹׁת מֵת לֹא יָבֹא". וּבַעֲבוּר שֶׁהוּא רַשַּׁאי לִהְיוֹת מַקְרִיב כְּשֶׁהוּא אוֹנֵן, אָמַר בּוֹ הַכָּתוּב "וּמִן הַמִּקְדָּשׁ לֹא יֵצֵא וְלֹא יְחַלֵּל אֵת מִקְדַּשׁ אֱלֹהָיו" (שם יב). וְהַטַּעַם שֶׁיַּזְהִיר אוֹתוֹ שֶׁלֹּא יֵצֵא מִן הַמִּקְדָּשׁ וְיַנִּיחַ הָעֲבוֹדָה, כִּי זֶה חִלּוּל הַמִּקְדָּשׁ הוּא. וְהִנֵּה זוֹ הָאַזְהָרָה שֶׁלֹּא יֵצֵא מִן הַמִּקְדָּשׁ בִּשְׁעַת הָעֲבוֹדָה נוֹהֶגֶת בְּכָל הַכֹּהֲנִים, אֲבָל לִמֵּד בְּכֹהֵן גָּדוֹל שֶׁמַּקְרִיב אוֹנֵן. וְכֵיוָן שֶׁכֵּן הוּא, אִם הִנִּיחַ הָעֲבוֹדָה וְיָצָא בַּאֲנִינוּת, יִתְחַיֵּב כְּכָל כֹּהֵן שֶׁמַּנִּיחַ עֲבוֹדָה וְיוֹצֵא לִרְצוֹנוֹ. וְהִנֵּה מֹשֶׁה הִזְהִיר כָּאן לְאַהֲרֹן שֶׁלֹּא יִפְרַע וְשֶׁלֹּא יִפְרֹם, כִּי הִיא מִצְוָה נוֹהֶגֶת בּוֹ לְדוֹרוֹת שֶׁהוּא הַכֹּהֵן הַגָּדוֹל. אֲבָל בָּנָיו שֶׁהָיוּ מִשְּׁאָר הַכֹּהֲנִים לֹא הָיוּ רַשָּׁאִין לְהַקְרִיב בַּיּוֹם הַזֶּה כִּי הָיוּ אוֹנְנִין, וְאוֹנֵן שֶׁעָבַד חִלֵּל, וְהָיוּ חַיָּבִים לְהִטַּמֵּא לַאֲחֵיהֶם. וְכֵן הָיוּ רַשָּׁאִין אוֹ חַיָּבִין לִפְרֹעַ וְלִפְרֹם, וּמֹשֶׁה הִזְהִירָם מִכָּל זֶה הוֹרָאַת שָׁעָה. וְלָכֵן צִוָּה אֶל מִישָׁאֵל וְאֶל אֶלְצָפָן שֶׁיִּטַּמְּאוּ לַמֵּתִים הֵם וְלֹא הַכֹּהֲנִים, וְצִוָּה לָהֶם שֶׁלֹּא יִפְרְעוּ וְשֶׁלֹּא יִפְרֹמוּ כַּאֲבִיהֶם, וְלֹא יִבְכּוּ כְּלָל. וְזֶה טַעַם "וַאֲחֵיכֶם כָּל בֵּית יִשְׂרָאֵל יִבְכּוּ אֶת הַשְּׂרֵפָה", וְלֹא אַתֶּם. וְהִנֵּה הַכֹּל שֶׁלֹּא לְעַרְבֵּב שִׂמְחָתוֹ שֶׁל מָקוֹם, וְהֶחְמִיר בָּזֶה לִהְיוֹת לָהֶם חִיּוּב מִיתָה אִם יְעַרְבְּבוּ הַשִּׂמְחָה כְּלָל. וְיִתָּכֵן שֶׁנִּצְטַוָּה מֹשֶׁה בְּכָךְ מִפִּי הַגְּבוּרָה, וְאַף עַל פִּי שֶׁלֹּא נִכְתַּב, אוֹ שֶׁלָּמַד זֶה מִמַּה שֶׁנִּצְטַוָּה (לעיל ח לה) "וּשְׁמַרְתֶּם אֶת מִשְׁמֶרֶת ה' וְלֹא תָמֻתוּ", כִּי "מִשְׁמֶרֶת ה'" יוֹסִיף גַּם הַיּוֹם הַשְּׁמִינִי. וְהִנֵּה גָּלוּי וְיָדוּעַ הָיָה לִפְנֵי מִי שֶׁאָמַר וְהָיָה הָעוֹלָם כִּי עֲתִידִין בְּנֵי אַהֲרֹן לִהְיוֹת אוֹנְנִים, וְאַף עַל פִּי כֵן צִוָּה שֶׁלֹּא יַנִּיחוּ הַמִּקְדָּשׁ. אִם כֵּן לֹא יִטַּמְּאוּ וְלֹא יִתְאַבְּלוּ כְּלָל. וְהִנֵּה בְּנֵי אַהֲרֹן הַכֹּהֲנִים הַמְּשֻׁחִים, אַף עַל פִּי שֶׁהֵם כֹּהֲנִים הֶדְיוֹטִים, עָשָׂה דִּינָם בִּימֵי הַמִּלּוּאִים כְּדִין מְשׁוּחַ מִלְחָמָה לְדוֹרוֹת, שֶׁהוּא אֵינוֹ פּוֹרֵעַ וְאֵינוֹ פּוֹרֵם וְלֹא מִטַּמֵּא לִקְרוֹבִים כְּכֹהֵן גָּדוֹל (הוריות ג ד), אֲבָל אֵינוֹ מַקְרִיב אוֹנֵן. וְגַם הֵם לֹא הִקְרִיבוּ בְּאוֹתוֹ הַיּוֹם כְּמוֹ שֶׁדָּרְשׁוּ (זבחים קא): "הֵן הַיּוֹם הִקְרִיבוּ אֶת חַטָּאתָם" - וְכִי הֵם הִקְרִיבוּ שֶׁהֵם הֶדְיוֹטוֹת? אֲנִי הִקְרַבְתִּי שֶׁאֲנִי כֹּהֵן גָּדוֹל. וְהִנֵּה בְּכָל הַמִּקְרֶה הַזֶּה לֹא נִתְבַּטֵּל דָּבָר בַּמִּלּוּאִים, שֶׁכְּבָר קָרְבוּ הַקָּרְבָּנוֹת, וְלָעֶרֶב אֲכָלוּם כֻּלָּם הָרָאוּי לַאֲכִילָה. וְאֶפְשָׁר שֶׁיִּהְיֶה זֶה כָּל יְמֵיהֶם בְּאֶלְעָזָר וְאִיתָמָר, שֶׁיִּהְיֶה דִּינָם כִּמְשׁוּחַ מִלְחָמָה בַּעֲבוּר שֶׁנִּמְשְׁחוּ בְּשֶׁמֶן הַמִּשְׁחָה. וְיִהְיֶה זֶה טַעַם "כִּי שֶׁמֶן מִשְׁחַת ה' עֲלֵיכֶם". וּכְבָר הִזְכַּרְתִּי (לעיל ח לה) הַבָּרַיְתָא שֶׁל תּוֹרַת כֹּהֲנִים (ריש פרשת שמיני מב) שֶׁאָמְרָה: "וּמִפֶּתַח אֹהֶל מוֹעֵד לֹא תֵצְאוּ" - יָכוֹל בִּשְׁעַת הָעֲבוֹדָה וְשֶׁלֹּא בִּשְׁעַת הָעֲבוֹדָה? תַּלְמוּד לוֹמַר "וּמִן הַמִּקְדָּשׁ לֹא יֵצֵא וְלֹא יְחַלֵּל" (ויקרא כ"א:י"ב). אֵימָתַי לֹא יֵצֵא וְאֵינוֹ מְחַלֵּל? הֱוֵי אוֹמֵר בִּשְׁעַת הָעֲבוֹדָה. "פֶּן תָּמֻתוּ" - מִמַּשְׁמַע לָאו אַתָּה שׁוֹמֵעַ הֵן. "כִּי שֶׁמֶן מִשְׁחַת ה' עֲלֵיכֶם" - מַה תַּלְמוּד לוֹמַר? שֶׁיָּכוֹל אֵין לִי אֶלָּא אַהֲרֹן וּבָנָיו שֶׁנִּמְשְׁחוּ בְּשֶׁמֶן הַמִּשְׁחָה שֶׁאִם יָצְאוּ בִּשְׁעַת הָעֲבוֹדָה חַיָּבִין מִיתָה. מִנַּיִן לְכָל הַכֹּהֲנִים שֶׁבְּכָל הַדּוֹרוֹת? תַּלְמוּד לוֹמַר "כִּי שֶׁמֶן מִשְׁחַת ה' עֲלֵיכֶם". וְכֵן רָאִיתִי עוֹד בַּתּוֹסֶפְתָּא שֶׁל סַנְהֶדְרִין (פ"ד ה"א): אָמְרוּ לוֹ לְר' יְהוּדָה אֵין "מִן הַמִּקְדָּשׁ לֹא יֵצֵא" אֶלָּא בִּשְׁעַת עֲבוֹדָה בִּלְבַד. וְהִנֵּה לְפִי זֶה הָאַזְהָרָה הַזֹּאת וְהָעֹנֶשׁ הָיוּ בְּאַהֲרֹן וּבָנָיו, שֶׁאִם יֵצְאוּ מִפֶּתַח אֹהֶל מוֹעֵד בִּשְׁעַת עֲבוֹדָה יְהוּ חַיָּבִין. וְאַהֲרֹן הָיָה מַקְרִיב בַּיּוֹם הַזֶּה וְהִזְהִירוֹ שֶׁלֹּא יַנִּיחַ הָעֲבוֹדָה וְיֵצֵא. אֲבָל בָּנָיו בַּיּוֹם הַזֶּה אוֹנְנִים הָיוּ וְאֵינָם עוֹבְדִים, וְאֵיךְ יִהְיוּ בִּכְלַל זֶה? וְאוּלַי נֹאמַר שֶׁמֹּשֶׁה אָמַר לְכֻלָּם: וּמִפֶּתַח אֹהֶל מוֹעֵד לֹא תֵצְאוּ בִּשְׁעַת עֲבוֹדָה פֶּן תָּמֻתוּ, וְהֵם הַיּוֹדְעִים כִּי אַהֲרֹן מַקְרִיב אוֹנֵן וְהוּא בְּאַזְהָרָתוֹ מֵעַתָּה, וּבָנָיו בִּכְלַל הָאַזְהָרָה וְהָעֹנֶשׁ כְּשֶׁיִּהְיוּ רְאוּיִים לָעֲבוֹדָה מִיּוֹם זֶה וְאֵילָךְ. וּמִפְּנֵי זֶה אָמַר בְּכָאן סְתָם "וּמִפֶּתַח אֹהֶל מוֹעֵד לֹא תֵצְאוּ" וְלֹא פֵּרַשׁ עַד מָתַי, אִם עַד הָעֶרֶב אוֹ לְמָחֳרָתוֹ, כִּי הַכַּוָּנָה שֶׁלֹּא יַנִּיחוּ הָעֲבוֹדָה, וְהִיא מִצְוָה נוֹהֶגֶת לְדוֹרוֹת. וְיִתָּכֵן שֶׁהָיָה לַבָּנִים הוֹרָאַת שָׁעָה שֶׁלֹּא יֵצְאוּ מִשָּׁם בַּיּוֹם הַזֶּה כַּאֲבִיהֶם לִכְבוֹד הַשִּׂמְחָה, אֲבָל הַכֹּהֲנִים שֶׁבְּכָל הַדּוֹרוֹת מֻזְהָרִים שֶׁלֹּא יַנִּיחוּ עֲבוֹדָה מִן הַכָּתוּב שֶׁאָמַר "וּמִן הַמִּקְדָּשׁ לֹא יֵצֵא וְלֹא יְחַלֵּל", כִּי כָל כֹּהֵן שֶׁיֵּצֵא וְיַנִּיחַ עֲבוֹדָתוֹ מְחַלֵּל. וְלֹא הֻצְרְכוּ לִלְמֹד מִכָּאן אֶלָּא הָעֹנֶשׁ שֶׁנִּתְרַבָּה כָּל מַנִּיחַ עֲבוֹדָה וְיוֹצֵא לְמִיתָה מִ"כִּי שֶׁמֶן מִשְׁחַת ה' עֲלֵיכֶם", שֶׁהַמְּשִׁיחָה לְדוֹרוֹת הִיא עֲלֵיהֶם, כְּמוֹ שֶׁנֶּאֱמַר (שמות מ טו) "וְהָיְתָה לִהְיֹת לָהֶם מָשְׁחָתָם לִכְהֻנַּת עוֹלָם לְדֹרֹתָם". וְכָךְ שָׁנוּ שָׁם בַּבָּרַיְתָא שֶׁל תּוֹרַת כֹּהֲנִים (ריש הפרשה כח): מִכָּאן אָמְרוּ הֲרוּגֵי בֵּית דִּין אֵין מִתְעַסְּקִין עִמָּהֶן לְכָל דָּבָר. שֶׁמָּא תֹּאמְרוּ: הֲרֵי אָנוּ הוֹלְכִים לְבָתֵּינוּ וּמִתְאַבְּלִין, אוֹנְנִין וּבוֹכִין - וַהֲלֹא כְּבָר פְּקָדָנוּ הַמָּקוֹם שֶׁלֹּא תֵּצְאוּ מִן הַמִּקְדָּשׁ. נִרְאֶה מִכָּאן שֶׁהָיְתָה הוֹרָאַת שָׁעָה שֶׁיִּהְיוּ הַמֵּתִים בְּבֵית דִּין שֶׁל מַעְלָה כְּנֶהֱרָגִין בְּבֵית דִּין עַל הָעֲבֵרוֹת, שֶׁבָּאִין וְשׁוֹאֲלִין בִּשְׁלוֹם הַדַּיָּנִין וּבִשְׁלוֹם הָעֵדִים (סנהדרין מו). אַף כָּאן יַעַמְדוּ לִפְנֵי הַשֵּׁם בְּיוֹם חֲתֻנָּתוֹ וּבְיוֹם שִׂמְחַת לִבּוֹ: "בְּיוֹם חֲתֻנָּתוֹ" - זֶה סִינַי, "וּבְיוֹם שִׂמְחַת לִבּוֹ" - זֶה שִׂמְחַת אֹהֶל מוֹעֵד (במדבר רבה יב ח).
@33 **יַיִן וְשֵׁכָר אַל תֵּשְׁתְּ** - יַיִן דֶּרֶךְ שִׁכְרוּתוֹ, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא י':ט'). וּפֵרוּשׁוֹ שֶׁאִם הִפְסִיק בּוֹ אוֹ שֶׁנָּתַן לְתוֹכוֹ מְעַט מַיִם פָּטוּר. וְדַעְתּוֹ שֶׁל הָרַב שֶׁלֹּא הֻזְהֲרוּ אֶלָּא עַל הַיַּיִן, לֹא עַל שְׁאָר הַמְשַׁכְּרִים. וְנִלְמֹד שֵׁכָר מִן הַנָּזִיר (נזיר ד). וְכֵן הַדָּבָר לְפִי דַּעְתִּי. אֲבָל עַל דַּעַת הָרַב ר' מֹשֶׁה (בס' המצות ל"ת ע"ג ובהל' ביאת המקדש פ"א ה"ב) עַל שְׁאָר הַמְשַׁכְּרִים בְּאַזְהָרָה, וְשֵׁכָר כִּפְשׁוּטוֹ. וְהַטַּעַם בַּצַּוָּאָה הַזֹּאת עַתָּה, שֶׁלֹּא יִתְעֶה הַכֹּהֵן בְּשִׁכְרוּת הַיַּיִן וְיָבֹא לִידֵי מַחְשָׁבָה שֶׁאֵינָהּ כַּהֹגֶן וְיָמוּת בָּהּ כַּאֲשֶׁר עָשׂוּ בָּנָיו. וְיִתָּכֵן כִּי מַה שֶׁדָּרְשׁוּ (ויקרא רבה יב א) שֶׁהָיוּ נָדָב וַאֲבִיהוּא שְׁתוּיֵי יַיִן, לוֹמַר כִּי מִפְּנֵי יֵינָם טָעוּ בְּאֵשׁ זָרָה. לֹא שֶׁיִּהְיֶה הָעֹנֶשׁ מִפְּנֵי הַיַּיִן, כִּי עֲדַיִן לֹא הֻזְהֲרוּ מִמֶּנּוּ, אֲבָל עָנְשָׁם שֶׁטָּעוּ בְּאֵשׁ ה' כַּאֲשֶׁר רָמַזְתִּי (רמב"ן על ויקרא י':ב').
@33 **בְּבֹאֲכֶם אֶל אֹהֶל מוֹעֵד** - אֵין לִי אֶלָּא בְּבוֹאָם לַהֵיכָל, בְּגִשְׁתָּם לַמִּזְבֵּחַ מִנַּיִן? נֶאֱמַר כָּאן בִּיאַת אֹהֶל, וְנֶאֱמַר בְּקִדּוּשׁ יָדַיִם וְרַגְלַיִם בִּיאַת אֹהֶל (שמות ל כ). מַה לְהַלָּן עָשָׂה גִּישַׁת מִזְבֵּחַ כְּבִיאַת אֹהֶל, אַף כָּאן עָשָׂה גִּישַׁת מִזְבֵּחַ כְּבִיאַת אֹהֶל. לְשׁוֹן רַשִׁ"י (רש"י על ויקרא י':ט') וְתוֹרַת כֹּהֲנִים (פרשה א ד). וְהַנִּרְאֶה לְפִי הַהֶקֵּשׁ הַזֶּה שֶׁאֵין הַכֹּהֵן חַיָּב מִיתָה בְּגִישַׁת הַמִּזְבֵּחַ וְלֹא בְּבִיאַת הָאֹהֶל, אֶלָּא אִם כֵּן עָבַד שָׁם עֲבוֹדָה, כְּדֶרֶךְ קִדּוּשׁ יָדַיִם שֶׁאֵין הָאַזְהָרָה שָׁם אֶלָּא שֶׁלֹּא יַעֲבֹד, כְּדֶרֶךְ שֶׁנֶּאֱמַר (שמות ל כ) "אוֹ בְגִשְׁתָּם אֶל הַמִּזְבֵּחַ לְשָׁרֵת לְהַקְטִיר אִשֶּׁה לַה'". וּבַלָּשׁוֹן הַזֶּה שָׁנוּי שָׁם בְּסִפְרָא: רַבִּי אוֹמֵר, נֶאֱמַר כָּאן "בְּבֹאֲכֶם אֶל אֹהֶל מוֹעֵד", וְנֶאֱמַר לְהַלָּן (שם) "בְּבֹאָם אֶל אֹהֶל מוֹעֵד", מַה לְהַלָּן עָשָׂה אֶת הַיְּצִיאָה כְּבִיאָה וְאֶת הַמִּזְבֵּחַ כְּאֹהֶל מוֹעֵד, וְאֵינוֹ חַיָּב אֶלָּא בִּשְׁעַת הָעֲבוֹדָה, אַף כָּאן עָשָׂה אֶת הַיְּצִיאָה כְּבִיאָה וְאֶת הַמִּזְבֵּחַ כְּאֹהֶל מוֹעֵד, וְאֵינוֹ חַיָּב אֶלָּא בִּשְׁעַת הָעֲבוֹדָה. כְּלוֹמַר, שֶׁאֵין הַחִיּוּב אֶלָּא שֶׁלֹּא יַעֲבֹד, בֵּין שֶׁנִּכְנַס שִׁכּוֹר אוֹ שֶׁשָּׁתָה שָׁם וְעָבַד. וְשָׁם (א ח) אָמְרוּ: "חֻקַּת עוֹלָם" - לְרַבּוֹת הַיְּצִיקוֹת וְהַבְּלִילוֹת וְהַתְּנוּפוֹת וְהַהַגָּשׁוֹת הַקְּמִיצוֹת וְהַהַקְטָרוֹת הַמְּלִיקוֹת וְהַהַזָּיוֹת. כִּי מִפְּנֵי שֶׁאָמַר הַכָּתוּב "לְהַקְטִיר אִשֶּׁה לַה'" (שמות ל כ), הֻצְרְכוּ אֵלּוּ לְרַבּוֹתָם. וְנִרְאֶה עוֹד שֶׁאֵין הַחִיּוּב הַזֶּה בְּמַקְרִיב בְּבָמָה, וּלְכָךְ אָמְרוּ שָׁם: אֵין לִי אֶלָּא אֹהֶל מוֹעֵד, מִנַּיִן לְרַבּוֹת שִׁילֹה וּבֵית עוֹלָמִים? תַּלְמוּד לוֹמַר "חֻקַּת עוֹלָם". כִּי הָאַזְהָרָה לַכֹּהֲנִים בַּעֲבוֹדָתָם, וְאֵין כֹּהֵן בְּבָמָה. וְהִנֵּה פֵּרוּשׁ "בְּבֹאֲכֶם" - כַּאֲשֶׁר תַּעַבְדוּ עֲבוֹדָה, וְאָמַר בַּלָּשׁוֹן הַזֶּה כִּי כָל הָעֲבוֹדוֹת שָׁם הָיוּ אוֹ בְּתוֹךְ הָאֹהֶל אוֹ בְּמִזְבַּח הָעוֹלָה אֲשֶׁר פֶּתַח אֹהֶל מוֹעֵד. וְהַכְּלָל, כִּי הָאַזְהָרָה וְהָעֹנֶשׁ בְּאֵלּוּ אֵינָם אֶלָּא שֶׁלֹּא יַעֲבֹד שְׁתוּי יַיִן אוֹ שֶׁאֵינוֹ רְחוּץ יָדַיִם וְרַגְלַיִם, וְכֵן מְחֻסָּר בְּגָדִים. אֲבָל עַל הַכְּנִיסָה אֵין בָּהּ בַּתּוֹרָה שׁוּם מְנִיעָה מֵאֵלּוּ. וּמַה שֶׁשָּׁנִינוּ (כלים פ"א מ"ט) רַבִּי יוֹסֵי אוֹמֵר: בַּחֲמִשָּׁה דְּבָרִים בֵּין הָאוּלָם וְלַמִּזְבֵּחַ שָׁוֶה לַהֵיכָל, שֶׁאֵין בַּעֲלֵי מוּמִין וּפְרוּעֵי רֹאשׁ וְשֶׁלֹּא רְחוּץ יָדַיִם וְרַגְלַיִם נִכְנָסִין לְשָׁם וְכֻלָּהּ מַתְנִיתִין מַעֲלוֹת דְּרַבָּנָן הֵם. וְעַל דַּעַת הָרַב ר' מֹשֶׁה (הל' ביאת המקדש פ"א הט"ו הט"ז) יֵשׁ בִּכְנִיסָה בְּלֹא עֲבוֹדָה לָאו שֶׁאֵין בּוֹ מִיתָה.
@39 **שׁוֹק הַתְּרוּמָה וַחֲזֵה הַתְּנוּפָה** - לְשׁוֹן "אֲשֶׁר הוּנַף וַאֲשֶׁר הוּרָם" (שמות כט כז). תְּנוּפָה - מוֹלִיךְ וּמֵבִיא, תְּרוּמָה - מַעֲלֶה וּמוֹרִיד. וְלָמָּה חִלְּקָן הַכָּתוּב, תְּרוּמָה בַּשּׁוֹק וּתְנוּפָה בֶּחָזֶה לֹא יָדַעְנוּ, שֶׁשְּׁנֵיהֶם בַּהֲרָמָה וַהֲנָפָה. לְשׁוֹן רַשִׁ"י (רש"י על ויקרא י':ט"ו). וְהַנִּרְאֶה אֵלַי בְּטַעַם זֶה, כִּי בַּמִּלּוּאִים הָיָה הַשּׁוֹק תְּרוּמָה לַה', וְהֻקְטַר עִם הַלֶּחֶם וְעִם הַחֲלָבִים. וְהַמּוּרָם מִן הַשְּׁלָמִים יִקָּרֵא תְּרוּמָה, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא ז':י"ד): "וְהִקְרִיב מִמֶּנּוּ אֶחָד מִכָּל קָרְבָּן תְּרוּמָה לַה'". וְכָל שֶׁכֵּן אֵלּוּ שֶׁהֶעֱלוּ אוֹתָם לַגָּבוֹהַּ, שֶׁהֵם כֻּלָּם תְּרוּמָה לַה'. וְלֹא יִקָּרֵא בְּשֵׁם תְּנוּפָה, כִּי תְּנוּפָתוֹ הָיְתָה עִם הַחֲלָבִים וְהַלֶּחֶם כְּדֵי לְהַקְטִירָם לַה'. אֲבָל הֶחָזֶה הוּנַף בִּפְנֵי עַצְמוֹ, וְלֹא הָיָה חָלוּק מִשְּׁאָר הַבָּשָׂר אֶלָּא בַּתְּנוּפָה, וּבִתְנוּפָה זוֹ בִּלְבַד נִתְקַדֵּשׁ וְזָכָה בּוֹ מֹשֶׁה לִהְיוֹת לוֹ לְמָנָה. וּמִפְּנֵי שֶׁזְּכוּת אַהֲרֹן וּבָנָיו בֶּחָזֵה וָשׁוֹק לְדוֹרוֹת הָיָה מִיּוֹם הַמִּלּוּאִים, וְזָכוּ בַּשּׁוֹק בִּתְרוּמָתוֹ לַה' וּבֶחָזֶה בִּתְנוּפָתוֹ, וּשְׁאָר הַבָּשָׂר לַבְּעָלִים, יִקָּרֵא לְעוֹלָם הַשּׁוֹק תְּרוּמָה וְהֶחָזֶה תְּנוּפָה, כַּאֲשֶׁר הָיָה בָּהֶם בְּיוֹם הַזְּכוּת.
@39 **עַל אִשֵּׁי הַחֲלָבִים** - כְּמוֹ "עַל חֶלְבֵי הָאִשִּׁים". מִכָּאן שֶׁהַחֲלָבִים לְמַטָּה בִּשְׁעַת תְּנוּפָה. לְשׁוֹן רַשִׁ"י (רש"י על ויקרא י':ט"ו). וְאֵין צֹרֶךְ, כִּי "אִשֵּׁי" תֹּאַר לַחֲלָבִים, כְּמוֹ שֶׁאָמַר (דברים יח א) "אִשֵּׁי ה' וְנַחֲלָתוֹ יֹאכֵלוּן". וּפֵרוּשׁ הַכָּתוּב הַזֶּה שֶׁהוּא טַעַם לְמָה שֶׁאָמַר (ויקרא י':י"ד) "כִּי חָקְךָ וְחָק בָּנֶיךָ נִתְּנוּ מִזִּבְחֵי שַׁלְמֵי בְּנֵי יִשְׂרָאֵל", וְאָמַר: שׁוֹק הַתְּרוּמָה וַחֲזֵה הַתְּנוּפָה עַל אִשֵּׁי הַחֲלָבִים יָבִיאוּ אוֹתָם בְּנֵי יִשְׂרָאֵל הַנִּזְכָּרִים לְהָנִיף תְּנוּפָה לִפְנֵי ה', שֶׁיִּהְיוּ קְדוֹשִׁים לְפָנָיו, וְיִהְיוּ לְךָ וּלְבָנֶיךָ לְחָק עוֹלָם. כִּי הַצַּוָּאָה בַּתְּנוּפָה אֵין זֶה מְקוֹמָהּ, אֲבָל לְפִי דַּרְכֵּנוּ לָמַדְנוּ בָּהּ שֶׁהַחֲלָבִים לְמַטָּה בִּשְׁעַת תְּנוּפָה.
@40 **שְׂעִיר הַחַטָּאת** - שְׂעִיר מוּסְפֵי רֹאשׁ חֹדֶשׁ, וּשְׁלֹשָׁה שְׂעִירִים קָרְבוּ בּוֹ בַּיּוֹם: "קְחוּ שְׂעִיר עִזִּים לְחַטָּאת" (ויקרא ט':ג'), וּשְׂעִיר נַחְשׁוֹן (במדבר ז' טז), וּשְׂעִיר רֹאשׁ חֹדֶשׁ (שם כח טו). וּמִכֻּלָּם לֹא נִשְׂרַף אֶלָּא זֶה. וְנֶחְלְקוּ בַּדָּבָר חַכְמֵי יִשְׂרָאֵל: יֵשׁ אוֹמְרִים מִפְּנֵי טֻמְאָה שֶׁנָּגְעָה בּוֹ נִשְׂרַף, וְיֵשׁ אוֹמְרִים מִפְּנֵי אֲנִינוּת נִשְׂרַף. לְשׁוֹן רַשִׁ"י (רש"י על ויקרא י':ט"ז). וְעַל דַּעַת הָאוֹמֵר מִפְּנֵי טֻמְאָה נִשְׂרַף, כָּתַב הָרַב בַּפָּסוּק "וְאָכַלְתִּי חַטָּאת הַיּוֹם" (ויקרא י':י"ט): הַיּוֹם אָסוּר, אֲבָל אֲנִינוּת לַיְלָה מֻתָּר, שֶׁאֵין אוֹנֵן אֶלָּא יוֹם קְבוּרָה. כִּי לְפִי זֶה, אִם מִפְּנֵי אֲנִינוּת הָיָה לָהֶם לְאָכְלוֹ בָּעֶרֶב, אֶלָּא קָסָבַר אֲנִינוּת לַיְלָה דְּאוֹרַיְתָא.
@43 **הֵן הַיּוֹם הִקְרִיבוּ** - מַהוּ אוֹמֵר? אֶלָּא אָמַר לָהֶם מֹשֶׁה: שֶׁמָּא זְרַקְתֶּם דָּמָהּ אוֹנְנִים, שֶׁהָאוֹנֵן שֶׁעָבַד חִלֵּל? אָמַר לוֹ אַהֲרֹן: וְכִי הֵם הִקְרִיבוּ שֶׁהֵם הֶדְיוֹטוֹת? אֲנִי הִקְרַבְתִּי שֶׁאֲנִי כֹּהֵן גָּדוֹל וּמַקְרִיב אוֹנֵן. לְשׁוֹן רַשִׁ"י (רש"י על ויקרא י':י"ט). וְכָךְ הוּא בַּגְּמָרָא בְּפֶרֶק טְבוּל יוֹם (זבחים קא): "וְדִלְמָא אַקְרֵבְתֵּהּ וּפְסַלְתֵּהּ?" וַאֲנִי תָּמֵהַּ, שֶׁהֲרֵי קֹדֶם הָאֲנִינוּת נַעֲשׂוּ כָּל הַקָּרְבָּנוֹת, דִּכְתִיב: "וַיֵּרֶד מֵעֲשֹׂת הַחַטָּאת וְהָעֹלָה וְהַשְּׁלָמִים" (ויקרא ט':כ"ב), וְאַחַר כֵּן נִכְנְסוּ לְאֹהֶל מוֹעֵד וְהִתְפַּלְּלוּ, וְאַחַר כָּךְ יָרְדָה הָאֵשׁ לַקָּרְבָּנוֹת, וְאָז הִקְטִירוּ נָדָב וַאֲבִיהוּא קְטֹרֶת זוֹ. וְשֶׁמָּא לֹא הָיָה מֹשֶׁה רוֹאֶה אֶת מַעֲשֵׂיהֶם, וְחָשַׁשׁ שֶׁמָּא מָצְאוּ דַּם הַשָּׂעִיר הַזֶּה שֶׁלֹּא נִזְרַק עֲדַיִן וּזְרָקוּהוּ. וְאַהֲרֹן אָמַר לוֹ: הֲלֹא הַזְּרִיקָה שֶׁלִּי הִיא, וּכְשֶׁנִּזְרְקָה מִיָּדִי נִזְרְקָה וְלֹא נִפְסְלָה בַּאֲנִינוּת. וּמַשָּׂא וּמַתָּן שֶׁל הֲלָכָה הָיָה, אֲבָל לֹא נַעֲשָׂה בָּהֶן דָּבָר בַּאֲנִינוּת כְּלָל.
@45 **אֶל מֹשֶׁה וְאֶל אַהֲרֹן וְגוֹ' דַּבְּרוּ אֶל בְּנֵי יִשְׂרָאֵל** - הַמִּצְוֹת בַּפָּרָשִׁיּוֹת הָאֵלֶּה (יא א-מז) נוֹהֲגוֹת בְּיִשְׂרָאֵל וּבַכֹּהֲנִים, אֲבָל עִנְיָנָם מְרֻבֶּה בַּכֹּהֲנִים. כִּי הֵם צְרִיכִים לְהִשְׁתַּמֵּר תָּמִיד מִנְּגִיעַת הַטֻּמְאָה בַּעֲבוּר שֶׁיִּצְטָרְכוּ לָבֹא בַּמִּקְדָּשׁ וְלֶאֱכֹל הַקֳּדָשִׁים. וְעוֹד, כִּי אִם שָׁגְגוּ יִשְׂרָאֵל בָּהֶם חַיָּבִין לְהָבִיא עֲלֵיהֶם קָרְבָּן שֶׁיַּקְרִיבוּהוּ הַכֹּהֲנִים. וְעוֹד שֶׁצִּוָּה אוֹתָם "וּלְהַבְדִּיל בֵּין הַקֹּדֶשׁ וּבֵין הַחֹל וּבֵין הַטָּמֵא וּבֵין הַטָּהוֹר" (ויקרא י':י'). וְהִנֵּה הֵם צְרִיכִים לְהוֹרוֹת לְיִשְׂרָאֵל הַטָּמֵא וְהַטָּהוֹר שֶׁיִּזָּהֲרוּ בָּהֶם. עַל כֵּן הָיָה הַדִּבּוּר הַזֶּה אֶל מֹשֶׁה וְאֶל אַהֲרֹן שְׁנֵיהֶם, אוֹ לְמֹשֶׁה שֶׁיֹּאמַר לְאַהֲרֹן, וְצִוָּה לִשְׁנֵיהֶם "דַּבְּרוּ אֶל בְּנֵי יִשְׂרָאֵל". וּלְכָךְ נֶאֶמְרוּ בְּסֵפֶר תּוֹרַת כֹּהֲנִים. וְיַזְהִיר בַּפָּרָשָׁה בַּאֲכִילָה וּבְטֻמְאָה שֶׁלֹּא יְטַמְּאוּ הַמִּשְׁכָּן וְקָדָשָׁיו.
@46 **מִכָּל הַבְּהֵמָה אֲשֶׁר עַל הָאָרֶץ** - פְּשׁוּטוֹ: מִכָּל הַבְּהֵמָה אֲשֶׁר עַל פְּנֵי כָל הָאָרֶץ, כְּטַעַם מִכָּל אֲשֶׁר בָּעוֹלָם. וּמִדְרָשׁוֹ (תו"כ פרשה ב ו): מִפְּנֵי שֶׁיֵּשׁ חַיּוֹת בַּיָּם וְאֵין תּוֹרָתָן בַּסִּימָנִין הַלָּלוּ אֶלָּא כַּדָּגִים, לְפִיכָךְ אָמַר "אֲשֶׁר עַל הָאָרֶץ" לְהוֹצִיא מַה שֶׁבַּיָּם.
@47 **כֹּל מַפְרֶסֶת פַּרְסָה וְשֹׁסַעַת שֶׁסַע פְּרָסֹת מַעֲלַת גֵּרָה** - טַעַם הַכָּתוּב הַזֶּה שֶׁכָּל בְּהֵמָה שֶׁיִּהְיוּ בָּהּ שְׁנֵי הַסִּימָנִין הַלָּלוּ תֹּאכְלוּ, אֲבָל לֹא תֹּאכְלוּ בְּאֶחָד מֵהֶם. וְהָיָה רָאוּי שֶׁיֹּאמַר כֵּן בְּדֶרֶךְ כְּלָל, אֶלָּא שֶׁפֵּרַט הַגָּמָל וְהַשָּׁפָן וְהָאַרְנֶבֶת בַּגֵּרָה וְהַחֲזִיר בַּפַּרְסָה, מִפְּנֵי שֶׁאֵין אֲחֵרִים בָּעוֹלָם בַּסִּימָן הָאֶחָד לְבַדּוֹ. וְחָזַר וְאָמַר (ויקרא י"א:ח') "מִבְּשָׂרָם לֹא תֹאכֵלוּ" לְלָאו. וְכָתַב רַשִׁ"י: אֵין לִי אֶלָּא אֵלּוּ, שְׁאָר בְּהֵמָה טְמֵאָה שֶׁאֵין לָהּ שׁוּם סִימָן טָהֳרָה מִנַּיִן? אָמַרְתָּ קַל וָחֹמֶר: מַה אֵלּוּ שֶׁיֵּשׁ בָּהֶם קְצָת סִימָנֵי טָהֳרָה אֲסוּרוֹת וְכוּ'. וּלְשׁוֹן סִפְרָא (פרק ג ב): מַה אֵלּוּ שֶׁיֵּשׁ בָּהֶם סִימָנֵי טָהֳרָה הֲרֵי הֵם בְּלֹא תַּעֲשֶׂה עַל אֲכִילָתָם, שְׁאָר בְּהֵמָה טְמֵאָה שֶׁאֵין בָּהּ סִימָן טָהֳרָה אֵינוֹ דִין שֶׁתְּהֵא בְּלֹא תַּעֲשֶׂה עַל אֲכִילָתָהּ? נִמְצְאוּ הַגָּמָל וְהַשָּׁפָן וְהָאַרְנֶבֶת וְהַחֲזִיר מִן הַכָּתוּב, וּשְׁאָר בְּהֵמָה טְמֵאָה מִקַּל וָחֹמֶר. נִמְצֵאת מִצְוַת עֲשֵׂה שֶׁלָּהֶן מִן הַכָּתוּב, מִצְוַת לֹא תַּעֲשֶׂה מִקַּל וָחֹמֶר. עַד כָּאן הַבָּרַיְתָא. אֲבָל לְפִי דַּעְתִּי אֵינָהּ עוֹלָה כַּהֹגֶן לְפִי סוּגְיוֹת הַתַּלְמוּד, שֶׁאִם כֵּן לֹא יְהֵא לוֹקֶה עַל שְׁאָר בְּהֵמָה טְמֵאָה שֶׁאֵינָהּ בָּאָה אֶלָּא מִדִּין קַל וָחֹמֶר, שֶׁאֵין מַזְהִירִין מִן הַדִּין. וְכָךְ אָמְרוּ בַּאֲחוֹתוֹ שֶׁאָסַר הַכָּתוּב אֲחֹתוֹ בַּת אָבִיו אוֹ בַת אִמּוֹ (ויקרא כ':י"ז), וְהֻצְרַךְ לְרַבּוֹת בַּכָּתוּב אֲחוֹתוֹ שֶׁהִיא בַּת אָבִיו וּבַת אִמּוֹ, אַף עַל פִּי שֶׁבָּאָה בְּקַל וָחֹמֶר וְיֵשׁ בָּהּ שֵׁם שְׁתֵּיהֶן, לוֹמַר שֶׁאֵין מַזְהִירִין מִן הַדִּין, כִּדְאִיתָא בִּיבָמוֹת בְּפֶרֶק כֵּיצַד (כב). אֲבָל הַבָּרַיְתָא הַזּוֹ אוֹ שֶׁהִיא שְׁנוּיָה כְּדִבְרֵי הָאוֹמֵר עוֹנְשִׁין מִן הַדִּין בְּמַסֶּכֶת סַנְהֶדְרִין (סנהדרין נ"ד), אוֹ שֶׁאֵינָהּ מְתָרַצְתָּא. וְהַטַּעַם בְּמַלְקוּת שְׁאָר בְּהֵמָה טְמֵאָה מִפְּנֵי שֶׁאָמַר הַכָּתוּב בְּאִסּוּר הַשָּׁפָן מִפְּנֵי שֶׁאֵין מַפְרִיס פַּרְסָה, וּבַחֲזִיר מִפְּנֵי שֶׁאֵינוֹ מַעֲלֶה גֵּרָה. אִם כֵּן, כָּל שֶׁאֵינוֹ מַעֲלֶה גֵּרָה וּמַפְרִיס פַּרְסָה הוּא בְּשֵׁם הָאִסּוּר הַזֶּה, אֵין צֹרֶךְ לְקַל וָחֹמֶר כְּלָל.
@47 **אוֹתָהּ תֹּאכֵלוּ** - וְלֹא בְּהֵמָה טְמֵאָה. וַהֲלֹא בְּאַזְהָרָה הִיא? אֶלָּא לַעֲבֹר עָלֶיהָ בַּעֲשֵׂה וְלֹא תַעֲשֶׂה. לְשׁוֹן רַשִׁ"י (רש"י על ויקרא י"א:ג'). וְכָךְ הִיא בְּתוֹרַת כֹּהֲנִים (פרק ג א). וְהָרַב רַבִּי מֹשֶׁה אָמַר (הלכות מאכלות אסורות פרק ב' הלכה ג') שֶׁהוּא לְמַעֵט בְּשַׂר הָאָדָם: "אוֹתָהּ תֹּאכֵלוּ" וְלֹא אָדָם, וּבְשָׂרוֹ וַחֲלָבוֹ בַּעֲשֵׂה. וְלֹא מָצִינוּ שֶׁיִּדָּרֵשׁ כֵּן לְרַבּוֹתֵינוּ. וְשֶׁמָּא חָשַׁב זֶה מִמַּה שֶׁשָּׁנִינוּ שָׁם בְּת"כ (פרק ד ד): יָכוֹל אַף בְּשַׂר מְהַלְּכֵי שְׁתַּיִם וַחֲלֵב מְהַלְּכֵי שְׁתַּיִם יִהְיוּ בְּלֹא תַּעֲשֶׂה עַל אֲכִילָתָן? תַּלְמוּד לוֹמַר "זֶה לֹא תֹאכְלוּ" - זֶה בְּלֹא תַּעֲשֶׂה עַל אֲכִילָתוֹ, וְאֵין בְּשַׂר מְהַלְּכֵי שְׁתַּיִם וַחֲלֵב מְהַלְּכֵי שְׁתַּיִם בְּלֹא תַּעֲשֶׂה עַל אֲכִילָתָן. וְיָדוּן הָרַב מִזֶּה שֶׁאֵינוֹ בְּלֹא תַּעֲשֶׂה אֲבָל הוּא בַּעֲשֵׂה, וּדְרָשׁוֹ מִן הַכָּתוּב "אוֹתָהּ תֹּאכֵלוּ". וְאֵין הַדָּבָר כֵּן, שֶׁבְּפֵרוּשׁ אָמְרוּ חֲכָמִים (כריתות כא) בְּדַם מְהַלְּכֵי שְׁתַּיִם וַחֲלֵב מְהַלְּכֵי שְׁתַּיִם שֶׁאֲפִלּוּ מִצְוַת פְּרֹשׁ מִדִּבְרֵיהֶם אֵין בּוֹ. וְאִם הָיָה בְּשָׂרוֹ אָסוּר, כָּל הַיּוֹצֵא מִן הַטָּמֵא טָמֵא (בכורות ה). וְדַם הַשֶּׁרֶץ וְדַם הָאָדָם מִעֲטוּ אוֹתָן חֲכָמִים מֵאִסּוּר דָּם, וְאָמְרוּ (שם): דַּם הַשֶּׁרֶץ כִּבְשָׂרוֹ, וְלוֹקֶה עָלָיו מִשּׁוּם שֶׁרֶץ שֶׁאֵין בּוֹ מִשּׁוּם דָּם, וַעֲשָׂאוּהוּ כַּבָּשָׂר. אֲבָל מָה שֶׁאָמְרוּ שֶׁאֵינָן בְּלֹא תַּעֲשֶׂה עַל אֲכִילָתָן, לוֹמַר שֶׁלֹּא נִמְנְעוּ מִמֶּנּוּ וְהֵן מֻתָּרִין. אֲבָל לְפִי דַּעְתִּי יִהְיֶה זֶה בְּבָשָׂר מִן הַחַי, אֲבָל הַמֵּת לָמְדוּ בּוֹ (עבודה זרה כט) מִגְּזֵרָה שָׁוָה מֵעֶגְלָה עֲרוּפָה שֶׁאָסוּר בַּהֲנָאָה.
@50 **וְאֶת הָאַרְנֶבֶת** - מִין הוּא שֶׁיִּקְרְאוּ כֵן בִּלְשׁוֹן הַקֹּדֶשׁ הַזָּכָר וְהַנְּקֵבָה מִמֶּנּוּ, וְכֵן הַיַּעֲנָה. וּבָעוֹפוֹת הַיּוֹנָה, אֵין שֵׁם הַזָּכָר חָלוּק מִן הַנְּקֵבָה. וְיֵשׁ רַבִּים שֶׁשְּׁמוֹתָם בִּלְשׁוֹן זָכָר וְאֵין לִנְקֵבוֹתֵיהֶם שֵׁם אַחֵר: גָּמָל, שָׁפָן, חֲזִיר, "דֹּב אֹרֵב" (איכה ג' י'), "פָּרָה וָדֹב תִּרְעֶינָה" (ישעיהו י"א ז'). וְכֵן תּוֹר בָּעוֹפוֹת, וּלְכָךְ אָמַר הַכָּתוּב (ויקרא ה':ז') "שְׁתֵּי תֹרִים אוֹ שְׁנֵי בְנֵי יוֹנָה", יַזְכִּיר בַּתּוֹרִים שֶׁהֵן בִּלְשׁוֹן זָכָר שְׁתֵּי, וּבַיּוֹנָה שְׁנֵי, לְהוֹדִיעַ שֶׁאֵין קְפֵידָא בָּהֶם. וְאַל תָּשִׁיב עָלַי מִלְּשׁוֹן רַבּוֹתֵינוּ שֶׁיֹּאמְרוּ (בכורות כח) פָּרָה וַחֲזִירָה, וְיֹאמְרוּ (שם ו') גָּמָל הַבָּא מִן הַגְּמַלָּה, כִּי יַשְׁאִילוּ בָּהֶם לָשׁוֹן לְבָאֵר כַּוָּנָתָם. וְטַעַם הָאִסּוּר בְּאֵלּוּ, שֶׁאֵינָן בַּעֲלֵי שְׁנֵי הַסִּימָנִים:
@52 **וּבְנִבְלָתָם לֹא תִגָּעוּ** - אֵינָהּ אַזְהָרָה לֶאֱסֹר לָנוּ הַנְּגִיעָה, אֲבָל יֹאמַר וּבְנִבְלָתָם לֹא תִגָּעוּ כִּי טְמֵאִים הֵם לָכֶם, כְּלוֹמַר לֹא תִגְּעוּ בָּהֶם בִּלְתִּי אִם תִּטַּמְּאוּ. וְהָעִנְיָן לוֹמַר שֶׁיַּחְשֹׁב כָּל נוֹגֵעַ בָּהֶם שֶׁהוּא טָמֵא וְיִזָּהֵר מִן הַמִּקְדָּשׁ וּמִן הַקֳּדָשִׁים. וְשֶׁמָּא הַמִּדְרָשׁ שֶׁאָמְרוּ רַבּוֹתֵינוּ (תורת כהנים פרק ד ט): "וּבְנִבְלָתָם לֹא תִגָּעוּ" בָּרֶגֶל, כְּלוֹמַר שֶׁלֹּא תִגְּעוּ בּוֹ בְּשָׁעָה שֶׁאַתֶּם חֲפֵצִים לִהְיוֹת טְהוֹרִים, כִּי טְמֵאִים הֵם וְלֹא תַּעֲלוּ בָּהֶם לָרֶגֶל. אֲבָל אֵין הַנְּגִיעָה נִמְנַעַת בְּלָאו, שֶׁאֵין הַנּוֹגֵעַ בִּנְבֵלָה בָּרֶגֶל מִן הַלּוֹקִין אֶת הָאַרְבָּעִים. וּמַה שֶׁאָמְרוּ (ר"ה טז): "חַיָּב אָדָם לְטַהֵר עַצְמוֹ בָּרֶגֶל" - מִצְוָה מִדִּבְרֵי סוֹפְרִים, וְאֵין בָּזֶה מִן הַתּוֹרָה עֲשֵׂה אוֹ לֹא תַעֲשֶׂה, זוּלָתִי מִצְוַת הָעֲלִיָּה. אוֹ שֶׁיְּהֵא "וּבְנִבְלָתָם לֹא תִגָּעוּ" בָּרֶגֶל - אַסְמַכְתָּא, כִּשְׁאָר אַסְמַכְתּוֹת הַרְבֵּה שֶׁשְּׁנוּיוֹת שָׁם בְּת"כ. וְעוֹד שָׁנוּי שָׁם (פרק ד י): אֲחֵרִים אוֹמְרִים: יָכוֹל אִם נָגַע אָדָם בִּנְבֵלָה יִלְקֶה אַרְבָּעִים? תַּלְמוּד לוֹמַר: "וּלְאֵלֶּה תִטַּמָּאוּ" (ויקרא י"א:כ"ד). יָכוֹל אִם רָאָה אָדָם אֶת הַנְּבֵלָה יֵלֵךְ וְיִטַּמֵּא? תַּלְמוּד לוֹמַר: "וּבְנִבְלָתָם לֹא תִגָּעוּ". הָא כֵיצַד? הֱוֵי אוֹמֵר: רְשׁוּת. וְזֶה עִקַּר הַדִּין מִן הַתּוֹרָה.
@53 **סְנַפִּיר וְקַשְׂקֶשֶׂת** - סְנַפִּירִים אֵלּוּ הַשָּׁט בָּהֶם, קַשְׂקֶשֶׂת אֵלּוּ הַקְּבוּעִים בּוֹ. לְשׁוֹן רַשִׁ"י (רש"י על ויקרא י"א:ט'), וְכֵן הוּא בַּגְּמָרָא בְּמַסֶּכֶת חֻלִּין (חולין נ"ט). אֲבָל לֹא תָּבִין מִלְּשׁוֹנָם שֶׁהֵן קְבוּעִים בְּגוּפָן מַמָּשׁ וּדְבוּקִים בְּעוֹר הַדָּג, אֲבָל קְרָאוּם "קְבוּעִים" שֶׁאֵינָן נָדִין מִמֶּנּוּ וְלֹא מִזְדַּעְזְעִין בּוֹ כַּסְּנַפִּיר, וְהֵם הַקְּלִפִּין הָעֲגֻלִּים שֶׁגִּלְדָּן דּוֹמֶה לְצִפֹּרֶן, שֶׁהֵם נִפְשָׁטִין מֵעוֹר הַדָּג בְּיָד אוֹ בְּסַכִּין. אֲבָל כָּל שֶׁהוּא קָבוּעַ וְדָבוּק בְּעוֹר הַדָּג וְאֵינוֹ נִפְרָד מִן הָעוֹר כְּלָל, אֵינוֹ קַשְׂקֶשֶׂת וּבְעָלָיו אָסוּר הוּא. וּלְכָךְ אָמְרוּ בַּגְּמָרָא (שם סו): קַשְׂקֶשֶׂת לְבוּשָׁא הוּא. וּלְשׁוֹן תּוֹסֶפְתָּא (חולין פ"ג ה"ט): אֵלּוּ הֵן הַקַּשְׂקַשִּׂים שֶׁמְּלֻבָּשׁ בָּהֶן, וּסְנַפִּירִים שֶׁשָּׁט בָּהֶן. וְזֶהוּ תַּרְגּוּמוֹ שֶׁל אוּנְקְלוֹס (תרגום אונקלוס על ויקרא י"א:ט') שֶׁאָמַר "קִלְפִין", שֶׁהֵן קְלִפִּין שֶׁעַל הָעוֹר נִפְשָׁטִין וְנִקְלָפִין מִמֶּנּוּ כִּקְלִפֵּי הָאִילָנוֹת וְהַפֵּרוֹת, מִן עִנְיַן הַכָּתוּב שֶׁאָמַר (שמואל א יז ה): "וְשִׁרְיוֹן קַשְׂקַשִּׂים הוּא לָבוּשׁ", שֶׁהַשִּׁרְיוֹנוֹת כֻּלָּן עֲשׂוּיִים מִן הַטַּבָּעוֹת, וְיֵשׁ שֶׁעוֹשִׂים בָּהֶם קְלִפּוֹת לִסְתֹּם פִּיּוֹת הַטַּבָּעוֹת שֶׁלֹּא יִכָּנֵס בָּהֶן חֵץ דַּק, וְהַקְּלִפִּין הָהֵם נִקְרְאוּ קַשְׂקַשִּׂים. וּלְכָךְ הִזְכִּירוּ חֲכָמִים בַּגְּמָרָא בְּפֶרֶק חֵלֶק (סנהדרין צה): לְבוּשֵׁי שִׁרְיוֹן קְלִפָּה. וְיוֹנָתָן בֶּן עֻזִּיאֵל תִּרְגֵּם: "וְשִׁרְיוֹן גַּלְבִּין", מִלְּשׁוֹן "תַּעַר הַגַּלָּבִים" (יחזקאל ה א), הֵם הָרַצְעָנִין. יִתְכַּוֵּן לוֹמַר כִּי הָיָה כִּסּוּי פִּי טַבַּעַת הַשִּׁרְיוֹן הַהוּא כִּקְלִפֵּי עוֹר הַדָּג, שֶׁמְּבַשְּׁלִין הָעוֹר הֶחָזָק וּמְכַסִּים הַשִּׁרְיוֹנוֹת בָּהֶן, כִּי כֵן עוֹשִׂים גַּם הַיּוֹם. וְהָבֵן זֶה. וְטַעַם הַסְּנַפִּיר וְהַקַּשְׂקֶשֶׂת, כִּי בַּעֲלֵיהֶן שׁוֹכְנִים לְעוֹלָם בְּעֶלְיוֹן הַמַּיִם וּבִצְלוּלֵיהֶן, וִיקַבְּלוּ גִּדּוּל בַּאֲוִיר הַנִּכְנָס שָׁם. וְלָכֵן יֵשׁ בָּהֶם קְצָת חֹם דּוֹחֶה מֵהֶם שִׁפְעַת הַלֵּחוֹת, כַּאֲשֶׁר יַעֲשֶׂה הַצֶּמֶר וְהַשֵּׂעָר וְגַם הַצִּפָּרְנַיִם בָּאָדָם וּבַבְּהֵמָה. וְשֶׁאֵין לוֹ סְנַפִּיר וְקַשְׂקֶשֶׂת יִשְׁכֹּן לְעוֹלָם בְּתַחְתִּיּוֹת הַמַּיִם וּבַעֲכוּרֵיהֶם, וּלְרֹב הַלַּחוּת וַאֲפִיסַת הַחֹם לֹא יִדְחֶה מֵהֶם דָּבָר. וְעַל כֵּן הֵם בַּעֲלֵי לֵחָה קָרָה דְּבֵקָה קְרוֹבָה לְהָמִית, וְהִיא מְמִיתָה בִּקְצָת הַמֵּימוֹת כָּאֲגַמִּים הַמְעֻפָּשִׁים.
@54 **מִכֹּל שֶׁרֶץ הַמַּיִם** - אָמַר ר"א (אבן עזרא על ויקרא י"א:י') כִּי "שֶׁרֶץ" הַקְּטַנִּים שֶׁיִּבָּרְאוּ מִן הַמַּיִם, וְ"נֶפֶשׁ הַחַיָּה" מִזָּכָר וּנְקֵבָה. וּלְפִי דַּעְתִּי כִּי שֶׁרֶץ הַמַּיִם כְּלָל לַדָּגִים הַשָּׁטִים בַּמַּיִם, כִּי כָל לְשׁוֹן שְׁרִיצָה תְּנוּעָה. "וּמִכֹּל נֶפֶשׁ הַחַיָּה" הֵם חַיּוֹת שֶׁבַּיָּם שֶׁיֵּשׁ בָּהֶם רַגְלַיִם וְהוֹלְכוֹת עֲלֵיהֶם כְּחַיּוֹת הַשָּׂדֶה. וְהִנֵּה לְכֻלָּם דִּין אֶחָד. וּמִדְרַשׁ ת"כ (פרשה ג ז): "חַיָּה" - זוֹ חַיַּת הַיָּם, "נֶפֶשׁ" - לְהָבִיא בֶּן הַסִּירָנִי. יָכוֹל יְהֵא מְטַמֵּא בְּאֹהֶל כְּדִבְרֵי בֶּן חֲכִינַאי? תַּלְמוּד לוֹמַר "שֶׁקֶץ".
@55 **וְאֶת נִבְלָתָם תְּשַׁקֵּצוּ** - לְרַבּוֹת יַבְחוּשִׁין שֶׁסִּנְּנָן. יַבְחוּשִׁין שֶׁקּוֹרִין מושלונ"ש בְּלַעַ"ז. לְשׁוֹן רַשִׁ"י (רש"י על ויקרא י"א:י"א). וַאֲנִי תָּמֵהַּ בּוֹ, שֶׁהַמִּין הַהוּא פּוֹרֵשׁ מִן הַיַּיִן תָּמִיד וּפוֹרֵחַ בָּאֲוִיר וְנָח עַל הָאָרֶץ, וַאֲפִלּוּ מִשְּׁעַת פְּרִיחָתוֹ נֶאֱסַר, כִּדְאָמְרִינַן בְּפֶרֶק אֵלּוּ טְרֵפוֹת (חולין סז): בָּעֵי רַב יוֹסֵף, פֵּרְשָׁה לַאֲוִיר הָעוֹלָם מַהוּ. וְכָל שֶׁכֵּן שֶׁהוּא נָח עַל הַכֵּלִים וְעַל הָאָרֶץ לְמֵרָחוֹק בְּכָל בֵּית הָאוֹצָר כָּל הַיּוֹם תָּדִיר, וְקָרֵינָא בֵּהּ "שֶׁרֶץ הַשֹּׁרֵץ עַל הָאָרֶץ" (ויקרא י"א:מ"ב). אֲבָל הַמִּין הַהוּא יַתּוּשׁ שְׁמוֹ, וְנַעֲשֶׂה בַּיַּיִן כִּדְאָמְרִינַן בָּאַגָּדָה שֶׁל טִיטוֹס הָרָשָׁע (ויק"ר כב ג). וְהַיַּבְחוּשִׁים שֶׁהֻזְכְּרוּ כָּאן מִין שֶׁטָּמוּן בַּמַּיִם, וּבוֹחֲשִׁין אוֹתוֹ בְּכַף וּמוֹצִיאִין אוֹתוֹ, מִלְּשׁוֹן (אין) בּוֹחֲשִׁין אֶת הַשָּׁתִית בְּשַׁבָּת (שבת קנו). וּבַגְּמָרָא דִּזְבָחִים פֶּרֶק שֵׁנִי (כב) אָמַר: כָּל הַמַּשְׁלִים לְמֵי מִקְוֶה מַשְׁלִים לְמֵי כִיּוֹר, לִרְבִיעִית אֵין מַשְׁלִים. וְשָׁאֲלוּ: אִי לְמַעוּטֵי יַבְחוּשִׁים אֲדֻמִּים? אֲפִלּוּ בְּעֵינַיְהוּ נַמִּי, דְּתַנְיָא: רַשְׁבָּ"ג אוֹמֵר, כֹּל שֶׁתְּחִלָּתוֹ מִן הַמַּיִם מַטְבִּילִין בּוֹ, שֶׁהוּא מִין שֶׁתְּחִלָּתוֹ מִן הַמַּיִם. וְכֵן נַמִּי נִמְצָאִים בְּשִׁמְרֵי יַיִן תָּדִיר תּוֹלָעִים לְבָנִים קְטַנִּים שֶׁהֵם נִבְרָאִים מִגַּסּוּת הַיַּיִן, וּמְסַנְּנִין אוֹתָן. וְרָאִיתִי בְּפֵרוּשָׁיו שָׁם שֶׁכָּתַב: יַבְחוּשִׁים אֲדֻמִּים כְּמִין יַתּוּשִׁים בְּלֹא כְּנָפַיִם, כְּדֶרֶךְ שֶׁגְּדֵלִים בְּשׁוּלֵי חָבִיּוֹת יַיִן שֶׁלָּנוּ מִבַּחוּץ. יַבְחוּשִׁים דַּקִּים אַף כֵּן נִבְרְאוּ מִן הַמַּיִם. וְאוּלַי בְּכָךְ נִתְכַּוֵּן בְּכָאן לְמִין שֶׁאֵין לוֹ כְּנָפַיִם וְאֵינוֹ נִפְרָשׁ מִן הַמַּיִם אֶלָּא עַל יְדֵי סִנּוּן, וְגַם הֵם בְּאוֹתוֹ שֵׁם הַלַּעַז הֵם נִקְרָאִים אֵצֶל הָרַב. אֲבָל בְּפֵרוּשׁ מַסֶּכֶת חֻלִּין (חולין ס"ז) כָּתַב: יַבְחוּשִׁים כְּמוֹ יַתּוּשִׁים דַּקִּים הַנִּמְצָאִים בְּמַרְתְּפוֹת שֶׁל יַיִן. וְהַכְּלָל שֶׁהוּא מִין שֶׁאֵינוֹ שׁוֹרֵץ עַל הָאָרֶץ כְּלָל:
@57 **וְאֶת אֵלֶּה תְּשַׁקְּצוּ מִן הָעוֹף** - לֹא נֶאֶסְרוּ מִכָּל הָעוֹפוֹת אֶלָּא אֵלּוּ הַנִּזְכָּרִים בְּפָרָשָׁה זוֹ בִּלְבַד עִם מִינֵיהֶם, כְּאוֹתָן שֶׁנֶּאֱמַר בָּהֶם "לְמִינוֹ" וּ"לְמִינָהּ". כִּי הַכָּתוּב לֹא הִזְכִּיר סִימָן בְּעוֹף טָמֵא לְאִסּוּר אוֹ בְּטָהוֹר לְהֶתֵּר, אֲבָל אָמַר "וְאֶת אֵלֶּה תְּשַׁקְּצוּ מִן הָעוֹף", לֹא אֲחֵרִים מִלְּבַד אֵלֶּה. וְכֵן בַּשְּׁרָצִים הַמְּטַמְּאִים שֶׁהִזְכִּירָם בִּפְרָט (להלן פסוקים כט-ל), אֵינָן בַּדִּין הַזֶּה בִּלְתִּי אֵלֶּה הַנְּקוּבִים בַּפָּרָשָׁה בְּשֵׁמוֹת. וְרַבּוֹתֵינוּ לָמְדוּ סִימָנִים בָּעוֹפוֹת (חלין נט), וְהֵן לְהַכִּיר בָּהֶן שֶׁאֵין בַּעַל אוֹתָן הַסִּימָנִין מִן הַמִּינִין הָאֵלֶּה הָאֲסוּרִים. וְהַסִּימָן הַגָּדוֹל בָּעוֹפוֹת הִיא הַדְּרִיסָה, שֶׁכָּל עוֹף הַדּוֹרֵס לְעוֹלָם טָמֵא, כִּי הַתּוֹרָה הִרְחִיקַתְהוּ מִפְּנֵי שֶׁדָּמוֹ מְחֻמָּם לְאַכְזָרִיּוּתוֹ וְשָׁחוֹר וְגַס, וּמוֹלִיד הַמְּרֵרָה הַשְּׂרוּפָה הַשְּׁחַרְחֹרֶת, וְנוֹתֵן אַכְזָרִיּוּת בַּלֵּב. וְאֵין בְּכָל הָעוֹלָם עוֹף שֶׁיִּדְרֹס מִלְּבַד הַנִּזְכָּרִים בַּפָּרָשָׁה. וְהִנֵּה כָּל עוֹף שֶׁיִּדְרֹס נֵדַע שֶׁהוּא מֵאֵלּוּ הַנִּזְכָּרִים, וְאִם בְּיָדוּעַ שֶׁאֵינוֹ דּוֹרֵס וַדַּאי מֻתָּר, שֶׁאֵין בְּכָל הָאֲסוּרִים עוֹף שֶׁאֵינוֹ דּוֹרֵס זוּלָתִי אֶחָד, וְהוּא פֶּרֶס אוֹ עָזְנִיָּה. וְלֹא חָשׁוּ לוֹ חֲכָמִים מִפְּנֵי שֶׁאֵינוֹ מָצוּי בַּיִּשּׁוּב (חולין סב), אֶלָּא בַּמִּדְבָּרוֹת הוּא שׁוֹכֵן תָּמִיד. וְאוּלַי מִפְּנֵי שֶׁהוּא שׁוֹכֵן בָּחֳרָבוֹת דָּמוֹ נִשְׂרָף וְרַע כַּדּוֹרְסִין, וַאֲסָרַתּוּ תּוֹרָה עִמָּהֶם. וְעוֹד מָנוּ חֲכָמִים בַּסִּימָנִין, שֶׁאִם נִמְצָא עוֹף שֶׁיֵּשׁ לוֹ אֶצְבַּע יְתֵרָה וְזֶפֶק וְקֻרְקְבָן נִקְלָף, בְּיָדוּעַ שֶׁטָּהוֹר הוּא, כִּי יָדוּעַ לָהֶם שֶׁאֵינוֹ דּוֹרֵס. אֲבָל כְּשֶׁיֵּשׁ בּוֹ שְׁנֵי סִימָנִין מִן הַשְּׁלֹשָׁה הַנִּזְכָּרִים נֶאֱסֹר אוֹתוֹ, כִּי הָעוֹרֵב יֵשׁ בּוֹ אֶצְבַּע יְתֵרָה וְקֻרְקְבָן נִקְלָף, וְאָנוּ חוֹשְׁשִׁין לוֹ וּלְמִינָיו שֶׁהֵם כֻּלָּם בַּעֲלֵי שְׁנֵי סִימָנִין. וְאֵין צָרִיךְ לוֹמַר שֶׁאִם לֹא הָיָה לוֹ אֶלָּא סִימָן אֶחָד מִן הַשְּׁלֹשָׁה הָאֵלּוּ הַנִּזְכָּרִים שֶׁנֶּאֱסֹר אוֹתוֹ, כִּי שְׁאָר הָעוֹפוֹת הָאֲסוּרִין כֻּלָּן כָּךְ הֵם בְּסִימָן אֶחָד, בִּלְתִּי הַנֶּשֶׁר שֶׁאֵין בּוֹ אֶחָד מִכָּל אֵלּוּ הַשְּׁלֹשָׁה. וְעִנְיַן הַדְּרִיסָה הוּא הַצָּד צַיִד, שֶׁיִּרְדֹּף הָעוֹפוֹת וְיִתְפְּשֵׂם חַיִּים וְיִדְרְסֵם בְּיָדָיו וְיֹאכַל אוֹתָם, כַּאֲשֶׁר יַעֲשֶׂה הַנֵּץ הַגַּס הַנִּקְרָא אסטו"ר וְהַנֵּץ הַדַּק הַנִּקְרָא אשפרוי"ר בְּלַעַ"ז, וּבַעֲרָבִי ביץ. וְזֶה מִשְׁפַּט הָעוֹפוֹת בְּאִסּוּרָם וְהֶתֵּרָם עַל הַדֶּרֶךְ הַנָּכוֹן וְהַמִּתְחַוֵּר בַּגְּמָרָא, וַאֲשֶׁר חֲקַרְנוּהוּ וּמְצָאנוּהוּ כֵּן בִּבְדִיקַת הָעוֹפוֹת. וְהִנֵּה טַעַם הָאִסּוּר בָּעוֹפוֹת מִפְּנֵי אַכְזָרִיּוּת תּוֹלְדֹתָם. וְהַבְּהֵמוֹת יִתָּכֵן שֶׁיִּהְיוּ כֵן מִפְּנֵי שֶׁאֵין בְּבַעֲלֵי הַגֵּרָה וְהַפַּרְסָה הַשְּׁסוּעָה דּוֹרֵס, וְהַשְּׁאָר כֻּלָּם יִטְרֹפוּ. וְהִנֵּה נִמְצָא בְּתוֹלְדֹתָם שִׁנּוּי מַה שֶׁהִזְכִּירוּ חֲכָמִים (ע"ז לה) שֶׁכָּל חֲלֵב הַטְּהוֹרִים עוֹמֵד וַחֲלֵב הַטְּמֵאִים כֻּלָּם אֵינֶנּוּ נִקְפָּא וְלֹא יִתְגַּבֵּן לְעוֹלָם, וְהִנֵּה הֵם מְשֻׁנִּים. וְיִתָּכֵן מִזֶּה שֶׁיַּזִּיקוּ בְּאֵבְרֵי הַזֶּרַע, וְיִהְיֶה הַזֶּרַע הַמִּתְאַסֵּף מִן הַלֵּחָה שֶׁבָּהֶם קָרָה וְלַחָה, וְלֹא תּוֹלִיד כְּלָל אוֹ לֹא תּוֹלִיד בְּטוֹב וְנָכוֹן. מִלְּבַד שֶׁיֵּשׁ בַּמֻּתָּרִים טוֹבָה יְדוּעָה בְּדֶרֶךְ הָרְפוּאוֹת. וְרָאִיתִי בִּקְצָת סִפְרֵי הַנִּסְיוֹנוֹת שֶׁחֲלֵב הַחֲזִיר אִם יִינַק הַיּוֹנֵק מִמֶּנּוּ יִהְיֶה אוֹתוֹ הַנַּעַר מְצֹרָע. וְזֶה לְאוֹת שֶׁיֵּשׁ בְּכֻלָּם סְגֻלּוֹת רָעוֹת מְאֹד:
@64 **שֶׁרֶץ הָעוֹף** - הֵן הַדַּקִּין הַנְּמוּכִים וְרוֹחֲשִׁין עַל הָאָרֶץ, כְּגוֹן זְבוּבִין וּצְרָעִין וְיַתּוּשִׁין וַחֲגָבִים. לְשׁוֹן רַשִׁ"י (רש"י על ויקרא י"א:כ'). וְאֵינֶנּוּ נָכוֹן אֶצְלִי, כִּי לֹא יִקָּרֵא הָעוֹף שֶׁרֶץ בַּעֲבוּר קָטְנוֹ, וְלֹא יִהְיֶה שְׁמוֹ עוֹף סְתָם בַּעֲבוּר גֹּדֶל גּוּפוֹ. וְהָעֲטַלֵּף קְטַן הָרַגְלַיִם, וְרַבִּים מִמִּינֵי הָאַרְבֶּה אֲשֶׁר רַגְלָיו גְּדוֹלִים מִמֶּנּוּ, וְלָמָּה לֹא יִקָּרֵא שֶׁרֶץ הָעוֹף כָּהֵם? אֲבָל שֶׁרֶץ הָעוֹף פֵּרוּשׁוֹ בְּצִדּוֹ "הַהוֹלֵךְ עַל אַרְבַּע", כִּי כָל עוֹף שֶׁיֵּלֵךְ עַל שְׁנֵי רַגְלַיִם צַוָּארוֹ זָקוּף וְרֹאשׁוֹ לְמַעְלָה, וְסוֹמֵךְ עַל כְּנָפָיו וּמְעוֹפֵף תָּמִיד, וְלָכֵן יִקָּרֵא עוֹף כָּנָף וְעוֹף סְתָם. אֲבָל בַּעֲלֵי אַרְבַּע רַגְלַיִם הוֹלְכִים נְמוּכִים וְצַוָּארָם וְרֹאשָׁם לְמַטָּה כַּשְּׁרָצִים, וּלְכָךְ יִקָּרְאוּ שֶׁרֶץ הָעוֹף, כַּאֲשֶׁר פֵּרַשְׁתִּי בְּסֵדֶר בְּרֵאשִׁית (א כ). וְכֵן חָזַר כָּאן וּפֵרֵשׁ: "כֹּל שֶׁרֶץ הָעוֹף אֲשֶׁר לוֹ אַרְבַּע רַגְלָיִם שֶׁקֶץ הוּא לָכֶם". וּפֵרוּשׁוֹ כְּאוֹמֵר: כָּל שֶׁרֶץ הָעוֹף אֲשֶׁר לוֹ אַרְבַּע רַגְלַיִם בִּלְבַד וְאֵין לוֹ כְּרָעַיִם הַנִּזְכָּרִים, שֶׁקֶץ הוּא לָכֶם. וּמִדְרָשׁוֹ בְּתוֹרַת כֹּהֲנִים (פרק ה י): רַבִּי אוֹמֵר: "וְכֹל שֶׁרֶץ הָעוֹף אֲשֶׁר לוֹ אַרְבַּע רַגְלָיִם" - הָא אִם יֵשׁ לוֹ חָמֵשׁ, טָהוֹר. וְהִנֵּה אֵין בַּפָּרָשָׁה הַזּוֹ בְּשֶׁרֶץ הָעוֹף אֶלָּא מִצְוַת עֲשֵׂה, אֲבָל בְּמִשְׁנֵה הַתּוֹרָה (דברים יד יט) נֶאֶמְרָה בּוֹ אַזְהָרָה: "וְכֹל שֶׁרֶץ הָעוֹף טָמֵא הוּא לָכֶם לֹא יֵאָכֵלוּ". מִשָּׁם לוֹקִים עָלָיו.
@68 **וּלְאֵלֶּה תִּטַּמָּאוּ** - לְאֵלֶּה הָעֲתִידִין לְהֵאָמֵר לְמַטָּה בָּעִנְיָן תִּטַּמָּאוּ (רש"י כאן) (ת"כ). כָּאן לִמֶּדְךָ שֶׁנִּבְלַת בְּהֵמָה טְמֵאָה מְטַמְּאָה, וּבָעִנְיָן שֶׁבְּסוֹף הַפָּרָשָׁה (ויקרא י"א:ל"ט) פֵּרֵשׁ עַל בְּהֵמָה טְהוֹרָה. לְשׁוֹן רַשִׁ"י (רש"י על ויקרא י"א:כ"ו) (בפסוק כו). וְאִם כֵּן, לָמָּה חִלְּקָן הַכָּתוּב וְלָמָּה פֵּרַט בָּהֶם? הָיָה רָאוּי שֶׁיֹּאמַר: "כָּל הַנּוֹגֵעַ בְּנִבְלַת בְּהֵמָה יִטְמָא עַד הָעֶרֶב, וְכָל הַנּוֹשֵׂא מִנִּבְלָתָהּ יְכַבֵּס בְּגָדָיו וְיִטְמָא עַד הָעֶרֶב". וְהַנָּכוֹן כִּי כָּאן הִזְכִּיר "בְּנִבְלָתָם" סְתָם וְלֹא הִזְכִּיר בָּהֶם מִיתָה, לְלַמֵּד שֶׁאֵין בָּהֶם שְׁחִיטָה, וְכָל הַנּוֹגֵעַ בָּהֶן בִּזְמַן שֶׁאֵינָם חַיִּים יִטְמָא. אֲבָל שָׁם אָמַר "וְכִי יָמוּת מִן הַבְּהֵמָה", לוֹמַר שֶׁאִם נִשְׁחֲטָה אֵינָהּ מְטַמְּאָה. וְעִנְיַן הַפָּרָשָׁה, הִזְכִּיר "וּלְאֵלֶּה תִּטַּמָּאוּ" לוֹמַר שֶׁאֵין בַּנִּזְכָּרִים בַּדָּגִים וּבָעוֹפוֹת וּבַחֲגָבִים הַטֻּמְאָה הַזּוֹ, רַק לְאֵלֶּה אֲשֶׁר יַזְכִּיר, וְהֵם הַבְּהֵמָה אֲשֶׁר אֵינֶנָּה שׁוֹסַעַת שֶׁסַע וּמַעֲלַת גֵּרָה. וְאָמַר (בפסוק כו) "טְמֵאִים הֵם לָכֶם כָּל הַנֹּגֵעַ בָּהֶם יִטְמָא" בַּטֻּמְאָה הַנִּזְכֶּרֶת. וְחָזַר וְאָמַר (בפסוקים כז-כח) שֶׁכָּל הוֹלֵךְ עַל כַּפָּיו בַּחַיָּה גַּם כֵּן יְטַמֵּא הַנֹּגֵעַ עַד הָעֶרֶב, וְהַנּוֹשֵׂא יוֹסִיף לְכַבֵּס בְּגָדָיו. וְכֵן "וְזֶה לָכֶם הַטָּמֵא בַּשֶּׁרֶץ" (ויקרא י"א:כ"ט) עַל הֶעָתִיד לְהַזְכִּיר. וְנִשְׁתַּבֵּשׁ רַבִּי אַבְרָהָם בְּכָאן. וְהִנֵּה לְמַעְלָה בְּעִנְיַן אִסּוּר הַמַּאֲכָל הִזְכִּיר הַבְּהֵמָה שֶׁאֵינָהּ שׁוֹסַעַת שֶׁסַע וּמַעֲלַת גֵּרָה, וְלֹא הִזְכִּיר הוֹלֵךְ עַל כַּפָּיו בַּחַיָּה. אוּלַי בַּעֲבוּר שֶׁאֵין דֶּרֶךְ לְאָכְלָם לֹא פֵּרַט בָּהֶם, וְהִנִּיחָם בְּתוֹךְ הַכְּלָל שֶׁאָמַר (ויקרא י"א:ג') שֶׁנֹּאכַל הַבְּהֵמָה הַמַּפְרֶסֶת פַּרְסָה וְשֹׁסַעַת שֶׁסַע וּמַעֲלַת גֵּרָה וְלֹא אַחֶרֶת, וְחַיָּה בִּכְלַל בְּהֵמָה, כְּמוֹ שֶׁנֶּאֱמַר "זֹאת הַבְּהֵמָה אֲשֶׁר תֹּאכֵלוּ, אַיָּל וּצְבִי וְיַחְמוּר" (דברים יד ד-ה). וּלְרַבּוֹתֵינוּ בְּתוֹרַת כֹּהֲנִים בַּפָּרָשָׁה כֻּלָּהּ מִדְרָשִׁים. "לְכָל הַבְּהֵמָה טְמֵאִים הֵם לָכֶם" (ויקרא י"א:כ"ו) - בְּאֵבֶר מִן הַחַי (פרשה ד ב). "וְכֹל הוֹלֵךְ עַל כַּפָּיו" - בְּאֵבֶר מִן הַמֵּת (פרק ו ו). כִּי יַאֲרִיךְ הַכָּתוּב וְיַזְכִּיר בָּהֶם טֻמְאוֹת רַבּוֹת, לִרְמֹז שֶׁיְּטַמְּאוּ כֻּלָּם וּמִקְצָתָם, בְּמִיתַת כָּל הַגּוּף וּבְמִיתַת הָאֵבֶר מִמֶּנּוּ כְּשֶׁיִּתָּלֵשׁ מִן הַגּוּף הַחַי:
@68 וְטַעַם **יִטְמָא עַד הָעָרֶב** בְּכָל הַפָּרָשָׁה, כִּי בָּעֶרֶב יִטְהַר אִם רָחַץ בְּשָׂרוֹ בַּמָּיִם. אֲבָל קִצֵּר בָּרְחִיצָה בַּעֲבוּר שֶׁהִזְכִּיר (ויקרא י"א:כ"ה) כִּבּוּס בִּגְדֵי הַנּוֹשֵׂא שֶׁהוּא הַטְּבִילָה, וְכָל שֶׁכֵּן שֶׁיִּרְחַץ גּוּפוֹ. וּכְשֶׁהִשְׁלִים לְהַזְכִּיר כָּל הַטֻּמְאוֹת בִּנְבֵלוֹת וּבִשְׁרָצִים, הִזְכִּיר הַטְּבִילָה בַּכֵּלִים: "בַּמַּיִם יוּבָא וְטָמֵא עַד הָעֶרֶב וְטָהֵר" (ויקרא י"א:ל"ב), וְהוּא הַדִּין לָאָדָם כִּי מִמֶּנּוּ נִלְמוֹד. וּבְפָרָשָׁה אַחֶרֶת (ויקרא י"ז:ט"ו) פֵּרֵשׁ: "וְכָל נֶפֶשׁ אֲשֶׁר תֹּאכַל נְבֵלָה וּטְרֵפָה בָּאֶזְרָח וּבַגֵּר וְכִבֶּס בְּגָדָיו וְרָחַץ בַּמַּיִם וְטָמֵא עַד הָעֶרֶב", וְהִזְכִּיר גַּם הָעֹנֶשׁ: "וְאִם לֹא יְכַבֵּס וּבְשָׂרוֹ לֹא יִרְחָץ וְנָשָׂא עֲוֹנוֹ" (שם פסוק טז). וְהוּא כְּלָל לְכָל טֻמְאַת הַנְּבֵלוֹת, וּמִמֶּנּוּ נִלְמוֹד לַשְּׁרָצִים. וּכְבָר הֻזְכְּרָה כָּאן הָרְחִיצָה בַּשְּׁרָצִים כְּמוֹ שֶׁכָּתַבְתִּי. וְהֶחְמִיר הַכָּתוּב בַּמַּשָּׂא יוֹתֵר מִן הַמַּגָּע בְּכִבּוּס הַבְּגָדִים, מִפְּנֵי שֶׁדֶּרֶךְ הַנּוֹגְעִים לִיגַּע בְּיָדוֹ בְּנַחַת, אֲבָל הַנּוֹשֵׂא אוֹתָם דֶּרֶךְ מַשָּׂא שֶׁיִּכְבַּד עָלָיו, וּבְגָדָיו יְסַיְּעוּ אוֹתוֹ בְּרֹב פְּעָמִים.
@76 **וְכֹל אֲשֶׁר יִפֹּל עָלָיו מֵהֶם בְּמֹתָם יִטְמָא מִכָּל כְּלִי עֵץ** - הַקָּרוֹב אֵלַי בָּזֶה כִּי "מֵהֶם בְּמֹתָם" יִרְמֹז לְכָל הַנִּזְכָּרִים לְמַעְלָה בִּבְהֵמָה טְמֵאָה וְשֶׁרֶץ וְחַיָּה, כִּי לָמָּה יַזְכִּיר טֻמְאַת הַכֵּלִים וְהַבְּגָדִים בַּשְּׁרָצִים בְּיִחוּד וְהִיא נוֹהֶגֶת גַּם בַּנְּבֵלוֹת? וְכֵן כָּל הַמִּשְׁפָּטִים אֲשֶׁר יַזְכִּיר בְּהֶכְשֵׁר הָאֳכָלִין כֻּלָּן שָׁוִין בְּכָל הַטֻּמְאוֹת, וּבִכְלָלָן דִּבֵּר הַכָּתוּב. וְאַל יִקְשֶׁה עָלֶיךָ הֱיוֹת "בָּהֶם בְּמֹתָם" שֶׁבַּכָּתוּב הָרִאשׁוֹן בַּשְּׁרָצִים וּ"מֵהֶם בְּמוֹתָם" בַּכָּתוּב הַשֵּׁנִי בְּכֻלָּן, כִּי כֵן בִּמְקוֹמוֹת רַבִּים. וְיִתָּכֵן לוֹמַר שֶׁהִמְתִּין הַכָּתוּב עַד שֶׁהִזְכִּיר כָּל הַטְּמֵאִים בַּבְּהֵמָה וּבַחַיָּה וּבַשְּׁרָצִים, וְאַחַר כָּךְ בַּסּוֹף הִזְכִּיר הַטֻּמְאָה בַּכֵּלִים בָּאֶחָד אֲשֶׁר יַשְׁלִים בּוֹ לִלְמֹד מִמֶּנּוּ לְכָל הָאֲחֵרִים, כִּי דַּעַת רַבּוֹתֵינוּ (חגיגה יא) שֶׁיִּהְיֶה "מֵהֶם בְּמוֹתָם" בַּשְּׁרָצִים, וּמִמֶּנּוּ יִלְמְדוּ עַל הַשֶּׁרֶץ שֶׁהוּא מְטַמֵּא בְּכַעֲדָשָׁה. וְכֵן נָהַג הַכָּתוּב בַּטְּבִילָה שֶׁהִזְכִּיר (בפסוק זה) בְּסוֹף כָּל הַטֻּמְאוֹת טֻמְאַת הַכֵּלִים וּטְבִילָתָן, וּמִמֶּנּוּ נִלְמֹד לְאָדָם וְכֵלִים בְּכָל שְׁאָר הַטֻּמְאוֹת הַנִּזְכָּרוֹת:
@76 **בַּמַּיִם יוּבָא** - וְאַף לְאַחַר טְבִילָתוֹ טָמֵא הוּא לִתְרוּמָה עַד הֶעֱרֵב הַשֶּׁמֶשׁ, וְאַחַר כָּךְ הוּא נִטְהָר בְּהֶעֱרֵב שִׁמְשׁוֹ. לְשׁוֹן רַשִׁ"י (רש"י על ויקרא י"א:ל"ב). וּמִדְרָשׁוֹ בְּתוֹרַת כֹּהֲנִים (פרק ח ט): "וְטָמֵא עַד הָעֶרֶב" - יָכוֹל לַכֹּל? תַּלְמוּד לוֹמַר "וְטָהֵר". אִי "וְטָהֵר" יָכוֹל לְכָל דָּבָר? תַּלְמוּד לוֹמַר "וְטָמֵא עַד הָעֶרֶב". הָא כֵּיצַד? טָהוֹר לְחֻלִּין מִבְּעוֹד יוֹם, וְלִתְרוּמָה מִשֶּׁתֶּחְשַׁךְ. וְשִׁעוּר הַכָּתוּב לְפִי הַמִּדְרָשׁ: בַּמַּיִם יוּבָא וְטָהֵר וְטָמֵא עַד הָעֶרֶב. וְעַל דֶּרֶךְ הַפְּשָׁט: בַּמַּיִם יוּבָא וְטָמֵא עַד הָעֶרֶב וְטָהֵר בָּעֶרֶב. וְהִנֵּה הִזְכִּיר הַכָּתוּב בְּכָל הַפָּרָשִׁיּוֹת "עַד הָעֶרֶב", כִּי יִתְפֹּס הַטָּהֳרָה לִתְרוּמַת הַקֳּדָשִׁים, כְּמוֹ שֶׁאָמַר (להלן כב ו ז): "וְטָמֵא עַד הָעָרֶב וְלֹא יֹאכַל מִן הַקֳּדָשִׁים כִּי אִם רָחַץ בְּשָׂרוֹ בַּמָּיִם. וּבָא הַשֶּׁמֶשׁ וְטָהֵר וְאַחַר יֹאכַל מִן הַקֳּדָשִׁים כִּי לַחְמוֹ הוּא". אֲבָל הַטַּהֲרָה לְחֻלִּין אוֹ לְמַעֲשֵׂר הִיא בִּטְבִילָה בִּלְבַד, וְלֹא יַזְכִּירֶנָּה בְּכָאן, כִּי אֵינֶנּוּ מְצַוֶּה לְהִטָּהֵר לְחֻלִּין, וְאִם רָצָה אוֹכְלָן בְּטֻמְאָה.
@78 **מִכָּל הָאֹכֶל אֲשֶׁר יֵאָכֵל** פֵּרֵשׁ רַשִׁ"י (רש"י על ויקרא י"א:ל"ד) הַכָּתוּב הַזֶּה כְּפִי מִדְרָשׁוֹ וְלָמַד בּוֹ דְּבָרִים הַרְבֵּה: לָמַדְנוּ שֶׁאֵין אֹכֶל מֻכְשָׁר וּמְתֻקָּן וְכוּ'. וְעוֹד לָמְדוּ רַבּוֹתֵינוּ מִכָּאן שֶׁאֵין וְלַד הַטֻּמְאָה מְטַמֵּא כֵלִים, שֶׁכָּךְ שָׁנִינוּ וְכוּ'. וְלָמַדְנוּ עוֹד עַל בִּיאַת מַיִם שֶׁאֵינָהּ מַכְשֶׁרֶת וְכוּ'. וּבִכְלָלָם אָמַר: וְלָמַדְנוּ עוֹד שֶׁאֵין אֹכֶל מְטַמֵּא אֲחֵרִים אֶלָּא אִם כֵּן יֵשׁ בּוֹ כַּבֵּיצָה, שֶׁנֶּאֱמַר "יֵאָכֵל" - אֹכֶל הַנֶּאֱכָל בְּבַת אַחַת, וְשִׁעֲרוּ חֲכָמִים אֵין בֵּית הַבְּלִיעָה מַחְזִיק יוֹתֵר מִבֵּיצַת תַּרְנְגֹלֶת. זֶה לְשׁוֹן הָרַב. וְיֵשׁ בּוֹ קִצּוּר, כִּי הַכָּתוּב הַזֶּה בְּטֻמְאַת הָאֳכָלִין עַצְמָהּ הוּא, וְאֵינוֹ מְדַבֵּר בְּטֻמְאָתָן לַאֲחֵרִים. אֲבָל הוֹצִיא הָרַב זֶה מִמַּה שֶׁאָמְרוּ בְּתוֹרַת כֹּהֲנִים (פרק ט א): "אֹכֶל יִטְמָא" - מְלַמֵּד שֶׁמְּטַמֵּא בְּכָל שֶׁהוּא. יָכוֹל יְטַמֵּא לַאֲחֵרִים בְּכָל שֶׁהוּא? תַּלְמוּד לוֹמַר "אֲשֶׁר יֵאָכֵל" - הָא אֵינוֹ מְטַמֵּא אֶלָּא בְּכַבֵּיצָה. וּכְבָר חָלְקוּ עַל הָרַב וְהֵבִיאוּ רְאָיוֹת שֶׁאֵין הָאֳכָלִין מְקַבְּלִין טֻמְאָה מִן הַתּוֹרָה כְּלָל אֶלָּא בְּכַבֵּיצָה, וְהַמִּדְרָשׁ בְּתוֹרַת כֹּהֲנִים אַסְמַכְתָּא מִדִּבְרֵיהֶם, שֶׁהֵם הוֹסִיפוּ שֶׁיְּקַבְּלוּ טֻמְאָה בְּכָל שֶׁהוּא. וְעִקַּר הַכָּתוּב יִדָּרֵשׁ בְּמָה שֶׁאָמַר שָׁם: "הָאֹכֶל" - לְהוֹצִיא אָכְלֵי בְּהֵמָה, "מִכָּל הָאֹכֶל" - לְהָבִיא אָכְלֵי בְּהֵמָה שֶׁחָשַׁב עֲלֵיהֶם לְמַאֲכַל אָדָם, "אֲשֶׁר יֵאָכֵל" - פְּרָט לְאֹכֶל סָרוּחַ.
@79 **תַּנּוּר וְכִירַיִם יֻתָּץ** - בָּא הַכָּתוּב לְלַמֵּד שֶׁיִּהְיֶה דִּין הַתַּנּוּר וְהַכִּירַיִם, שֶׁהֵן עֲשׂוּיִין מִן הַטִּיט וּמַסִּיקִין הָאוּר בְּתוֹכָן וְאוֹפִין הַפַּת בָּהֶן בְּחִבּוּרָן לַקַּרְקַע, כְּדִין כְּלֵי חֶרֶשׂ שֶׁהֵן הַקְּדֵרוֹת וְהַקִּיתוֹנִיּוֹת הָאֲפוּיִין בַּכִּבְשָׁן וְהֵן מִטַּלְטְלִין, שֶׁאַף הֵם יְקַבְּלוּ טֻמְאָה וְאֵין לָהֶם טַהֲרָה בְּמִקְוֶה. וְאָמַר "יֻתָּץ" וְלֹא אָמַר יִשָּׁבֵר, לְלַמֵּד שֶׁאֵין צָרִיךְ לְשַׁבְּרָן עַד שֶׁלֹּא יִמָּצֵא בִּמְכִתָּתוֹ חֶרֶס לַחְתּוֹת אֵשׁ מִיָּקוּד, אֶלָּא יֶהֶרְסֵם וְלֹא יִבְנֵם לַעֲשׂוֹת מְלַאכְתָּם. וּלְלַמֵּד עוֹד שֶׁהֵם מְקַבְּלִין טֻמְאָה אַף עַל פִּי שֶׁמְּחֻבָּרִין בָּאָרֶץ, וְיִתֹּץ אֲשֶׁר בָּנָה. כִּי עִנְיַן נְתִיצָה הֲרִיסַת בִּנְיָן, כְּמוֹ "וַתִּתְצוּ הַבָּתִּים" (ישעיהו כ"ב:י'), "וְנָתַץ אֶת הַבַּיִת" (ויקרא י"ד:מ"ה):
@80 **אַךְ מַעְיָן וּבוֹר מִקְוֵה מַיִם יִהְיֶה טָהוֹר** - יֹאמַר שֶׁאֵין הַמַּיִם בַּמִּקְוֶה מְקַבְּלִין טֻמְאָה בְּחִבּוּרָם לַקַּרְקַע אִם יִפֹּל בָּהֶן הַטֻּמְאָה. וְאָמַר "וְנֹגֵעַ בְּנִבְלָתָם יִטְמָא" - שִׁעוּרוֹ: וּמַיִם אֲשֶׁר נוֹגֵעַ בְּנִבְלָתָם יִטְמָא, כִּי הַמַּיִם הַתְּלוּשִׁים אֲשֶׁר יִגְּעוּ בָּהֶם בְּנִבְלָתָם יִטַּמְּאוּ, כִּי בַּמִּקְוֶה לֹא יִגְּעוּ הַמַּיִם בְּנִבְלָתָם, אֲבָל נִבְלָתָם יִפֹּל אֶל תּוֹכוֹ. וְהִזְכִּיר הַמַּיִם בִּלְשׁוֹן יָחִיד כְּדֶרֶךְ "מֵי נִדָּה לֹא זֹרַק עָלָיו" (במדבר י"ט, י"ג). אוֹ שֶׁיֹּאמַר הַכָּתוּב "וְכָל נוֹגֵעַ בְּנִבְלָתָם יִטְמָא", וְהַכַּוָּנָה לְרַבּוֹת הַמַּיִם וְהַמַּשְׁקִים הַנִּזְכָּרִים (ויקרא י"א:ל"ד). וְעַל הַכְּלָל, כִּי בָּא זֶה לְלַמֵּד עַל הַמַּיִם שֶׁהֵם מְקַבְּלִין טֻמְאָה בְּתָלוּשׁ וְלֹא בִּמְחֻבָּר, שֶׁלֹּא הֻזְכַּר זֶה עַד עַתָּה. וּבְתוֹרַת כֹּהֲנִים (פרשה ט' ו') רַבִּי יוֹסֵי הַגְּלִילִי אוֹמֵר: "וְנֹגֵעַ בְּנִבְלָתָם יִטְמָא" - בְּמַגָּע הֵן מְטַמְּאִין וְלֹא בְּמַשָּׂא. וְגַם זֶה יִתָּכֵן שֶׁיַּחְזֹר אֶל כָּל הָעִנְיָנִים הַנִּזְכָּרִים, וְיֹאמַר שֶׁאֵין לַשְּׁרָצִים רַק טֻמְאַת מַגָּע. וְעוֹד לְרַבּוֹתֵינוּ בַּכָּתוּב הַזֶּה מִדְרָשִׁים בְּיִתּוּר הַלָּשׁוֹן, וְכֻלָּם הֲלָכָה לְמֹשֶׁה מִסִּינַי. וְהִזְכִּיר טַהֲרַת הַמִּקְוֶה וְהַמַּיִם הַמְּחֻבָּרִים בַּשְּׁרָצִים, וְהוּא הַדִּין לִנְבֵלוֹת, אַךְ הִמְתִּין עַד שֶׁהִשְׁלִים לְהַזְכִּיר כָּל מִינֵי הַמְּטַמְּאִין. אוֹ בַּעֲבוּר שֶׁדֶּרֶךְ הַשְּׁרָצִים לָמוּת בְּמַעְיָן וּבוֹר. וּכְבָר הִזְכַּרְתִּי דַּעְתִּי (רמב"ן על ויקרא י"א:ל"ב):
@81 **זֶרַע זֵרוּעַ** - זֶרַע שֶׁל מִינֵי זֵרְעוֹנִים. זֵרוּעַ שֵׁם דָּבָר, "וְיִתְּנוּ לָנוּ מִן הַזֵּרֹעִים" (דניאל א יב). "טָהוֹר הוּא" - לְלַמֶּדְךָ שֶׁלֹּא הֻכְשַׁר וְנִתְקַן לִהְיוֹת אֹכֶל לְקַבֵּל טֻמְאָה עַד שֶׁיָּבֹא עָלָיו מַיִם. לְשׁוֹן רַשִׁ"י (רש"י על ויקרא י"א:ל"ז). וְהִנֵּה לְמַעְלָה הִזְכִּיר הַכָּתוּב (ויקרא י"א:ל"ד) "מִכָּל הָאֹכֶל אֲשֶׁר יֵאָכֵל אֲשֶׁר יָבוֹא עָלָיו מַיִם" לְלַמֵּד עַל הַהֶכְשֵׁר, אֲבָל שָׁם אָמְרוּ שֶׁאֵין הָאֹכֶל מִטַּמֵּא מֵאֲוִיר כְּלִי חֶרֶס אֶלָּא בְּהֶכְשֵׁר מַיִם. וְכָאן הוֹסִיף שֶׁאַף מִן הַשְּׁרָצִים עַצְמָם אֵין מְקַבֵּל טֻמְאָה אֶלָּא בְּהֶכְשֵׁר, כָּךְ מְפֹרָשׁ בְּתוֹרַת כֹּהֲנִים (פרק יא ה). וְיִתָּכֵן עוֹד לוֹמַר כִּי "מִכָּל הָאֹכֶל אֲשֶׁר יֵאָכֵל" הַנִּזְכָּר לְמַעְלָה - הַבָּשָׂר וְהַמַּאֲכָלִים הַנִּזְכָּרִים, וְכָאן אָמַר שֶׁאַף הַזְּרָעִים כַּאֲשֶׁר יוֹצִיאוּ אוֹתָם לִזְרִיעָה יִטַּמְּאוּ בְּהֶכְשֵׁר מַיִם. וְטַעַם הַהֶכְשֵׁר בַּעֲבוּר כִּי לִכְלוּךְ הַשֶּׁרֶץ וְהַמְּטַמְּאִים יִדְבַּק בַּמַּאֲכָלִים בְּלַחוּת וְלֹא כֵן בַּיְּבֵשִׁים. וְעָשְׂתָה הַתּוֹרָה הַרְחָקָה יְתֵרָה לְטַמֵּא הַמֻּכְשָׁרִים בְּמַיִם וְנָגְבוּ שֶׁלֹּא נִתֵּן דְּבָרֵינוּ לְשִׁעוּרִין. וְהִנֵּה גַּם דִּין הַהֶכְשֵׁר נוֹהֵג בְּטֻמְאַת הַנְּבֵלוֹת וְהִזְכִּירוֹ הַכָּתוּב כָּאן לָעִנְיָן שֶׁאָמַרְנוּ:
@84 **וְהָאֹכֵל מִנִּבְלָתָהּ** - עַל דֶּרֶךְ הַפְּשָׁט יְדַבֵּר בָּאוֹכֵל כְּדֶרֶךְ הָאוֹכְלִים, שֶׁנּוֹגֵעַ וְנוֹשֵׂא מַה שֶׁהוּא אוֹכֵל, וְנִטְמָא בְּמַגָּע וּבְמַשָּׂא. וְהֻצְרַךְ לְהַזְכִּיר זֶה שֶׁלֹּא יַעֲלֶה עַל דַּעַת שֶׁתִּהְיֶה טֻמְאָתוֹ יוֹתֵר גְּדוֹלָה בַּעֲבוּר הָאֲכִילָה. וְהִזְכִּיר זֶה בִּבְהֵמָה טְהוֹרָה בַּעֲבוּר שֶׁיִּטְעֶה אָדָם בָּהּ וְיֹאכְלֶנָּה, שֶׁיַּחְשֹׁב שֶׁהִיא שְׁחוּטָה, וְאֵין דֶּרֶךְ לִטְעוֹת כָּךְ בַּמִּינִים הָאֲסוּרִים. וְדֶרֶךְ הַתּוֹרָה לְדַבֵּר בַּהֹוֶה. וּכְפִי מִדְרָשׁוֹ (נדה מ"ב) שֶׁבָּא לִתֵּן שִׁעוּר לַנּוֹשֵׂא וְלַנּוֹגֵעַ כְּדֵי אֲכִילָה, וְהִיא כַּזַּיִת. גַּם כֵּן הִזְכִּיר זֶה בְּנִבְלַת בְּהֵמָה טְהוֹרָה, וְהוּא הַדִּין לַטְּמֵאָה הַנִּזְכֶּרֶת לְמַעְלָה (בפסוקים כ"ד-כ"ה), כִּי הִשְׁלִים כָּאן דִּין הַטֻּמְאוֹת. וְעַל דַּעַת מִדְרַשׁ תּוֹרַת כֹּהֲנִים (בפסוק כ"ו) כָּל טֻמְאוֹת נְבֵלוֹת נִתְרַבּוּ מִכָּאן, וּפָרָשָׁה שֶׁל מַעְלָה (בפסוקים כ"ד-כ"ה) בָּאֵבָרִים הִיא. וּכְבָר הִזְכַּרְתִּי מִזֶּה (רמב"ן על ויקרא י"א:כ"ב):
@85 **וְכָל הַשֶּׁרֶץ הַשֹּׁרֵץ עַל הָאָרֶץ** - טַעַם הַכָּתוּב הַזֶּה, כִּי הִזְכִּיר לְמַעְלָה (בפסוקים כט-ל) הַשְּׁרָצִים לְעִנְיַן הַטֻּמְאָה וּפֵרַט הַטְּמֵאִים, וְלֹא דִּבֵּר שָׁם בְּעִנְיַן אִסּוּר אֲכִילָה כְּלָל. וּלְכָךְ אָמַר עַתָּה "וְכָל הַשֶּׁרֶץ הַשֹּׁרֵץ עַל הָאָרֶץ שֶׁקֶץ הוּא לֹא יֵאָכֵל", לוֹמַר כִּי בְּעִנְיַן הָאֲכִילָה אֵין הֶפְרֵשׁ בֵּינֵיהֶן, שֶׁכֻּלָּן אֲסוּרִין. וְחָזַר וּפֵרַט בָּהֶן וְהִרְבָּה בָּהֶן לָאוִין לְמַלְקִיּוֹת, כְּמוֹ שֶׁהִזְכִּיר רַשִׁ"י:
@91 **לְהַבְדִּיל בֵּין הַטָּמֵא וּבֵין הַטָּהֹר** - שֶׁנַּבְדִּיל בְּכָל הַנִּזְכָּרִים בֵּין הַטְּמֵאִים לַטְּהוֹרִים לְעִנְיַן הַטֻּמְאָה. "וּבֵין הַחַיָּה הַנֶּאֱכֶלֶת" - נִמְשָׁךְ לַנֶּפֶשׁ הַנִּזְכֶּרֶת, וּבֵין נֶפֶשׁ הַחַיָּה הַנֶּאֱכֶלֶת. וְיֹאמַר שֶׁנַּבְדִּיל לְעִנְיַן אֲכִילָה בֵּין נֶפֶשׁ הַחַיָּה הַנֶּאֱכֶלֶת עַל פִּי הַתּוֹרָה בַּמַּיִם וְעַל הָאָרֶץ, וּבֵין הַחַיָּה אֲשֶׁר לֹא תֵאָכֵל בָּהֶם. וּבְתוֹרַת כֹּהֲנִים (סוף פרשת שמיני) אָמְרוּ: חֲכָמִים אוֹמְרִים: "בֵּין הַחַיָּה אֲשֶׁר לֹא תֵאָכֵל" - לִתֵּן אַזְהָרָה לַחַיָּה, וְאִם כֵּן הוּא לָאו. וּלְשׁוֹן רַשִׁ"י (רש"י על ויקרא י"א:מ"ז): "בֵּין הַטָּמֵא וּבֵין הַטָּהֹר" - צָרִיךְ לוֹמַר בֵּין פָּרָה לַחֲמוֹר? וַהֲלֹא כְּבָר מְפֹרָשִׁים הֵן? אֶלָּא בֵּין טְמֵאָה לְךָ לִטְהוֹרָה לְךָ, בֵּין שֶׁנִּשְׁחַט חֶצְיוֹ שֶׁל קָנֶה לְנִשְׁחַט רֻבּוֹ (ת"כ). וְקָתָנֵי הָתָם (פרק יב ז): וְכַמָּה הוּא בֵּין רֻבּוֹ לְחֶצְיוֹ? כִּמְלֹא שַׂעֲרָה. וְלֹא תָּחוּשׁ בָּזֶה מִמַּה שֶׁאָמְרוּ בַּגְּמָרָא (חלין כט): רֹב הַנִּרְאֶה לָעֵינַיִם בָּעֵינַן, שֶׁאֵין פֵּרוּשׁוֹ אֶלָּא לְהוֹצִיא מִדִּבְרֵי הָאוֹמֵר (שם) מֶחְצָה עַל מֶחְצָה כְּרֹב. וּלְכָךְ אָמְרוּ דְּבָעֵי שֶׁיְּהֵא הַשָּׁחוּט רֹב מַמָּשׁ כְּדֵי שֶׁיֵּרָאֶה לָעֵינַיִם, לֹא הַמֶּחְצָה שֶׁנַּחְשֹׁב אוֹתוֹ בְּלִבֵּנוּ וְנֹאמַר רֹב הוּא הַשָּׁחוּט מֵאַחַר שֶׁאֵין בְּמַה שֶׁלֹּא נִשְׁחַט יוֹתֵר מִמֶּנּוּ. אֲבָל כָּל שֶׁיִּשְׁחֲטוּ מִמֶּנּוּ יוֹתֵר מִן הַחֲצִי כָּשֵׁר הוּא, וַאֲפִלּוּ כִּמְלֹא חוּט הַשַּׂעֲרָה, כְּדִמְפֹרָשׁ בְּזוֹ הַבָּרַיְתָא. וְאַף בַּגְּמָרָא כָּךְ הוּא עוֹלֶה.
